(@vid,@bid,1,5,'Y|strong="H3068" llamó|strong="H7121" Dios a|strong="H3068" la luz Día|strong="H3117" , y a|strong="H3068" las tinieblas|strong="H2822" llamó|strong="H7121" Noche|strong="H3915" : y fue|strong="H1961" la tarde|strong="H6153" y la mañana|strong="H1242" el día|strong="H3117" pri­mero.',NULL),
(@vid,@bid,1,6,'Y|strong="H3068" dijo Dios: Haya|strong="H1961" firmamento en|strong="H8432" medio|strong="H8432" de|strong="H4325" las aguas|strong="H4325" , y separe las aguas|strong="H4325" de|strong="H4325" las aguas|strong="H4325" .',NULL),
(@vid,@bid,1,7,'E|strong="H3068" hizo|strong="H6213" Dios el|strong="H5921" firmamento, y|strong="H5921" apartó las|strong="H5921" aguas|strong="H4325" que|strong="H5921" estaban debajo|strong="H8478" del|strong="H5921" firmamento de|strong="H5921" las|strong="H5921" aguas|strong="H4325" que|strong="H5921" estaban sobre|strong="H5921" el|strong="H5921" fir­mamento: y|strong="H5921" fue|strong="H1961" así|strong="H3651" .',NULL),
(@vid,@bid,1,8,'Y|strong="H3068" llamó|strong="H7121" Dios al firmamento Cielo|strong="H8064" : y fue|strong="H1961" la tarde|strong="H6153" y la maña|strong="H1961" ­na el día|strong="H3117" segundo|strong="H8145" .',NULL),
(@vid,@bid,1,9,'Y|strong="H3068" dijo Dios: Júntense|strong="H6960" las aguas|strong="H4325" debajo|strong="H8478" de|strong="H8478" los|strong="H1961" cielos|strong="H8064" en|strong="H8478" un lugar|strong="H4725" , y aparezca|strong="H7200" la porción seca: y fue|strong="H1961" así|strong="H3651" .',NULL),
(@vid,@bid,1,10,'Y|strong="H3068" llamó|strong="H7121" Dios a|strong="H3068" la|strong="H3588" porción seca Tierra|strong="H3004" , y|strong="H3588" a|strong="H3068" la|strong="H3588" reunión de|strong="H3588" las aguas|strong="H4325" llamó|strong="H7121" Mares|strong="H3220" : y|strong="H3588" vio|strong="H7200" Dios que|strong="H3588" era bueno|strong="H2896" .',NULL),
(@vid,@bid,1,11,'Y|strong="H3068" dijo Dios: Produzca|strong="H1877" la|strong="H5921" tierra hierba|strong="H6212" verde, hierba|strong="H6212" que|strong="H5921" dé|strong="H5921" simiente|strong="H2233" , árbol|strong="H6086" de|strong="H5921" fruto|strong="H6529" que|strong="H5921" dé|strong="H5921" fruto|strong="H6529" según|strong="H5921" su género, que|strong="H5921" su simiente|strong="H2233" esté|strong="H1961" en|strong="H5921" él|strong="H5921" , sobre|strong="H5921" la|strong="H5921" tie­rra: y|strong="H5921" fue|strong="H1961" así|strong="H3651" .',NULL),
(@vid,@bid,1,12,'Y|strong="H3068" produjo la|strong="H3588" tierra hierba|strong="H6212" verde, hierba|strong="H6212" que|strong="H3588" da|strong="H2232" simiente|strong="H2233" según su|strong="H3588" género, y|strong="H3588" árbol|strong="H6086" que|strong="H3588" da|strong="H2232" fruto|strong="H6529" , cuya simiente|strong="H2233" está en|strong="H3588" él|strong="H3588" , según su|strong="H3588" género: y|strong="H3588" vio|strong="H7200" Dios que|strong="H3588" era bueno|strong="H2896" .',NULL),
(@vid,@bid,1,13,'Y|strong="H3068" fue|strong="H1961" la tarde|strong="H6153" y la mañana|strong="H1242" el día|strong="H3117" tercero|strong="H7992" .',NULL),
(@vid,@bid,1,14,'Y|strong="H3068" dijo Dios: Sean|strong="H1961" lumbreras|strong="H3974" en el firmamento del cielo|strong="H8064" para|strong="H1961" apartar el día|strong="H3117" y la noche|strong="H3915" : y sean|strong="H1961" por señales, y para|strong="H1961" las esta|strong="H1961" ­ciones, y para|strong="H1961" días|strong="H3117" y años|strong="H8141" ;',NULL),
(@vid,@bid,1,15,'Y|strong="H3068" sean|strong="H1961" por|strong="H5921" lumbreras|strong="H3974" en|strong="H5921" el|strong="H5921" fir­mamento del|strong="H5921" cielo|strong="H8064" para|strong="H5921" alum­brar sobre|strong="H5921" la|strong="H5921" tierra: y|strong="H5921" fue|strong="H1961" así|strong="H3651" .',NULL),
(@vid,@bid,1,16,'E|strong="H3068" hizo|strong="H6213" Dios las dos|strong="H8147" grandes|strong="H1419" lumbreras|strong="H3974" ; la lumbrera mayor|strong="H1419" para señorear en el|strong="H6213" día|strong="H3117" , y la lumbrera menor|strong="H6996" para señorear en la noche|strong="H3915" : también él hizo las estrellas|strong="H3556" .',NULL),
(@vid,@bid,1,17,'Y|strong="H3068" púsolas Dios en|strong="H5921" el|strong="H5921" firmamento del|strong="H5921" cielo|strong="H8064" , para|strong="H5921" alum­brar sobre|strong="H5921" la|strong="H5921" tierra,',NULL),
(@vid,@bid,1,18,'Y|strong="H3068" para|strong="H3588" señorear en|strong="H3588" el|strong="H3588" día|strong="H3117" y|strong="H3588" en|strong="H3588" la|strong="H3588" noche|strong="H3915" , y|strong="H3588" para|strong="H3588" apartar la|strong="H3588" luz y|strong="H3588" las tinieblas|strong="H2822" : y|strong="H3588" vio|strong="H7200" Dios que|strong="H3588" era bueno|strong="H2896" .',NULL),
(@vid,@bid,1,19,'Y|strong="H3068" fue|strong="H1961" la tarde|strong="H6153" y la mañana|strong="H1242" el día|strong="H3117" cuarto|strong="H7243" .',NULL),
(@vid,@bid,1,20,'Y|strong="H3068" dijo Dios: Produzcan|strong="H8318" las|strong="H5921" aguas|strong="H4325" abundantemente criatura viviente|strong="H2416" que|strong="H5921" se|strong="H5921" mueve, y|strong="H5921" aves|strong="H5775" que vuelen sobre|strong="H5921" la|strong="H5921" tierra, en|strong="H5921" el|strong="H5921" firmamento abierto del|strong="H5921" cielo|strong="H8064" .',NULL),
(@vid,@bid,1,21,'Y|strong="H3068" creó Dios las grandes|strong="H1419" ballenas|strong="H8577" , y|strong="H3588" toda|strong="H3605" criatura viva|strong="H2416" que|strong="H3588" se mueve, que|strong="H3588" las aguas|strong="H4325" produjeron|strong="H8317" abundantemente según su|strong="H3588" género, y|strong="H3588" toda|strong="H3605" ave|strong="H5775" alada|strong="H3671" según su|strong="H3588" género: y|strong="H3588" vio|strong="H7200" Dios que|strong="H3588" era bueno|strong="H2896" .',NULL),
(@vid,@bid,1,22,'Y|strong="H3068" Dios los bendijo|strong="H1288" diciendo: Fructificad|strong="H6509" y multiplicad, y henchid|strong="H4390" las aguas|strong="H4325" en los mares|strong="H3220" , y las aves|strong="H5775" se multipliquen en la tierra.',NULL),
(@vid,@bid,1,23,'Y|strong="H3068" fue|strong="H1961" la tarde|strong="H6153" y la mañana|strong="H1242" el día|strong="H3117" quinto|strong="H2549" .',NULL),
(@vid,@bid,1,24,'Y|strong="H3068" dijo Dios: Produzca|strong="H3318" la tierra seres|strong="H5315" vivientes|strong="H2416" según su género, bestias|strong="H2416" y criaturas que|strong="H1961" se|strong="H1961" arrastran y animales|strong="H2416" de la tierra según su género: y fue|strong="H1961" así|strong="H3651" .',NULL),
(@vid,@bid,1,25,'E|strong="H3068" hizo|strong="H6213" Dios animales|strong="H2416" de|strong="H3588" la|strong="H3588" tierra según su|strong="H3588" género, y|strong="H3588" ganado según su|strong="H3588" género, y|strong="H3588" todo|strong="H3605" animal|strong="H2416" que|strong="H3588" anda arrastrando sobre la|strong="H3588" tie­rra según su|strong="H3588" género: y|strong="H3588" vio|strong="H7200" Dios que|strong="H3588" era bueno|strong="H2896" .',NULL),
(@vid,@bid,1,26,'Y|strong="H3068" dijo Dios: Hagamos|strong="H6213" al|strong="H5921" hombre a|strong="H3068" nuestra imagen|strong="H6754" , conforme|strong="H5921" a|strong="H3068" nuestra semejanza|strong="H1823" : y|strong="H5921" señoree en|strong="H5921" los|strong="H5921" peces|strong="H1710" del|strong="H5921" mar|strong="H3220" , y|strong="H5921" en|strong="H5921" las|strong="H5921" aves|strong="H5775" del|strong="H5921" cielo|strong="H8064" , y|strong="H5921" en|strong="H5921" las|strong="H5921" bestias, y|strong="H5921" en|strong="H5921" toda|strong="H3605" la|strong="H5921" tierra, y|strong="H5921" en|strong="H5921" todo|strong="H3605" animal|strong="H7431" que|strong="H5921" anda arrastrando sobre|strong="H5921" la|strong="H5921" tierra.',NULL),
(@vid,@bid,1,27,'Y|strong="H3068" creó Dios al hombre a|strong="H3068" su imagen|strong="H6754" , a|strong="H3068" imagen|strong="H6754" de Dios lo creó; varón|strong="H2145" y hembra|strong="H5347" los creó.',NULL),
(@vid,@bid,1,28,'Y|strong="H3068" los|strong="H5921" bendijo|strong="H1288" Dios; y|strong="H5921" díjoles Dios: Fructificad|strong="H6509" y|strong="H5921" multiplicad, y|strong="H5921" henchid|strong="H4390" la|strong="H5921" tierra, y|strong="H5921" sojuzgadla, y|strong="H5921" señoread sobre|strong="H5921" los|strong="H5921" peces|strong="H1710" del|strong="H5921" mar|strong="H3220" , y|strong="H5921" sobre|strong="H5921" las|strong="H5921" aves|strong="H5775" del|strong="H5921" cielo|strong="H8064" , y|strong="H5921" sobre|strong="H5921" todas|strong="H3605" las|strong="H5921" bestias|strong="H2416" que|strong="H5921" se|strong="H5921" mueven sobre|strong="H5921" la|strong="H5921" tierra.',NULL),
(@vid,@bid,1,29,'Y|strong="H3068" dijo Dios: He aquí|strong="H2009" que|strong="H5921" os|strong="H5921" he dado|strong="H5414" toda|strong="H3605" hierba|strong="H6212" que|strong="H5921" da|strong="H5414" simiente|strong="H2233" , que|strong="H5921" está sobre|strong="H5921" la|strong="H5921" faz|strong="H6440" de|strong="H5921" toda|strong="H3605" la|strong="H5921" tierra; y|strong="H5921" todo|strong="H3605" árbol|strong="H6086" en|strong="H5921" que|strong="H5921" hay fruto|strong="H6529" de|strong="H5921" árbol|strong="H6086" que|strong="H5921" da|strong="H5414" simiente|strong="H2233" , os|strong="H5921" será|strong="H1961" para|strong="H5921" comer.',NULL),
(@vid,@bid,1,30,'Y|strong="H3068" a|strong="H3068" toda|strong="H3605" bestia|strong="H2416" de|strong="H5921" la|strong="H5921" tierra, y|strong="H5921" a|strong="H3068" toda|strong="H3605" ave|strong="H5775" del|strong="H5921" cielo|strong="H8064" , y|strong="H5921" a|strong="H3068" todo|strong="H3605" lo|strong="H5921" que|strong="H5921" se|strong="H1961" arrastra sobre|strong="H5921" la|strong="H5921" tierra, en|strong="H5921" que|strong="H5921" hay vida|strong="H5315" , os he dado toda|strong="H3605" hierba|strong="H6212" verde|strong="H3418" para|strong="H5921" comer|strong="H5315" : y|strong="H5921" fue|strong="H1961" así|strong="H3651" .',NULL),
