(@vid,@bid,2,1,'Y|strong="H3068" FUERON acabados los|strong="H3605" cie­ los|strong="H3605" y la|strong="H3605" tierra, y todo|strong="H3605" el|strong="H3605" ejér­cito de ellos|strong="H3605" .',NULL),
(@vid,@bid,2,2,'Y|strong="H3068" acabó|strong="H3615" Dios en el|strong="H3605" día|strong="H3117" séptimo|strong="H7637" su obra|strong="H4399" que|strong="H3117" hizo|strong="H6213" , y reposó|strong="H7673" el|strong="H3605" día|strong="H3117" séptimo|strong="H7637" de toda|strong="H3605" su obra|strong="H4399" que|strong="H3117" había|strong="H6213" hecho|strong="H6213" .',NULL),
(@vid,@bid,2,3,'Y|strong="H3068" bendijo|strong="H1288" Dios al día|strong="H3117" séptimo|strong="H7637" , y|strong="H3588" santificólo, porque|strong="H3588" en|strong="H3588" él|strong="H3588" reposó|strong="H7673" de|strong="H3588" toda|strong="H3605" su|strong="H3588" obra|strong="H4399" que|strong="H3588" había|strong="H6942" Dios creado y|strong="H3588" hecho|strong="H6213" .',NULL),
(@vid,@bid,2,4,'Éstos son los orígenes de los cielos|strong="H8064" y de la tierra cuando|strong="H3117" fue­ron creados, en el|strong="H6213" día|strong="H3117" que|strong="H3117" el|strong="H6213" SEÑOR|strong="H3068" Dios|strong="H3068" hizo|strong="H6213" la tierra y los cielos|strong="H8064" ,',NULL),
(@vid,@bid,2,5,'Y|strong="H3068" toda|strong="H3605" planta|strong="H7880" del|strong="H5921" campo|strong="H7704" antes|strong="H3588" que|strong="H3588" fuese|strong="H1961" en|strong="H5921" la|strong="H5921" tierra, y|strong="H3588" toda|strong="H3605" hier­ba del|strong="H5921" campo|strong="H7704" antes|strong="H3588" que|strong="H3588" naciese: porque|strong="H3588" aun|strong="H2962" no|strong="H3808" había|strong="H1961" el|strong="H5921" SEÑOR|strong="H3068" Dios|strong="H3068" hecho|strong="H1961" llover sobre|strong="H5921" la|strong="H5921" tierra, ni|strong="H3808" había hombre para|strong="H5921" que|strong="H3588" labra­ se|strong="H1961" la|strong="H5921" tierra;',NULL),
(@vid,@bid,2,6,'Mas|strong="H4480" subía|strong="H5927" de|strong="H4480" la|strong="H3605" tierra un vapor, que|strong="H4480" regaba toda|strong="H3605" la|strong="H3605" faz|strong="H6440" de|strong="H4480" la|strong="H3605" tierra.',NULL),
(@vid,@bid,2,7,'Formó|strong="H3335" , pues|strong="H1961" , el SEÑOR|strong="H3068" Dios|strong="H3068" al|strong="H4480" hombre del polvo|strong="H6083" de|strong="H4480" la tierra|strong="H6083" , y sopló|strong="H5397" en|strong="H4480" su nariz aliento de|strong="H4480" vida|strong="H5315" ; y fue|strong="H1961" el hombre un alma|strong="H5315" viviente|strong="H2416" .',NULL),
(@vid,@bid,2,8,'Y|strong="H3068" había el SEÑOR|strong="H3068" Dios|strong="H3068" plan­tado un huerto|strong="H1588" en Edén al orien­te, y puso|strong="H7760" allí|strong="H8033" al hombre que había formado.',NULL),
(@vid,@bid,2,9,'Y|strong="H3068" había el|strong="H3605" SEÑOR|strong="H3068" Dios|strong="H3068" hecho nacer de|strong="H4480" la|strong="H3605" tierra todo|strong="H3605" árbol|strong="H6086" agradable a|strong="H3068" la|strong="H3605" vista|strong="H4758" , y bueno|strong="H2896" para|strong="H4480" comer: también el|strong="H3605" árbol|strong="H6086" de|strong="H4480" vida|strong="H2416" en|strong="H4480" medio|strong="H8432" del|strong="H4480" huerto|strong="H1588" , y el|strong="H3605" árbol|strong="H6086" del|strong="H4480" conocimiento|strong="H1847" del|strong="H4480" bien|strong="H2896" y del|strong="H4480" mal|strong="H7451" .',NULL),
(@vid,@bid,2,10,'Y|strong="H3068" salía|strong="H3318" de Edén un río|strong="H5104" para|strong="H1961" regar el huerto|strong="H1588" , y de allí|strong="H8033" se|strong="H1961" repar­tía en|strong="H3318" cuatro ramales|strong="H7218" .',NULL),
(@vid,@bid,2,11,'El|strong="H1931" nombre|strong="H8034" del uno es Pisón: éste|strong="H1931" es el|strong="H1931" que|strong="H1931" rodea toda|strong="H3605" la|strong="H1931" tierra de Havila|strong="H2341" , donde|strong="H8033" hay oro|strong="H2091" ;',NULL),
