(@vid,@bid,2,13,'El|strong="H1931" nombre|strong="H8034" del segundo|strong="H8145" río|strong="H5104" es Gihón: éste|strong="H1931" es el|strong="H1931" que|strong="H1931" rodea toda|strong="H3605" la|strong="H1931" tierra de Etiopía|strong="H3568" .',NULL),
(@vid,@bid,2,14,'Y|strong="H3068" el|strong="H1931" nombre|strong="H8034" del tercer río|strong="H5104" es Hidekel: éste|strong="H1931" es|strong="H1931" el|strong="H1931" que|strong="H1931" va|strong="H3068" al oriente de Asiria. Y|strong="H3068" el|strong="H1931" cuarto|strong="H7243" río|strong="H5104" es el|strong="H1931" Éufrates|strong="H6578" .',NULL),
(@vid,@bid,2,15,'Tomó|strong="H3947" , pues, el SEÑOR|strong="H3068" Dios|strong="H3068" al hombre, y le puso|strong="H3240" en el huerto|strong="H1588" de Edén, para que lo labrara y lo guardase.',NULL),
(@vid,@bid,2,16,'Y|strong="H3068" mandó|strong="H6680" el|strong="H5921" SEÑOR|strong="H3068" Dios|strong="H3068" al|strong="H5921" hombre, diciendo: De|strong="H5921" todo|strong="H3605" árbol|strong="H6086" del|strong="H5921" huerto|strong="H1588" podrás libremente comer;',NULL),
(@vid,@bid,2,17,'Mas|strong="H3588" del|strong="H4480" árbol|strong="H6086" del|strong="H4480" conoci­miento del|strong="H4480" bien|strong="H2896" y|strong="H3588" del|strong="H4480" mal|strong="H7451" no|strong="H3808" comerás de|strong="H4480" él|strong="H3588" ; porque|strong="H3588" el|strong="H3588" día|strong="H3117" que|strong="H3588" de|strong="H4480" él|strong="H3588" comieres, ciertamente|strong="H3588" morirás|strong="H4191" .',NULL),
