(@vid,@bid,49,23,'Los|strong="H1167" arqueros le agraviaron mucho, y le asaetearon a él , y le aborrecieron:',NULL),
(@vid,@bid,49,24,'Mas su arco|strong="H7198" quedó|strong="H3427" en fortale­za, y los|strong="H3427" brazos|strong="H2220" de sus manos|strong="H3027" se corroboraron por|strong="H3027" las manos|strong="H3027" del poderoso Dios de Jacob|strong="H3290" , (de allí|strong="H8033" es el|strong="H3427" pastor|strong="H7462" , y la piedra de Israel|strong="H3478" ,)',NULL),
(@vid,@bid,49,25,'Por|strong="H5921" el|strong="H5921" Dios de|strong="H5921" tu padre, el|strong="H5921" cual te|strong="H5921" ayudará, y|strong="H5921" por|strong="H5921" el|strong="H5921" Todopoderoso|strong="H7706" , el|strong="H5921" cual te|strong="H5921" bendecirá|strong="H1288" con|strong="H5921" bendi­ciones del|strong="H5921" cielo|strong="H8064" de|strong="H5921" arriba, con|strong="H5921" bendiciones|strong="H1293" del|strong="H5921" abismo|strong="H8415" que|strong="H5921" está|strong="H5921" abajo|strong="H8478" , con|strong="H5921" bendiciones|strong="H1293" del|strong="H5921" seno y|strong="H5921" de|strong="H5921" la|strong="H5921" matriz.',NULL),
(@vid,@bid,49,26,'Las|strong="H5921" bendiciones|strong="H1293" de|strong="H5921" tu padre prevalecieron|strong="H1396" más|strong="H5921" que|strong="H5921" las|strong="H5921" bendiciones|strong="H1293" de|strong="H5921" mis progenitores, hasta|strong="H5704" el|strong="H5921" término de|strong="H5921" los|strong="H5921" collados|strong="H1389" eternos|strong="H5769" serán|strong="H1961" sobre|strong="H5921" la|strong="H5921" cabeza|strong="H7218" de|strong="H5921" José|strong="H3130" , y|strong="H5921" sobre|strong="H5921" la|strong="H5921" mollera|strong="H6936" del|strong="H5921" que|strong="H5921" fue|strong="H1961" separado de|strong="H5921" sus hermanos.',NULL);
INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,49,27,'Benjamín|strong="H1144" arrebatará como un lobo|strong="H2061" : en la mañana|strong="H1242" devorará la presa|strong="H7998" , y a|strong="H3068" la tarde|strong="H6153" repartirá|strong="H2505" los despojos|strong="H7998" .',NULL),
(@vid,@bid,49,28,'Todos|strong="H3605" estos|strong="H2063" fueron las doce|strong="H8147" tribus|strong="H7626" de Israel|strong="H3478" : y esto|strong="H2063" fue lo que|strong="H3605" su padre les dijo|strong="H1696" , y bendíjolos: a|strong="H3068" cada|strong="H3605" uno por su bendición|strong="H1293" los|strong="H3605" bendijo|strong="H1288" .',NULL),
(@vid,@bid,49,29,'Mandóles|strong="H6680" luego, y díjoles: Yo|strong="H6680" voy a|strong="H3068" ser reunido con mi pueblo|strong="H5971" : sepultadme|strong="H6912" con mis padres en|strong="H6912" la cueva|strong="H4631" que|strong="H5971" está en|strong="H6912" el campo|strong="H7704" de|strong="H5971" Efrón el heteo;',NULL),
