(@vid,@bid,50,4,'Y|strong="H3068" pasados los días|strong="H3117" de|strong="H5869" su luto, habló|strong="H1696" José|strong="H3130" a|strong="H3068" los de|strong="H5869" la casa|strong="H1004" de|strong="H5869" Faraón|strong="H6547" , diciendo|strong="H1696" : Si|strong="H4994" he hallado|strong="H4672" ahora|strong="H4994" gracia|strong="H2580" en vuestros ojos|strong="H5869" , os|strong="H5869" ruego|strong="H4994" que|strong="H4994" habléis|strong="H1696" en oídos de|strong="H5869" Faraón|strong="H6547" , diciendo|strong="H1696" :',NULL),
(@vid,@bid,50,5,'Mi|strong="H2009" padre me conjuró|strong="H7650" diciendo: He aquí|strong="H2009" yo|strong="H2009" muero|strong="H4191" ; en|strong="H6912" mi|strong="H2009" sepul­cro que|strong="H6258" yo|strong="H2009" cavé para|strong="H6258" mí|strong="H2009" en|strong="H6912" la tie­rra de Canaán|strong="H3667" , allí|strong="H8033" me sepultarás; ruego|strong="H4994" pues|strong="H4994" que|strong="H6258" vaya|strong="H5927" yo|strong="H2009" ahora|strong="H6258" , y sepultaré a|strong="H3068" mi|strong="H2009" padre, y volveré|strong="H7725" .',NULL),
(@vid,@bid,50,6,'Y|strong="H3068" Faraón|strong="H6547" dijo: Ve|strong="H5927" , y sepulta|strong="H6912" a|strong="H3068" tu padre, como él te conjuró|strong="H7650" .',NULL),
(@vid,@bid,50,7,'Entonces José|strong="H3130" subió|strong="H5927" a|strong="H3068" sepultar a|strong="H3068" su padre; y subieron|strong="H5927" con él|strong="H3605" todos|strong="H3605" los|strong="H3605" siervos|strong="H5650" de Faraón|strong="H6547" , los|strong="H3605" ancianos|strong="H2205" de su casa|strong="H1004" , y todos|strong="H3605" los|strong="H3605" ancianos|strong="H2205" de la|strong="H3605" tierra de Egipto|strong="H4714" .',NULL),
