(@vid,@bid,50,16,'Y|strong="H3068" enviaron a|strong="H3068" decir a|strong="H3068" José|strong="H3130" : Tu padre mandó|strong="H6680" antes|strong="H6440" de|strong="H6440" su muerte|strong="H4194" , diciendo:',NULL),
(@vid,@bid,50,17,'Así|strong="H3541" diréis a|strong="H3068" José|strong="H3130" : Ruégote|strong="H4994" que|strong="H3588" perdones|strong="H5375" ahora|strong="H6258" la|strong="H3588" maldad|strong="H7451" de|strong="H3588" tus hermanos y|strong="H3588" su|strong="H3588" pecado|strong="H2403" , porque|strong="H3588" mal|strong="H7451" te|strong="H3588" trataron: por|strong="H3588" tanto ahora|strong="H6258" te|strong="H3588" rogamos que|strong="H3588" perdones|strong="H5375" la|strong="H3588" maldad|strong="H7451" de|strong="H3588" los|strong="H3588" siervos|strong="H5650" del Dios de|strong="H3588" tu padre. Y|strong="H3068" José|strong="H3130" lloró|strong="H1058" mientras|strong="H3588" hablaban|strong="H1696" .',NULL),
(@vid,@bid,50,18,'Y|strong="H3068" vinieron también|strong="H1571" sus her­manos, y|strong="H1571" postráronse delante|strong="H6440" de|strong="H6440" él|strong="H5307" , y|strong="H1571" dijeron: He aquí|strong="H2009" , nosotros somos tus siervos|strong="H5650" .',NULL),
