(@vid,@bid,50,20,'Vosotros pensasteis|strong="H2803" mal|strong="H7451" sobre|strong="H5921" mí|strong="H5921" , mas Dios lo|strong="H2088" encaminó a|strong="H3068" bien|strong="H2896" , para|strong="H4616" hacer|strong="H6213" lo|strong="H2088" que|strong="H5921" vemos hoy|strong="H3117" , para|strong="H4616" mantener en|strong="H5921" vida|strong="H3117" a|strong="H3068" mucho|strong="H7227" pueblo|strong="H5971" .',NULL),
(@vid,@bid,50,21,'Ahora|strong="H6258" , pues|strong="H6258" , no|strong="H5921" tengáis miedo|strong="H3372" ; yo os|strong="H5921" sustentaré a|strong="H3068" voso­tros y|strong="H5921" a|strong="H3068" vuestros hijos. Así|strong="H6258" los|strong="H5921" consoló, y|strong="H5921" les|strong="H5921" habló|strong="H1696" al|strong="H5921" corazón|strong="H3820" .',NULL),
(@vid,@bid,50,22,'Y|strong="H3068" estuvo|strong="H3427" José|strong="H3130" en Egipto|strong="H4714" , él|strong="H1931" y la|strong="H1931" casa|strong="H1004" de su|strong="H1931" padre: y vivió|strong="H2421" José|strong="H3130" ciento|strong="H3967" diez|strong="H6235" años|strong="H8141" .',NULL),
