(@vid,@bid,50,24,'Y|strong="H3068" José|strong="H3130" dijo a|strong="H3068" sus hermanos: Yo|strong="H4480" me|strong="H4480" muero|strong="H4191" ; y Dios cierta­mente os|strong="H4480" visitará|strong="H6485" , y os|strong="H4480" hará subir|strong="H5927" de|strong="H4480" esta|strong="H2063" tierra a|strong="H3068" la|strong="H2063" tierra que|strong="H4480" juró|strong="H7650" a|strong="H3068" Abraham, a|strong="H3068" Isaac|strong="H3327" , y a|strong="H3068" Jacob|strong="H3290" .',NULL),
(@vid,@bid,50,25,'Y|strong="H3068" conjuró|strong="H7650" José|strong="H3130" a|strong="H3068" los|strong="H1121" hijos|strong="H1121" de|strong="H1121" Israel|strong="H3478" , diciendo: Dios ciertamen­te os visitará|strong="H6485" , y haréis llevar de|strong="H1121" aquí|strong="H2088" mis huesos|strong="H6106" .',NULL),
