INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'ÉSTOS son los|strong="H1121" nombres|strong="H8034" de|strong="H1121" los|strong="H1121" hijos|strong="H1121" de|strong="H1121" Israel|strong="H3478" , que|strong="H1121" entraron en Egipto|strong="H4714" con Jacob|strong="H3290" ; cada uno entró con su familia|strong="H1004" .',NULL),
