(@vid,@bid,1,6,'Y|strong="H3068" murió|strong="H4191" José|strong="H3130" , y todos|strong="H3605" sus|strong="H1931" her­manos, y toda|strong="H3605" aquella|strong="H1931" genera­ción.',NULL),
(@vid,@bid,1,7,'Y|strong="H3068" los|strong="H1121" hijos|strong="H1121" de|strong="H1121" Israel|strong="H3478" fructificaron, y aumentaron mucho|strong="H3966" , y se multiplicaron|strong="H7235" , y fueron fortalecidos en extremo; y la tierra se llenó|strong="H4390" de|strong="H1121" ellos.',NULL),
