(@vid,@bid,1,9,'Y|strong="H3068" él|strong="H1121" dijo a|strong="H3068" su pueblo|strong="H5971" : He aquí|strong="H2009" , el|strong="H1121" pueblo|strong="H5971" de|strong="H4480" los|strong="H1121" hijos|strong="H1121" de|strong="H4480" Israel|strong="H3478" es mayor|strong="H7227" y más|strong="H4480" fuerte|strong="H6099" que|strong="H4480" nosotros:',NULL),
(@vid,@bid,1,10,'Ahora, pues|strong="H3588" , seamos|strong="H1961" sabios para|strong="H5921" con|strong="H5921" ellos|strong="H1931" , porque|strong="H3588" no|strong="H6435" se|strong="H1961" multipli­quen, y|strong="H1571" acontezca que|strong="H3588" viniendo|strong="H1961" guerra|strong="H4421" , ellos|strong="H1931" también|strong="H1571" se|strong="H1961" junten con|strong="H5921" nuestros enemigos|strong="H8130" , y|strong="H1571" peleen contra|strong="H5921" nosotros|strong="H5921" , y|strong="H1571" se|strong="H1961" vayan de|strong="H4480" la|strong="H1931" tierra.',NULL),
