INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'Y|strong="H3068" ACONTECIÓ|strong="H1961" en|strong="H3212" los|strong="H1121" días|strong="H3117" que|strong="H1931" gobernaban los|strong="H1121" jueces|strong="H8199" , que|strong="H1931" hubo|strong="H1961" hambre|strong="H7458" en|strong="H3212" la|strong="H1931" tierra. Y|strong="H3068" un varón de|strong="H1121" Belem de|strong="H1121" Judá|strong="H3063" , fue|strong="H1961" a|strong="H3068" peregrinar en|strong="H3212" los|strong="H1121" campos|strong="H7704" de|strong="H1121" Moab|strong="H4124" , él|strong="H1931" y su|strong="H1931" esposa, y dos|strong="H8147" hijos|strong="H1121" suyos|strong="H1931" .',NULL),
(@vid,@bid,1,2,'El|strong="H1121" nombre|strong="H8034" de|strong="H1121" aquel varón era|strong="H1961" Elimelec, y el|strong="H1121" de|strong="H1121" su esposa Noemi|strong="H5281" ; y los|strong="H1121" nombres|strong="H8034" de|strong="H1121" sus dos|strong="H8147" hijos|strong="H1121" eran|strong="H1961" , Mahalón|strong="H4248" y Quilión, efrateos de|strong="H1121" Belem de|strong="H1121" Judá|strong="H3063" . Llegaron pues|strong="H1961" a|strong="H3068" los|strong="H1121" cam­pos de|strong="H1121" Moab|strong="H4124" , y asentaron allí|strong="H8033" .',NULL),
