(@vid,@bid,1,11,'Y|strong="H3068" Noemi|strong="H5281" respondió|strong="H7725" : Volveos|strong="H7725" , hijas|strong="H1323" mías: ¿ para|strong="H1961" qué|strong="H4100" habéis de|strong="H5973" ir|strong="H3212" conmigo|strong="H5973" ? ¿tengo yo más|strong="H5750" hijos|strong="H1121" en|strong="H5973" el|strong="H5973" vientre, que|strong="H4100" puedan ser vuestros maridos?',NULL),
(@vid,@bid,1,12,'Volveos|strong="H7725" , hijas|strong="H1323" mías, e|strong="H3068" idos|strong="H3212" ; que|strong="H3588" yo|strong="H3588" ya|strong="H1571" soy|strong="H1961" vieja para|strong="H3588" ser para|strong="H3588" varón. Y|strong="H3068" aunque|strong="H3588" dijese: Esperanza|strong="H8615" tengo|strong="H3426" ; y|strong="H1571" esta|strong="H1961" noche|strong="H3915" fuese|strong="H3212" con|strong="H3588" varón, y|strong="H1571" aun|strong="H1571" pariese hijos|strong="H1121" ;',NULL),
(@vid,@bid,1,13,'¿Habíais vosotras de|strong="H4480" esperar­ los|strong="H1961" hasta|strong="H5704" que|strong="H3588" fuesen grandes|strong="H1431" ? ¿habías vosotras de|strong="H4480" quedaros sin casar por|strong="H3588" amor de|strong="H4480" ellos|strong="H3027" ? No|strong="H3588" , hijas|strong="H1323" mías; que|strong="H3588" mayor|strong="H3588" amargura|strong="H4843" tengo yo|strong="H4480" que|strong="H3588" vosotras, pues|strong="H3588" la|strong="H3588" mano|strong="H3027" del|strong="H4480" SEÑOR|strong="H3068" ha salido|strong="H3318" con|strong="H4480" ­tra mí|strong="H1431" .',NULL),
(@vid,@bid,1,14,'Mas|strong="H5750" ellas alzando|strong="H5375" otra|strong="H5750" vez su voz|strong="H6963" , lloraron|strong="H1058" : y Orfa besó|strong="H5401" a|strong="H3068" su suegra|strong="H2545" , mas|strong="H5750" Rut se quedó con ella.',NULL),
(@vid,@bid,1,15,'Y|strong="H3068" Noemi dijo: He aquí|strong="H2009" tu cuñada se|strong="H5971" ha vuelto|strong="H7725" a|strong="H3068" su pueblo|strong="H5971" y a|strong="H3068" sus dioses; vuélvete|strong="H7725" tú tras ella.',NULL),
(@vid,@bid,1,16,'Y|strong="H3068" Rut respondió|strong="H7725" : No|strong="H3588" me|strong="H3588" rue­gues que|strong="H3588" te|strong="H3588" deje|strong="H5800" , y|strong="H3588" me|strong="H3588" aparte de|strong="H3588" ti: porque|strong="H3588" donde quiera que|strong="H3588" tú fueres|strong="H3212" , iré|strong="H3212" yo|strong="H3588" ; y|strong="H3588" donde quiera que|strong="H3588" vivieres|strong="H3885" , viviré|strong="H3885" . Tu pueblo|strong="H5971" será mi pueblo|strong="H5971" , y|strong="H3588" tu Dios mi Dios.',NULL),
(@vid,@bid,1,17,'Donde|strong="H8033" tú|strong="H6213" murieres, moriré|strong="H4191" yo|strong="H3588" , y|strong="H3588" allí|strong="H8033" seré sepultada|strong="H6912" : así|strong="H3541" me|strong="H3588" haga|strong="H6213" el|strong="H3588" SEÑOR|strong="H3068" , y|strong="H3588" así|strong="H3541" me|strong="H3588" dé|strong="H3588" , que|strong="H3588" sólo la|strong="H3588" muerte|strong="H4194" hará|strong="H6213" separación entre|strong="H3588" mí y|strong="H3588" ti.',NULL),
(@vid,@bid,1,18,'Y|strong="H3068" viendo|strong="H7200" Noemi que|strong="H3588" estaba tan|strong="H1931" resuelta a|strong="H3068" ir|strong="H3212" con|strong="H3588" ella|strong="H1931" , dejó|strong="H2308" de|strong="H3588" hablarle|strong="H1696" .',NULL),
(@vid,@bid,1,19,'Anduvieron|strong="H3212" pues|strong="H1961" ellas|strong="H5921" dos|strong="H8147" hasta|strong="H5704" que|strong="H5921" llegaron a|strong="H3068" Belem: y|strong="H5921" aconteció|strong="H1961" que|strong="H5921" entrando en|strong="H5921" Belem, toda|strong="H3605" la|strong="H5921" ciudad|strong="H5892" se|strong="H1961" conmovió por|strong="H5921" razón de|strong="H5921" ellas|strong="H5921" , y|strong="H5921" decían: ¿ No|strong="H1961" es|strong="H1961" ésta|strong="H2063" Noemi|strong="H5281" ?',NULL),
