(@vid,@bid,4,4,'Y|strong="H3068" yo|strong="H3588" decidí hacértelo saber|strong="H5046" , y|strong="H3588" decirte que|strong="H3588" la|strong="H3588" tomes delante|strong="H5048" de|strong="H3588" los|strong="H3427" que|strong="H3588" están|strong="H3427" aquí sentados|strong="H3427" , y|strong="H3588" delante|strong="H5048" de|strong="H3588" los|strong="H3427" ancianos|strong="H2205" de|strong="H3588" mi pueblo|strong="H5971" . Si|strong="H3588" hubieres de|strong="H3588" redimir|strong="H1350" , redime|strong="H1350" ; y|strong="H3588" si|strong="H3588" no|strong="H3808" quisieres|strong="H3808" redimir|strong="H1350" , decláramelo|strong="H5046" para|strong="H3588" que|strong="H3588" yo|strong="H3588" lo|strong="H3808" sepa|strong="H3045" : porque|strong="H3588" no|strong="H3808" hay otro que|strong="H3588" redima sino|strong="H3588" tú, y|strong="H3588" yo|strong="H3588" después|strong="H3427" de|strong="H3588" ti. Y|strong="H3068" él|strong="H3588" respondió: Yo|strong="H3588" redimiré|strong="H1350" .',NULL),
(@vid,@bid,4,5,'Entonces|strong="H3117" replicó Booz|strong="H1162" : El|strong="H5921" mismo día|strong="H3117" que|strong="H5921" tomares las|strong="H5921" tie­rras de|strong="H5921" mano|strong="H3027" de|strong="H5921" Noemi|strong="H5281" , has|strong="H4191" de|strong="H5921" tomar también a|strong="H3068" Rut moabita|strong="H4125" , esposa del|strong="H5921" difunto, para|strong="H5921" que|strong="H5921" suscites el|strong="H5921" nombre|strong="H8034" del|strong="H5921" muerto|strong="H4191" sobre|strong="H5921" su posesión|strong="H5159" .',NULL),
(@vid,@bid,4,6,'Y|strong="H3068" respondió el|strong="H3588" pariente|strong="H1350" : No|strong="H3808" puedo|strong="H3201" redimir|strong="H1350" por|strong="H3588" mi parte, por|strong="H3588" ­ que|strong="H3588" echaría a|strong="H3068" perder mi heredad|strong="H5159" : redime|strong="H1350" tú usando de mi derecho, porque|strong="H3588" yo|strong="H3588" no|strong="H3808" podré|strong="H3201" redimir|strong="H1350" .',NULL),
(@vid,@bid,4,7,'Había ya de|strong="H5921" largo tiempo esta|strong="H2063" costumbre en|strong="H5921" Israel|strong="H3478" en|strong="H5921" la|strong="H5921" reden­ción o|strong="H3068" contrato, que|strong="H5921" para|strong="H5921" la|strong="H5921" con|strong="H5921" ­firmación de|strong="H5921" cualquier|strong="H3605" negocio|strong="H1697" , el|strong="H5921" uno se|strong="H5921" quitaba el|strong="H5921" zapato y|strong="H5921" lo|strong="H1697" daba|strong="H5414" a|strong="H3068" su compañero|strong="H7453" : y|strong="H5921" este|strong="H2063" era el|strong="H5921" testimonio en|strong="H5921" Israel|strong="H3478" .',NULL),
(@vid,@bid,4,8,'Entonces el pariente|strong="H1350" dijo a|strong="H3068" Booz|strong="H1162" : Tómalo|strong="H7069" tú. Y|strong="H3068" descalzó su zapato.',NULL),
(@vid,@bid,4,9,'Y|strong="H3068" Booz|strong="H1162" dijo a|strong="H3068" los|strong="H3605" ancianos|strong="H2205" y|strong="H3588" a|strong="H3068" todo|strong="H3605" el|strong="H3588" pueblo|strong="H5971" : Vosotros sois hoy|strong="H3117" testigos|strong="H5707" de|strong="H3588" que|strong="H3588" tomo|strong="H7069" todas|strong="H3605" las cosas que|strong="H3588" fueron de|strong="H3588" Elimelec, y|strong="H3588" todo|strong="H3605" lo|strong="H3605" que|strong="H3588" fue de|strong="H3588" Quilión y|strong="H3588" de|strong="H3588" Mahalón|strong="H4248" , de|strong="H3588" mano|strong="H3027" de|strong="H3588" Noemí|strong="H5281" ;',NULL),
(@vid,@bid,4,10,'Y|strong="H3068" que|strong="H3808" también|strong="H1571" tomo|strong="H7069" por|strong="H5921" mi|strong="H5921" esposa a|strong="H3068" Rut moabita|strong="H4125" , esposa de|strong="H5921" Mahalón|strong="H4248" , para|strong="H5921" suscitar|strong="H6965" el|strong="H5921" nom­bre del|strong="H5921" difunto sobre|strong="H5921" su heredad|strong="H5159" , para|strong="H5921" que|strong="H3808" el|strong="H5921" nombre|strong="H8034" del|strong="H5921" muerto|strong="H4191" no|strong="H3808" se|strong="H5921" borre de|strong="H5921" entre|strong="H5921" sus herma­ nos|strong="H5921" y|strong="H1571" de|strong="H5921" la|strong="H5921" puerta|strong="H8179" de|strong="H5921" su lugar|strong="H4725" . Vosotros|strong="H5973" sois hoy|strong="H3117" testigos|strong="H5707" .',NULL),
(@vid,@bid,4,11,'Y|strong="H3068" dijeron todos|strong="H3605" los|strong="H3605" del pueblo|strong="H5971" que|strong="H5971" estaban|strong="H5971" a|strong="H3068" la|strong="H3605" puerta|strong="H8179" con los|strong="H3605" ancianos|strong="H2205" : Testigos|strong="H5707" somos. El|strong="H3605" SEÑOR|strong="H3068" haga|strong="H6213" a|strong="H3068" la|strong="H3605" mujer que|strong="H5971" entra en tu|strong="H6213" casa|strong="H1004" como a|strong="H3068" Raquel y a|strong="H3068" Lea|strong="H3812" , las cuales dos|strong="H8147" edificaron|strong="H1129" la|strong="H3605" casa|strong="H1004" de|strong="H5971" Israel|strong="H3478" ; y tú|strong="H6213" seas ilustre en Efrata, y tengas|strong="H5414" nombradía en Belem:',NULL),
(@vid,@bid,4,12,'Y|strong="H3068" de|strong="H4480" la|strong="H2063" simiente|strong="H2233" que|strong="H4480" el SEÑOR|strong="H3068" te|strong="H4480" diere|strong="H5414" de|strong="H4480" esta|strong="H2063" moza|strong="H5291" , sea|strong="H1961" tu casa|strong="H1004" como|strong="H1961" la|strong="H2063" casa|strong="H1004" de|strong="H4480" Fares, al|strong="H4480" que|strong="H4480" parió|strong="H3205" Tamar a|strong="H3068" Judá|strong="H3063" .',NULL),
(@vid,@bid,4,13,'Booz|strong="H1162" pues|strong="H1961" tomó|strong="H3947" a|strong="H3068" Rut, y ella fue|strong="H1961" su esposa; y luego que|strong="H1121" entró a|strong="H3068" ella, el|strong="H1121" SEÑOR|strong="H3068" le dio|strong="H5414" que|strong="H1121" conci­biese y pariese un hijo|strong="H1121" .',NULL),
(@vid,@bid,4,14,'Y|strong="H3068" las mujeres decían a|strong="H3068" Noemi|strong="H5281" : Loado|strong="H1288" sea el SEÑOR|strong="H3068" , que|strong="H3808" hizo que|strong="H3808" no|strong="H3808" te faltase hoy|strong="H3117" pariente|strong="H1350" , cuyo nombre|strong="H8034" será|strong="H3808" nom­brado en Israel|strong="H3478" .',NULL),
(@vid,@bid,4,15,'El|strong="H1931" cual|strong="H1931" será|strong="H1961" restaurador|strong="H7725" de|strong="H3588" tu alma|strong="H5315" , y|strong="H3588" el|strong="H1931" que|strong="H3588" sustentará tu vejez|strong="H7872" ; pues|strong="H3588" que|strong="H3588" tu nuera|strong="H3618" , la|strong="H1931" cual|strong="H1931" te|strong="H3588" ama y|strong="H3588" te|strong="H3588" vale|strong="H2896" más|strong="H3588" que|strong="H3588" siete|strong="H7651" hijos|strong="H1121" , le|strong="H1931" ha parido.',NULL),
(@vid,@bid,4,16,'Y|strong="H3068" tomando|strong="H3947" Noemi|strong="H5281" el hijo, púsolo|strong="H7896" en su regazo|strong="H2436" , y fuéle su ama.',NULL),
(@vid,@bid,4,17,'Y|strong="H3068" las vecinas diciendo, a|strong="H3068" Noemi|strong="H5281" ha nacido|strong="H3205" un hijo|strong="H1121" , le|strong="H1931" pusieron nombre|strong="H8034" ; y llamáronle Obed|strong="H5744" . Éste|strong="H1931" es padre de|strong="H1121" Isaí|strong="H3448" , padre de|strong="H1121" David|strong="H1732" .',NULL),
