INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'HUBO|strong="H1961" un varón de|strong="H4480" Ramataim de|strong="H4480" Sofim, del|strong="H4480" monte|strong="H2022" de|strong="H4480" Efraím, que|strong="H4480" se|strong="H1961" llamaba|strong="H8034" Elcana, hijo|strong="H1121" de|strong="H4480" Jeroham|strong="H3395" , hijo|strong="H1121" de|strong="H4480" Eliú, hijo|strong="H1121" de|strong="H4480" Tohu, hijo|strong="H1121" de|strong="H4480" Zuf, efrateo.',NULL),
(@vid,@bid,1,2,'Y|strong="H3068" tenía|strong="H1961" él dos|strong="H8147" esposas; el nom­bre de la una era|strong="H1961" Ana, y el nom­bre de la otra|strong="H8145" Penina. Y|strong="H3068" Penina tenía|strong="H1961" hijos|strong="H3206" , mas Ana no|strong="H1961" los|strong="H1961" tenía|strong="H1961" .',NULL),
(@vid,@bid,1,3,'Y|strong="H3068" subía|strong="H5927" aquel|strong="H1931" varón todos los|strong="H1121" años|strong="H3117" de|strong="H1121" su|strong="H1931" ciudad|strong="H5892" , a|strong="H3068" adorar y sacrificar al SEÑOR|strong="H3068" de|strong="H1121" los|strong="H1121" ejér­citos en Silo|strong="H7887" , donde|strong="H8033" estaban dos|strong="H8147" hijos|strong="H1121" de|strong="H1121" Elí|strong="H5941" , Ofni y Finees, sacerdotes|strong="H3548" del SEÑOR|strong="H3068" .',NULL),
(@vid,@bid,1,4,'Y|strong="H3068" cuando|strong="H3117" venía el|strong="H3605" día|strong="H3117" , Elcana sacrificaba|strong="H2076" , y daba|strong="H5414" a|strong="H3068" Penina su esposa, y a|strong="H3068" todos|strong="H3605" sus hijos|strong="H1121" y a|strong="H3068" todas|strong="H3605" sus hijas|strong="H1323" , a|strong="H3068" cada|strong="H3605" uno su parte|strong="H4490" .',NULL),
(@vid,@bid,1,5,'Mas|strong="H3588" a|strong="H3068" Ana daba|strong="H5414" una parte|strong="H4490" escogida; porque|strong="H3588" amaba a|strong="H3068" Ana, aunque|strong="H3588" el|strong="H3588" SEÑOR|strong="H3068" había|strong="H3588" cerrado su|strong="H3588" matriz|strong="H7358" .',NULL),
(@vid,@bid,1,6,'Y|strong="H3068" su|strong="H3588" competidora la|strong="H1571" irritaba, enojándola|strong="H3707" y|strong="H1571" entristeciéndola, porque|strong="H3588" el|strong="H3588" SEÑOR|strong="H3068" había|strong="H3588" cerrado su|strong="H3588" matriz|strong="H7358" .',NULL),
(@vid,@bid,1,7,'Y|strong="H3068" así hacía|strong="H6213" él|strong="H6213" cada|strong="H8141" año|strong="H8141" : cuando subía|strong="H5927" a|strong="H3068" la casa|strong="H1004" del SEÑOR|strong="H3068" , eno­jaba así|strong="H3651" a|strong="H3068" la otra|strong="H6213" ; por|strong="H3651" lo|strong="H3808" cual ella lloraba|strong="H1058" , y no|strong="H3808" comía.',NULL),
(@vid,@bid,1,8,'Y|strong="H3068" Elcana su marido le dijo: Ana, ¿ por|strong="H4100" qué|strong="H4100" lloras|strong="H1058" ? ¿y por|strong="H4100" qué|strong="H4100" no|strong="H3808" comes? ¿y por|strong="H4100" qué|strong="H4100" está afligido tu corazón|strong="H3824" ? ¿ No|strong="H3808" te soy yo mejor|strong="H2896" que|strong="H4100" diez|strong="H6235" hijos|strong="H1121" ?',NULL),
(@vid,@bid,1,9,'Y|strong="H3068" levantóse|strong="H6965" Ana después|strong="H5921" que|strong="H5921" hubo comido y|strong="H5921" bebido|strong="H8354" en|strong="H5921" Silo|strong="H7887" ; y|strong="H5921" mientras el|strong="H5921" sacerdote|strong="H3548" Elí|strong="H5941" estaba|strong="H3427" sentado|strong="H3427" en|strong="H5921" una silla junto|strong="H5921" a|strong="H3068" un pilar del|strong="H5921" templo|strong="H1964" del|strong="H5921" SEÑOR|strong="H3068" ,',NULL),
(@vid,@bid,1,10,'Ella|strong="H1931" con|strong="H5921" amargura|strong="H4751" de|strong="H5921" alma|strong="H5315" oró|strong="H6419" al|strong="H5921" SEÑOR|strong="H3068" , y|strong="H5921" lloró|strong="H1058" abundan­temente.',NULL),
(@vid,@bid,1,11,'E|strong="H3068" hizo|strong="H5088" voto|strong="H5087" , diciendo: Oh SEÑOR|strong="H3068" de|strong="H5921" los|strong="H5921" ejércitos|strong="H6635" , si|strong="H3808" te|strong="H5921" dig­nares mirar|strong="H7200" la|strong="H5921" aflicción|strong="H6040" de|strong="H5921" tu sier­ va|strong="H3068" , y|strong="H5921" te|strong="H5921" acordares de|strong="H5921" mí|strong="H5921" , y|strong="H5921" no|strong="H3808" te|strong="H5921" olvidares de|strong="H5921" tu sierva, mas|strong="H5921" dieres|strong="H5414" a|strong="H3068" tu sierva un hijo varón, yo lo|strong="H3808" dedi­caré al|strong="H5921" SEÑOR|strong="H3068" todos|strong="H3605" los|strong="H5921" días|strong="H3117" de|strong="H5921" su vida|strong="H2416" , y|strong="H5921" no|strong="H3808" subirá|strong="H5927" navaja|strong="H4177" sobre|strong="H5921" su cabeza|strong="H7218" .',NULL),
(@vid,@bid,1,12,'Y|strong="H3068" sucedió|strong="H1961" que|strong="H3588" como|strong="H3588" ella orase largamente delante|strong="H6440" del SEÑOR|strong="H3068" , Elí|strong="H5941" estaba|strong="H1961" observando|strong="H8104" la|strong="H3588" boca|strong="H6310" de|strong="H3588" ella.',NULL),
(@vid,@bid,1,13,'Mas|strong="H7535" Ana hablaba|strong="H1696" en|strong="H5921" su|strong="H1931" corazón|strong="H3820" , y|strong="H5921" solamente|strong="H7535" se|strong="H1931" movían sus|strong="H1931" labios|strong="H8193" , y|strong="H5921" su|strong="H1931" voz|strong="H6963" no|strong="H3808" se|strong="H1931" oía|strong="H8085" ; y|strong="H5921" túvola Elí|strong="H5941" por|strong="H5921" borracha.',NULL),
(@vid,@bid,1,14,'Entonces|strong="H5493" le|strong="H5921" dijo Elí|strong="H5941" : ¿ Hasta|strong="H5704" cuándo|strong="H4970" estarás borracha?; aparta|strong="H5493" de|strong="H5921" ti|strong="H5921" tu vino|strong="H3196" .',NULL),
(@vid,@bid,1,15,'Y|strong="H3068" Ana le respondió|strong="H6030" , dicien­do: No|strong="H3808" , señor|strong="H3068" mío: mas|strong="H6030" yo|strong="H5315" soy una mujer trabajada de|strong="H6440" espíritu|strong="H7307" : no|strong="H3808" he bebido|strong="H8354" vino|strong="H3196" ni|strong="H3808" bebida|strong="H7941" fuerte, sino|strong="H3808" que|strong="H3808" he derramado|strong="H8210" mi|strong="H6030" alma|strong="H5315" delante|strong="H6440" del|strong="H8354" SEÑOR|strong="H3068" .',NULL),
(@vid,@bid,1,16,'No|strong="H3588" tengas|strong="H5414" a|strong="H3068" tu sierva por|strong="H3588" una hija|strong="H1323" de|strong="H3588" Belial: porque|strong="H3588" por|strong="H3588" la|strong="H3588" magnitud de|strong="H3588" mis|strong="H5414" congojas y|strong="H3588" de|strong="H3588" mi aflicción he hablado|strong="H1696" hasta|strong="H5704" ahora|strong="H2008" .',NULL),
(@vid,@bid,1,17,'Y|strong="H3068" Elí|strong="H5941" respondió|strong="H6030" , y dijo: Ve|strong="H3212" en|strong="H5973" paz|strong="H7965" , y el|strong="H5973" Dios de|strong="H5973" Israel|strong="H3478" te|strong="H5973" otorgue la petición|strong="H7596" que le|strong="H5973" has|strong="H5414" hecho.',NULL),
(@vid,@bid,1,18,'Y|strong="H3068" ella dijo: Halle|strong="H4672" tu sierva|strong="H8198" gracia|strong="H2580" delante|strong="H6440" de|strong="H6440" tus ojos|strong="H5869" . Y|strong="H3068" fuese|strong="H3212" la mujer su camino|strong="H1870" , y comió, y su cara|strong="H6440" no|strong="H3808" estuvo|strong="H1961" más|strong="H5750" triste.',NULL),
(@vid,@bid,1,19,'Y|strong="H3068" levantándose|strong="H7925" muy de|strong="H6440" mañana|strong="H1242" , adoraron|strong="H7812" delante|strong="H6440" del SEÑOR|strong="H3068" , y volviéronse|strong="H7725" , y vinie­ron a|strong="H3068" su casa|strong="H1004" en Ramá|strong="H7414" . Y|strong="H3068" Elcana conoció|strong="H3045" a|strong="H3068" Ana su esposa, y el SEÑOR|strong="H3068" se|strong="H3045" acordó de|strong="H6440" ella.',NULL),
(@vid,@bid,1,20,'Y|strong="H3068" sucedió|strong="H1961" que|strong="H3588" corrido el|strong="H3588" tiempo|strong="H3117" , después|strong="H1961" de|strong="H3588" haber|strong="H1961" concebido Ana, parió|strong="H3205" un hijo|strong="H1121" , y|strong="H3588" púsole|strong="H7121" por|strong="H3588" nombre|strong="H8034" Samuel|strong="H8050" , diciendo : Por|strong="H3588" cuanto|strong="H3588" lo demandé al SEÑOR|strong="H3068" .',NULL),
(@vid,@bid,1,21,'Después subió|strong="H5927" el|strong="H3605" varón Elcana, con toda|strong="H3605" su familia|strong="H1004" , a|strong="H3068" sacrificar al SEÑOR|strong="H3068" el|strong="H3605" sacrificio|strong="H2077" acostumbrado|strong="H3117" , y su voto|strong="H5088" .',NULL),
(@vid,@bid,1,22,'Mas|strong="H3588" Ana no|strong="H3808" subió|strong="H5927" , sino|strong="H3588" dijo a|strong="H3068" su|strong="H3588" marido: Yo no subiré hasta|strong="H5704" que|strong="H3588" el|strong="H3588" niño|strong="H5288" sea destetado; para|strong="H5704" que|strong="H3588" lo|strong="H3808" lleve y|strong="H3588" sea presentado delante|strong="H6440" del SEÑOR|strong="H3068" , y|strong="H3588" se|strong="H3808" quede|strong="H3427" allá|strong="H8033" para|strong="H5704" siempre|strong="H5769" .',NULL),
