INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'Y|strong="H3068" ACONTECIÓ|strong="H1961" después|strong="H3427" de la muerte|strong="H4191" de Saúl|strong="H7586" , que|strong="H3117" vuelto|strong="H7725" David|strong="H1732" de la derrota de los|strong="H3427" Amalecitas, estuvo|strong="H1961" dos|strong="H8147" días|strong="H3117" en|strong="H5221" Siclag|strong="H6860" :',NULL),
