INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,19,12,'Vosotros sois|strong="H1961" mis hermanos; mis huesos y mi|strong="H1961" carne sois|strong="H1961" : ¿ por|strong="H1697" qué|strong="H4100" pues|strong="H1961" seréis|strong="H1961" vosotros los|strong="H3605" pos­treros en volver|strong="H7725" al|strong="H4428" rey|strong="H4428" ?',NULL),
