(@vid,@bid,19,27,'Y|strong="H3068" él|strong="H5921" revolvió a|strong="H3068" tu siervo|strong="H5650" delante|strong="H5921" de|strong="H5921" mi|strong="H5921" señor el|strong="H5921" rey|strong="H4428" ; mas|strong="H3588" mi|strong="H5921" señor el|strong="H5921" rey|strong="H4428" es|strong="H3588" como|strong="H3588" un ángel de|strong="H5921" Dios: haz pues|strong="H3588" lo|strong="H5921" que|strong="H3588" bien|strong="H3588" te|strong="H5921" pareciere.',NULL),
(@vid,@bid,19,28,'Porque|strong="H4428" toda la casa de|strong="H5869" mi padre era digna de|strong="H5869" muerte delan­ te|strong="H5869" de|strong="H5869" mi señor el|strong="H6213" rey|strong="H4428" , y tú|strong="H6213" pusiste a|strong="H3068" tu|strong="H6213" siervo|strong="H5650" entre los convidados de|strong="H5869" tu|strong="H6213" mesa. ¿Qué derecho pues tengo aún para quejarme más contra el|strong="H6213" rey|strong="H4428" ?',NULL),
