(@vid,@bid,39,28,'Ella|strong="H5921" habita|strong="H7931" y|strong="H5921" está|strong="H7931" en|strong="H5921" la|strong="H5921" roca|strong="H5553" , en|strong="H5921" la|strong="H5921" cumbre de|strong="H5921" la|strong="H5921" roca|strong="H5553" , en|strong="H5921" lugar seguro.',NULL),
(@vid,@bid,39,29,'Desde allí|strong="H8033" acecha|strong="H2658" la comida: sus ojos|strong="H5869" observan|strong="H5027" de|strong="H5869" muy lejos|strong="H7350" .',NULL),
(@vid,@bid,39,30,'Sus|strong="H1931" pollos chupan|strong="H5966" la|strong="H1931" sangre|strong="H1818" : y donde|strong="H8033" hubiere cadáveres, allí|strong="H8033" está|strong="H1931" .',NULL),
(@vid,@bid,40,1,'A|strong="H3068" MÁS|strong="H6030" de eso respondió|strong="H6030" el SEÑOR|strong="H3068" a|strong="H3068" Job, y dijo:',NULL),
(@vid,@bid,40,2,'¿Es sabiduría contender|strong="H7378" con|strong="H5973" el|strong="H5973" Todopoderoso|strong="H7706" ? El|strong="H5973" que disputa|strong="H7378" con|strong="H5973" Dios, responda|strong="H6030" a|strong="H3068" esto.',NULL),
(@vid,@bid,40,3,'Y|strong="H3068" respondió|strong="H6030" Job al SEÑOR|strong="H3068" , y dijo:',NULL),
(@vid,@bid,40,4,'He aquí|strong="H2005" que|strong="H4100" yo soy vil, ¿ qué|strong="H4100" te responderé? Mi mano|strong="H3027" pongo|strong="H7760" sobre mi boca|strong="H6310" .',NULL),
(@vid,@bid,40,5,'Una vez hablé|strong="H1696" , y no|strong="H3808" responde|strong="H6030" ­ré: aun|strong="H3254" dos|strong="H8147" veces, mas|strong="H3254" no|strong="H3808" torna|strong="H3808" ­ré a|strong="H3068" hablar|strong="H1696" .',NULL);
INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,40,6,'Entonces respondió|strong="H6030" el SEÑOR|strong="H3068" a|strong="H3068" Job desde|strong="H4480" la oscuridad, y dijo:',NULL),
(@vid,@bid,40,7,'Cíñete ahora|strong="H4994" como varón|strong="H1397" tus lomos|strong="H2504" ; yo|strong="H4994" te preguntaré|strong="H7592" , y explí­came.',NULL),
(@vid,@bid,40,8,'¿ Invalidarás|strong="H6565" tú también mi jui­cio? ¿me condenarás a|strong="H3068" mí, para|strong="H4616" justificarte a|strong="H3068" ti?',NULL),
(@vid,@bid,40,9,'¿Tienes tú brazo|strong="H2220" como|strong="H3644" Dios? ¿y tronarás tú con voz|strong="H6963" como|strong="H3644" él?',NULL),
(@vid,@bid,40,10,'Atavíate ahora|strong="H4994" de|strong="H3847" majestad y de|strong="H3847" alteza: y vístete|strong="H3847" de|strong="H3847" honra|strong="H1935" y de|strong="H3847" hermosura|strong="H1926" .',NULL),
(@vid,@bid,40,11,'Esparce|strong="H6327" furores de tu ira: y mira|strong="H7200" a|strong="H3068" todo|strong="H3605" soberbio|strong="H1343" , y abátelo.',NULL),
(@vid,@bid,40,12,'Mira|strong="H7200" a|strong="H3068" todo|strong="H3605" soberbio|strong="H1343" , y humí­llalo, y quebranta a|strong="H3068" los|strong="H3605" impíos|strong="H7563" en|strong="H8478" su asiento.',NULL),
(@vid,@bid,40,13,'Encúbrelos|strong="H2934" a|strong="H3068" todos|strong="H3162" en el polvo|strong="H6083" , venda sus rostros|strong="H6440" en la oscuridad;',NULL),
(@vid,@bid,40,14,'Y|strong="H3068" yo|strong="H3588" también|strong="H1571" te|strong="H3588" confesaré|strong="H3034" que|strong="H3588" podrá salvarte tu diestra|strong="H3225" .',NULL),
(@vid,@bid,40,15,'He aquí|strong="H2009" ahora|strong="H4994" behemot, al cual|strong="H5973" yo|strong="H2009" hice|strong="H6213" contigo|strong="H5973" ; hierba|strong="H2682" come como|strong="H5973" buey.',NULL),
(@vid,@bid,40,16,'He aquí|strong="H2009" ahora|strong="H4994" que|strong="H4994" su fuerza|strong="H3581" está en sus lomos|strong="H4975" , y su fortaleza|strong="H3581" en el ombligo de su vientre.',NULL),
(@vid,@bid,40,17,'Su cola|strong="H2180" mueve|strong="H2654" como|strong="H3644" un cedro, y los nervios de sus geni­tales son entretejidos.',NULL),
(@vid,@bid,40,18,'Sus huesos|strong="H6106" son fuertes c omo latón, y sus miembros como barras de hierro|strong="H1270" .',NULL),
(@vid,@bid,40,19,'Él|strong="H1931" es|strong="H1931" la|strong="H1931" cabeza|strong="H7225" de los|strong="H1931" caminos|strong="H1870" de Dios: el|strong="H1931" que|strong="H1931" lo|strong="H1931" hizo|strong="H6213" , puede hacer|strong="H6213" que|strong="H1931" su|strong="H1931" espada|strong="H2719" a|strong="H3068" él|strong="H1931" se|strong="H1931" acer­ que|strong="H1931" .',NULL),
(@vid,@bid,40,20,'Ciertamente|strong="H3588" los|strong="H3605" montes|strong="H2022" pro­ducen hierba para|strong="H3588" él|strong="H3588" : y|strong="H3588" toda|strong="H3605" bes­tia del campo|strong="H7704" retoza|strong="H7832" allá|strong="H8033" .',NULL),
(@vid,@bid,40,21,'Echaráse|strong="H7901" debajo|strong="H8478" de|strong="H8478" las som­bras, en|strong="H8478" lo oculto de|strong="H8478" las cañas|strong="H7070" , y de|strong="H8478" los lugares húmedos.',NULL),
(@vid,@bid,40,22,'Los árboles sombríos lo cubren con su sombra; los sauces del arroyo|strong="H5158" lo cercan|strong="H5437" .',NULL),
(@vid,@bid,40,23,'He aquí|strong="H2005" que|strong="H3588" él|strong="H3588" tomará el|strong="H3588" río|strong="H5104" sin|strong="H3808" inmutarse|strong="H2648" : y|strong="H3588" confíase que|strong="H3588" el|strong="H3588" Jordán|strong="H3383" pasará|strong="H1518" por|strong="H3588" su|strong="H3588" boca|strong="H6310" .',NULL),
(@vid,@bid,40,24,'¿ Tomarálo|strong="H3947" alguno por sus ojos|strong="H5869" en armadijos, y horadará su nariz?',NULL),
(@vid,@bid,41,1,'¿SACARÁS tú al leviatán con|strong="H1571" el|strong="H1571" anzuelo, o|strong="H3068" con|strong="H1571" la|strong="H1571" cuerda que|strong="H1571" le echares en su lengua?',NULL),
(@vid,@bid,41,2,'¿Pondrás tú garfio en|strong="H3588" sus|strong="H1931" nari­ces, y|strong="H3588" horadarás con|strong="H3588" espinas su|strong="H1931" quijada?',NULL),
(@vid,@bid,41,3,'¿Multiplicará él|strong="H1931" ruegos para contigo? ¿hablaráte él|strong="H1931" lisonjas?',NULL),
(@vid,@bid,41,4,'¿Hará concierto contigo para que|strong="H3808" lo|strong="H1697" tomes por|strong="H1697" siervo perpe­tuo?',NULL),
(@vid,@bid,41,5,'¿Jugarás tú con él|strong="H4310" como con pájaro, o|strong="H3068" lo atarás para tus niñas?',NULL),
(@vid,@bid,41,6,'¿Harán de|strong="H6440" él|strong="H4310" banquete los com­pañeros? ¿partiránlo entre los mercaderes?',NULL),
(@vid,@bid,41,7,'¿Podrás tú llenarle el cuero de garrochas, o|strong="H3068" con arpón de pesca­dores su cabeza?',NULL),
(@vid,@bid,41,8,'Pon tu mano sobre él|strong="H5066" ; te acor­darás de la batalla, y nunca|strong="H3808" más|strong="H3808" tornarás.',NULL),
(@vid,@bid,41,9,'He aquí que|strong="H3808" la esperanza acer­ca de él será|strong="H3808" burlada: porque|strong="H3808" aun|strong="H3808" a|strong="H3068" su sola vista se|strong="H3808" desmayarán.',NULL),
(@vid,@bid,41,10,'Nadie|strong="H5869" hay tan osado que lo despierte: ¿quién pues podrá estar delante|strong="H5869" de|strong="H5869" mí?',NULL),
(@vid,@bid,41,11,'¿Quién me ha anticipado, para que|strong="H6310" yo restituya? Todo lo que hay debajo del cielo es mío.',NULL),
(@vid,@bid,41,12,'Yo no callaré sus miembros, ni lo de sus fuerzas y la gracia de su disposición.',NULL),
(@vid,@bid,41,13,'¿Quién descubrirá la delante­ra de su vestidura? ¿quién se lle­gará a|strong="H3068" él con freno doble?',NULL),
(@vid,@bid,41,14,'¿Quién abrirá las puertas de|strong="H6440" su rostro|strong="H6440" ? Los órdenes de|strong="H6440" sus dientes espantan.',NULL),
(@vid,@bid,41,15,'Sus escamas son su orgullo, cerrados entre|strong="H5921" sí|strong="H5921" estrechamente.',NULL),
(@vid,@bid,41,16,'El uno se junta con el otro, que viento no entra entre ellos.',NULL),
(@vid,@bid,41,17,'Pegado está el uno con el otro, están trabados entre sí, que no se pueden apartar.',NULL),
(@vid,@bid,41,18,'Con sus estornudos encien­den lumbre, y sus ojos son como los párpados del alba.',NULL),
(@vid,@bid,41,19,'De su boca salen hachas de fuego, centellas de fuego proce­den.',NULL),
(@vid,@bid,41,20,'De|strong="H1121" sus narices sale humo, como de|strong="H1121" una olla o|strong="H3068" caldero que|strong="H3808" hierve.',NULL),
(@vid,@bid,41,21,'Su aliento enciende los carbo­nes, y de su boca sale llama.',NULL),
(@vid,@bid,41,22,'En|strong="H5921" su cerviz mora la|strong="H5921" fortale­za, y|strong="H5921" espárcese el|strong="H5921" desaliento delante|strong="H5921" de|strong="H5921" él|strong="H5921" .',NULL),
(@vid,@bid,41,23,'Las partes momias de su carne están apretadas: están en él firmes, y no se mueven.',NULL),
(@vid,@bid,41,24,'Su corazón es firme como una piedra, y fuerte como la muela de abajo.',NULL),
(@vid,@bid,41,25,'De|strong="H5921" su grandeza tienen temor los|strong="H5921" fuertes, y|strong="H5921" a|strong="H3068" causa de|strong="H5921" su desfa­llecimiento hacen|strong="H6213" por|strong="H5921" purificar­ se|strong="H5921" .',NULL),
(@vid,@bid,41,26,'Cuando alguno|strong="H3605" lo|strong="H1931" alcanzare, ni espada, ni lanza, ni dardo, ni coselete durará.',NULL),
(@vid,@bid,41,27,'El hierro estima por pajas, y el latón por leño podrido.',NULL),
(@vid,@bid,41,28,'Saeta no le hace huir; las piedras de honda se le tornan aristas.',NULL),
(@vid,@bid,41,29,'Tiene toda arma por hojaras­cas, y del blandir de la pica se burla.',NULL),
(@vid,@bid,41,30,'Por debajo tiene agudas con­chas; imprime su agudez en el suelo.',NULL),
(@vid,@bid,41,31,'Hace hervir como una olla la profunda mar, y tórnala como una olla de ungüento.',NULL),
(@vid,@bid,41,32,'En pos de sí hace resplande­cer la senda, que parece que el abismo sea cano.',NULL),
(@vid,@bid,41,33,'No hay sobre la tierra su semejante, hecho para nada temer.',NULL),
(@vid,@bid,41,34,'Mira toda cosa alta: él es rey sobre todos los hijos de la soberbia.',NULL),
(@vid,@bid,42,1,'Y|strong="H3068" RESPONDIÓ|strong="H6030" Job al SEÑOR|strong="H3068" , y dijo:',NULL),
(@vid,@bid,42,2,'Yo|strong="H4480" conozco|strong="H3045" que|strong="H3588" todo|strong="H3605" lo|strong="H3808" pue­des, y|strong="H3588" que|strong="H3588" no|strong="H3808" hay pensamiento|strong="H4209" que|strong="H3588" se|strong="H3045" esconda de|strong="H4480" ti|strong="H4480" .',NULL),
(@vid,@bid,42,3,'¿ Quién|strong="H4310" es|strong="H2088" el|strong="H4310" que|strong="H4480" oscurece el|strong="H4310" consejo|strong="H6098" sin|strong="H3808" conocimiento|strong="H1847" ? por|strong="H4480" tanto|strong="H3651" yo|strong="H4480" denunciaba lo|strong="H2088" que|strong="H4480" no|strong="H3808" entendía|strong="H3045" ; cosas|strong="H3045" que|strong="H4480" me|strong="H4480" eran|strong="H3808" ocultas, y que|strong="H4480" no|strong="H3808" las sabía|strong="H3045" .',NULL),
(@vid,@bid,42,4,'Oye|strong="H8085" , te ruego|strong="H4994" , y hablaré|strong="H1696" : te pre­guntaré, y tú me enseñarás.',NULL),
(@vid,@bid,42,5,'De|strong="H5869" oídas te|strong="H5869" había oído|strong="H8085" ; mas|strong="H6258" ahora|strong="H6258" mis ojos|strong="H5869" te|strong="H5869" ven|strong="H7200" .',NULL),
(@vid,@bid,42,6,'Por|strong="H5921" tanto|strong="H3651" me aborrezco|strong="H3988" , y|strong="H5921" me|strong="H5921" arrepiento en|strong="H5921" el|strong="H5921" polvo|strong="H6083" y|strong="H5921" en|strong="H5921" la|strong="H5921" ceniza.',NULL),
(@vid,@bid,42,7,'Y|strong="H3068" aconteció|strong="H1961" que|strong="H3588" después|strong="H1961" que|strong="H3588" habló|strong="H1696" el|strong="H3588" SEÑOR|strong="H3068" estas palabras|strong="H1697" a|strong="H3068" Job, el|strong="H3588" SEÑOR|strong="H3068" dijo|strong="H1696" a|strong="H3068" Elifaz temanita|strong="H8489" : Mi|strong="H1961" ira se|strong="H1961" encendió contra|strong="H1961" ti y|strong="H3588" tus dos|strong="H8147" compañeros|strong="H7453" : porque|strong="H3588" no|strong="H3808" habéis hablado|strong="H1696" por|strong="H3588" mí|strong="H1961" lo|strong="H1697" recto|strong="H3559" , como|strong="H3588" mi|strong="H1961" siervo|strong="H5650" Job.',NULL),
(@vid,@bid,42,8,'Ahora|strong="H6258" pues|strong="H3588" , tomaos|strong="H3947" siete|strong="H7651" bece­rros y|strong="H3588" siete|strong="H7651" carneros, y|strong="H3588" andad|strong="H3212" a|strong="H3068" mi|strong="H5921" siervo|strong="H5650" Job, y|strong="H3588" ofreced holo­causto por|strong="H5921" vosotros|strong="H5973" , y|strong="H3588" mi|strong="H5921" siervo|strong="H5650" Job orará|strong="H6419" por|strong="H5921" vosotros|strong="H5973" ; porque|strong="H3588" de|strong="H5921" cierto|strong="H3588" a|strong="H3068" él|strong="H5921" atenderé para|strong="H5921" no|strong="H3808" trataros|strong="H6213" afrentosamente|strong="H5039" , por|strong="H5921" cuanto|strong="H3588" no|strong="H3808" habéis hablado|strong="H1696" por|strong="H5921" mí|strong="H5921" con|strong="H5973" rectitud|strong="H3559" , como|strong="H3588" mi|strong="H5921" siervo|strong="H5650" Job.',NULL),
(@vid,@bid,42,9,'Fueron|strong="H3212" pues Elifaz temanita|strong="H8489" , y Bildad|strong="H1085" suhita|strong="H7747" , y Zofar nahamatita, e|strong="H3068" hicieron|strong="H6213" como el|strong="H6213" SEÑOR|strong="H3068" les dijo|strong="H1696" : y el|strong="H6213" SEÑOR|strong="H3068" atendió|strong="H5375" a|strong="H3068" Job.',NULL),
(@vid,@bid,42,10,'Y|strong="H3068" mudó el|strong="H3605" SEÑOR|strong="H3068" la|strong="H3605" aflic­ción de Job, orando él|strong="H3605" por|strong="H1157" sus amigos|strong="H7453" : y aumentó al|strong="H1157" doble todas|strong="H3605" las cosas que|strong="H1157" habían sido de Job.',NULL),
(@vid,@bid,42,11,'Y|strong="H3068" vinieron a|strong="H3068" él|strong="H5921" todos|strong="H3605" sus her­manos, y|strong="H5921" todas|strong="H3605" sus hermanas, y|strong="H5921" todos|strong="H3605" los|strong="H5921" que|strong="H5921" antes|strong="H6440" le|strong="H5921" habían conocido|strong="H3045" , y|strong="H5921" comieron con|strong="H5973" él|strong="H5921" pan|strong="H3899" en|strong="H5921" su casa|strong="H1004" , y|strong="H5921" condoliéronse de|strong="H5921" él|strong="H5921" , y|strong="H5921" consoláronle de|strong="H5921" todo|strong="H3605" aquel|strong="H3605" mal|strong="H7451" que|strong="H5921" sobre|strong="H5921" él|strong="H5921" había el|strong="H5921" SEÑOR|strong="H3068" tra­ído; y|strong="H5921" cada|strong="H3605" uno de|strong="H5921" ellos|strong="H5921" le|strong="H5921" dio|strong="H5414" una pieza de|strong="H5921" moneda, y|strong="H5921" un zarci­llo de|strong="H5921" oro|strong="H2091" .',NULL),
(@vid,@bid,42,12,'Y|strong="H3068" bendijo|strong="H1288" el SEÑOR|strong="H3068" la pos­trimería de Job más que|strong="H1961" su prin­cipio; porque tuvo|strong="H1961" catorce mil ovejas|strong="H6629" , y|strong="H1241" seis|strong="H8337" mil camellos|strong="H1581" , y|strong="H1241" mil yuntas|strong="H6776" de bueyes|strong="H1241" , y|strong="H1241" mil asnas.',NULL),
