(@vid,@bid,42,15,'Y|strong="H3068" no|strong="H3808" se|strong="H3808" hallaron|strong="H4672" mujeres|strong="H1323" tan hermosas|strong="H3303" como las|strong="H1992" hijas|strong="H1323" de|strong="H5414" Job en|strong="H8432" toda|strong="H3605" la|strong="H3605" tierra: y dióles|strong="H5414" su|strong="H1992" padre herencia|strong="H5159" entre|strong="H8432" sus|strong="H1992" hermanos.',NULL),
(@vid,@bid,42,16,'Y|strong="H3068" después de|strong="H1121" esto|strong="H2063" vivió|strong="H2421" Job ciento|strong="H3967" y cuarenta años|strong="H8141" , y vio|strong="H7200" a|strong="H3068" sus hijos|strong="H1121" , y a|strong="H3068" los|strong="H1121" hijos|strong="H1121" de|strong="H1121" sus hijos|strong="H1121" , hasta la|strong="H2063" cuarta generación|strong="H1755" .',NULL),
(@vid,@bid,42,17,'Murió|strong="H4191" pues Job viejo|strong="H2205" , y lleno|strong="H7649" de días|strong="H3117" .',NULL);
INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'BIENAVENTURADO es el|strong="H3427" varón que|strong="H3808" no|strong="H3808" anda|strong="H1980" en|strong="H5975" consejo|strong="H6098" de impíos|strong="H7563" , ni|strong="H3808" se|strong="H3808" para en|strong="H5975" camino|strong="H1870" de pecadores|strong="H2400" , ni|strong="H3808" en|strong="H5975" silla de escarnecedores se|strong="H3808" sienta.',NULL),
