(@vid,@bid,18,4,'Cercáronme dolores de|strong="H4480" muerte, y torrentes de|strong="H4480" hombres impíos me|strong="H4480" atemorizaron.',NULL),
(@vid,@bid,18,5,'Dolores|strong="H2256" del infierno me rodea­ron, me previnieron lazos de muerte|strong="H4194" .',NULL),
(@vid,@bid,18,6,'En mi angustia invoqué al SEÑOR, y clamé a|strong="H3068" mi Dios: él oyó mi voz desde su templo, y mi clamor llegó delante|strong="H6923" de él, a|strong="H3068" sus oídos.',NULL),
(@vid,@bid,18,7,'Entonces la tierra se estremeció y tembló; también los fundamentos de|strong="H6440" las colinas se movieron y se estremecieron, porque|strong="H6440" se indignó él.',NULL),
(@vid,@bid,18,8,'Humo subió de|strong="H3588" su|strong="H3588" nariz, y|strong="H3588" de|strong="H3588" su|strong="H3588" boca fuego devoró; carbones fueron por|strong="H3588" él|strong="H3588" encendidos.',NULL),
(@vid,@bid,18,9,'E|strong="H3068" inclinó los cielos y|strong="H1197" descendió; y|strong="H1197" la|strong="H1197" oscuridad estaba debajo de|strong="H4480" sus pies.',NULL),
(@vid,@bid,18,10,'Y|strong="H3068" cabalgó sobre un querubín, y voló: sí, él voló sobre las alas del viento.',NULL),
(@vid,@bid,18,11,'Hizo de|strong="H5921" las|strong="H5921" tinieblas su escondedero, su pabellón en|strong="H5921" derredor de|strong="H5921" sí|strong="H5921" eran aguas oscuras y nubes espesas de|strong="H5921" los|strong="H5921" cielos.',NULL),
(@vid,@bid,18,12,'Por el resplandor delante de|strong="H4325" él, sus nubes|strong="H5645" espesas pasaron; granizo y carbones de|strong="H4325" fuego.',NULL),
(@vid,@bid,18,13,'Y|strong="H3068" tronó en los cielos el|strong="H5674" SEÑOR, y el|strong="H5674" Altísimo dio su voz; granizo|strong="H1259" y carbones|strong="H1513" de|strong="H5048" fuego.',NULL),
(@vid,@bid,18,14,'Sí, envió sus saetas, y los dispersó, él lanzó relámpagos y los desconcertó.',NULL),
(@vid,@bid,18,15,'Entonces fueron vistos los canales de aguas, y fueron descubiertos las fundaciones del mundo a|strong="H3068" tu reprensión, oh SEÑOR, por el soplo del aliento de tu nariz.',NULL),
