(@vid,@bid,18,17,'Libróme de|strong="H4325" mi poderoso ene­migo, y de|strong="H4325" los que|strong="H4325" me aborrecí­an, pues|strong="H7971" eran ellos más|strong="H7227" fuertes que|strong="H4325" yo.',NULL),
(@vid,@bid,18,18,'Me|strong="H4480" impidieron en|strong="H4480" el|strong="H3588" día de|strong="H4480" mi calamidad; pero|strong="H3588" el|strong="H3588" SEÑOR fue mi apoyo.',NULL),
(@vid,@bid,18,19,'Y|strong="H3068" sacóme a|strong="H3068" lugar espacioso; libróme porque se|strong="H1961" deleitó en mí|strong="H1961" .',NULL),
(@vid,@bid,18,20,'Me|strong="H3588" recompensó el|strong="H3588" SEÑOR conforme a|strong="H3068" mi justicia: conforme a|strong="H3068" la|strong="H3588" limpieza de|strong="H3588" mis manos me|strong="H3588" ha recompensado.',NULL),
(@vid,@bid,18,21,'Porque yo he guardado los caminos del SEÑOR|strong="H3068" , y no me aparté impíamente de mi Dios|strong="H3068" .',NULL),
(@vid,@bid,18,22,'Pues|strong="H3588" todos sus juicios estuvie­ron delante de|strong="H3588" mí, y|strong="H3588" no|strong="H3808" eché de|strong="H3588" mí sus estatutos.',NULL),
(@vid,@bid,18,23,'También fui|strong="H3808" recto delante|strong="H5048" de|strong="H4480" él|strong="H3588" , y|strong="H3588" me|strong="H4480" guardé de|strong="H4480" mi iniquidad.',NULL),
(@vid,@bid,18,24,'Por tanto me|strong="H5973" ha recompensado el|strong="H5973" SEÑOR conforme a|strong="H3068" mi|strong="H1961" justicia; conforme a|strong="H3068" la|strong="H8104" limpieza de|strong="H5973" mis manos delan­ te|strong="H5973" de|strong="H5973" sus ojos.',NULL),
(@vid,@bid,18,25,'Con el misericordioso te|strong="H5869" mos­trarás misericordioso, y recto para con el hombre recto.',NULL),
(@vid,@bid,18,26,'Puro te|strong="H5973" mostrarás para|strong="H5973" con|strong="H5973" el|strong="H5973" puro, y desagradable te|strong="H5973" mostrarás para|strong="H5973" con|strong="H5973" el|strong="H5973" perverso.',NULL),
(@vid,@bid,18,27,'Pues tú salvarás al pueblo|strong="H5973" afligido, y humillarás los|strong="H5973" ojos altivos.',NULL),
(@vid,@bid,18,28,'Tú pues|strong="H3588" alumbrarás mi lám­ para|strong="H3588" : el|strong="H3588" SEÑOR mi Dios alum­brará mis tinieblas.',NULL),
(@vid,@bid,18,29,'Pues|strong="H3588" por|strong="H3588" ti he corrido a|strong="H3068" través de|strong="H3588" una tropa; y|strong="H3588" por|strong="H3588" mi Dios|strong="H3068" he saltado sobre|strong="H5050" un muro.',NULL),
(@vid,@bid,18,30,'En cuanto a Dios, perfecto es su|strong="H3588" camino: la|strong="H3588" palabra del SEÑOR es refinada: él|strong="H3588" es escudo a|strong="H3068" todos los|strong="H3588" que|strong="H3588" en|strong="H3588" él|strong="H3588" confían.',NULL),
(@vid,@bid,18,31,'Porque ¿ quién|strong="H3605" es Dios|strong="H3068" fuera del SEÑOR|strong="H3068" ? ¿ O|strong="H3068" quién|strong="H3605" es una roca fuera de nuestro Dios|strong="H3068" ?',NULL),
(@vid,@bid,18,32,'Dios|strong="H3068" es el|strong="H3588" que|strong="H3588" me|strong="H3588" ciñe de|strong="H3588" fuerza, y|strong="H3588" hace perfecto mi cami­ no|strong="H3588" .',NULL),
(@vid,@bid,18,33,'Él hace mis|strong="H5414" pies como de|strong="H5414" ciervas, y me pone sobre mis|strong="H5414" alturas.',NULL),
(@vid,@bid,18,34,'Él|strong="H5921" enseña mis manos para|strong="H5921" la|strong="H5921" guerra, de|strong="H5921" modo que|strong="H5921" es|strong="H5975" quebrado con|strong="H5921" mis brazos el|strong="H5921" arco de|strong="H5921" acero.',NULL),
(@vid,@bid,18,35,'Tú me diste asimismo el escudo de tu salvación: y tu diestra me sustentó, y tu gentileza me ha engrandecido.',NULL),
(@vid,@bid,18,36,'Ensanchaste mis|strong="H5414" pasos debajo de|strong="H5414" mí, para|strong="H5414" que mis|strong="H5414" pies no resbalasen.',NULL),
(@vid,@bid,18,37,'Yo he perseguido a|strong="H3068" mis enemigos, y los he atrapado: y no|strong="H3808" me volví hasta que|strong="H3808" fueron consumidos.',NULL),
(@vid,@bid,18,38,'Yo los|strong="H7291" herí, de|strong="H5704" modo que|strong="H3808" no|strong="H3808" pudieron levantarse: son|strong="H3808" caídos debajo de|strong="H5704" mis pies.',NULL),
(@vid,@bid,18,39,'Pues, me ceñiste con fuerza para la batalla; has sometido debajo|strong="H8478" de|strong="H8478" mí a|strong="H3068" los que|strong="H3808" se|strong="H3808" levantaron|strong="H6965" contra mí.',NULL),
(@vid,@bid,18,40,'También me has dado la cerviz de|strong="H8478" mis enemigos, para que yo destruya a|strong="H3068" los que me aborrecen.',NULL),
(@vid,@bid,18,41,'Clamaron, pero no hubo quien los salvase: aun al SEÑOR, pero él no les respondió.',NULL),
(@vid,@bid,18,42,'Entonces los|strong="H5921" molí como|strong="H5921" polvo delante|strong="H5921" del|strong="H5921" viento, los|strong="H5921" arrojé como|strong="H5921" la|strong="H5921" tierra en|strong="H5921" las|strong="H5921" calles.',NULL),
(@vid,@bid,18,43,'Me|strong="H5921" libraste de|strong="H5921" las|strong="H5921" contiendas del|strong="H5921" pueblo: me|strong="H5921" has puesto por|strong="H5921" cabecera de|strong="H5921" los|strong="H5921" paganos: un pueblo que no|strong="H5921" he conocido me|strong="H5921" servirá.',NULL),
(@vid,@bid,18,44,'Así que|strong="H3808" oigan de|strong="H5971" mí, me obedecerán: los extranjeros se|strong="H3045" someterán a|strong="H3068" mí.',NULL),
