(@vid,@bid,18,47,'Es Dios|strong="H3068" el que me venga y somete a|strong="H3068" la gente debajo de mí.',NULL),
(@vid,@bid,18,48,'Me libra de|strong="H8478" mis|strong="H5414" enemigos: sí, tú me enalteces sobre los que|strong="H5971" se|strong="H5971" levantan contra mí; me has|strong="H5414" librado del hombre violento.',NULL),
(@vid,@bid,18,49,'Por|strong="H4480" tanto yo|strong="H4480" te|strong="H4480" daré gracias entre|strong="H4480" los paganos, oh SEÑOR, y cantaré alabanzas a|strong="H3068" tu nombre.',NULL),
(@vid,@bid,18,50,'Grande liberación da a|strong="H3068" su rey, y|strong="H5921" muestra misericordia a|strong="H3068" su ungido, a|strong="H3068" David y|strong="H5921" a|strong="H3068" su simiente, para|strong="H5921" siempre|strong="H5921" .',NULL),
(@vid,@bid,19,1,'Al Músico principal: Salmo de David. LOS cielos declaran la gloria de Dios, y el firmamento muestra la obra de sus manos.',NULL),
(@vid,@bid,19,2,'Día tras día emite palabra; noche tras noche muestra|strong="H5046" conocimiento.',NULL),
