(@vid,@bid,19,5,'Lo|strong="H4405" cual como un novio que|strong="H3605" sale|strong="H3318" de su tálamo, y se regocija como hombre fuerte para correr una carrera.',NULL),
(@vid,@bid,19,6,'Del cabo del cielo es su|strong="H1931" salida|strong="H3318" , y su|strong="H1931" curso hasta|strong="H1931" el|strong="H1931" cabo de él|strong="H1931" : y no hay quién|strong="H1931" se|strong="H1931" esconda de su|strong="H1931" calor.',NULL),
(@vid,@bid,19,7,'La|strong="H5921" ley del|strong="H5921" SEÑOR es perfecta, que|strong="H5921" convierte el|strong="H5921" alma: el|strong="H5921" testimo­nio del|strong="H5921" SEÑOR es seguro, que|strong="H5921" hace sabio al|strong="H5921" simple.',NULL),
(@vid,@bid,19,8,'Los estatutos del SEÑOR|strong="H3068" son rectos, que regocijan el corazón|strong="H5315" : el mandamiento del SEÑOR|strong="H3068" es puro, que alumbra los ojos.',NULL),
(@vid,@bid,19,9,'El temor del SEÑOR|strong="H3068" es limpio|strong="H1249" , que permanece para siempre; los juicios del SEÑOR|strong="H3068" son verdad, todos justos.',NULL),
