(@vid,@bid,21,6,'Porque|strong="H5921" lo|strong="H5921" has bendecido para|strong="H5921" siempre|strong="H5921" ; llenástelo de|strong="H5921" alegría con|strong="H5921" tu rostro.',NULL),
(@vid,@bid,21,7,'Por|strong="H3588" cuanto|strong="H3588" el|strong="H3588" rey confía en|strong="H3588" el|strong="H3588" SEÑOR, y|strong="H3588" por|strong="H3588" la|strong="H3588" misericordia del Altísimo, no|strong="H3588" será|strong="H1293" conmovido.',NULL),
(@vid,@bid,21,8,'Alcanzará tu mano a|strong="H3068" todos tus enemigos; tu diestra alcanzará a|strong="H3068" los|strong="H3588" que|strong="H3588" te|strong="H3588" aborrecen.',NULL),
