(@vid,@bid,22,2,'Dios mío, clamo de|strong="H1697" día, y no|strong="H4100" oyes; y de|strong="H1697" noche, y no|strong="H4100" hay para mí silencio.',NULL),
(@vid,@bid,22,3,'Pero tú eres santo, tú que|strong="H3808" habitas entre las alabanzas de Israel.',NULL),
