(@vid,@bid,22,8,'Remítese al SEÑOR, líbrelo; sálvele, puesto que|strong="H3605" en él|strong="H3605" se com­placía.',NULL),
(@vid,@bid,22,9,'Pero|strong="H3588" tú eres el|strong="H3588" que|strong="H3588" me|strong="H3588" sacó del vientre, el|strong="H3588" que|strong="H3588" me|strong="H3588" haces esperar desde que estaba a|strong="H3068" los|strong="H3588" pechos de|strong="H3588" mi madre.',NULL),
(@vid,@bid,22,10,'Sobre|strong="H5921" ti|strong="H5921" fui echado desde|strong="H5921" la|strong="H5921" matriz: desde|strong="H5921" el|strong="H5921" vientre de|strong="H5921" mi|strong="H5921" madre, tú eres mi|strong="H5921" Dios.',NULL),
(@vid,@bid,22,11,'No|strong="H5921" te|strong="H5921" alejes de|strong="H5921" mí|strong="H5921" , porque|strong="H5921" la|strong="H5921" angustia está|strong="H5921" cerca|strong="H5921" ; porque|strong="H5921" no|strong="H5921" hay quien ayude.',NULL),
(@vid,@bid,22,12,'Hanme rodeado muchos toros; fuertes toros de|strong="H4480" Basán me|strong="H4480" han cercado.',NULL),
