(@vid,@bid,22,18,'Partieron entre sí mis vestiduras|strong="H1992" , y sobre mi ropa echaron suertes.',NULL),
(@vid,@bid,22,19,'Mas|strong="H5921" tú, oh SEÑOR, no|strong="H5921" te|strong="H5921" alejes; fortaleza mía, apresúrate para|strong="H5921" mi|strong="H5921" ayuda.',NULL),
