INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,36,2,'Lisonjéase, por tanto, en sus propios ojos|strong="H5869" , hasta que|strong="H6343" su iniqui­dad sea hallada aborrecible.',NULL),
