(@vid,@bid,46,9,'Que hace cesar las guerras hasta los fines de la tierra: que quiebra el arco, corta la lanza, y quema los carros en|strong="H3212" el fuego.',NULL),
(@vid,@bid,46,10,'Estad quietos, y|strong="H5704" conoced que|strong="H5704" yo soy Dios: ensalzado he de|strong="H5704" ser entre las gentes, ensalzado seré en|strong="H5704" la tierra.',NULL),
(@vid,@bid,46,11,'El|strong="H3588" SEÑOR de|strong="H3588" los|strong="H3588" ejércitos es|strong="H3588" con|strong="H3588" nosotros; nuestro refugio es|strong="H3588" el|strong="H3588" Dios de|strong="H3588" Jacob. Selah.',NULL),
(@vid,@bid,47,1,'Al Músico principal: de los hijos de Coré: Salmo. PUEBLOS todos, batid las manos; aclamad a|strong="H3068" Dios con voz de|strong="H1121" júbilo.',NULL),
(@vid,@bid,47,2,'Porque el|strong="H3605" SEÑOR el|strong="H3605" Altísimo es terrible; Rey grande sobre toda|strong="H3605" la|strong="H3605" tierra.',NULL),
(@vid,@bid,47,3,'Él|strong="H5921" sujetará a|strong="H3068" los|strong="H5921" pueblos deba­jo de|strong="H5921" nosotros|strong="H3605" , y|strong="H3588" a|strong="H3068" las|strong="H5921" naciones debajo de|strong="H5921" nuestros pies.',NULL),
(@vid,@bid,47,4,'Él nos elegirá nuestras hereda­des; la hermosura de|strong="H8478" Jacob, al|strong="H8478" cual amó. Selah.',NULL),
