(@vid,@bid,47,6,'Cantad a|strong="H3068" Dios|strong="H3068" , cantad: cantad a|strong="H3068" nuestro Rey, cantad.',NULL),
(@vid,@bid,47,7,'Porque|strong="H4428" Dios es el Rey|strong="H4428" de toda la tierra: cantad|strong="H2167" con el entendi­miento.',NULL),
(@vid,@bid,47,8,'Reina|strong="H4428" Dios sobre las gentes: Dios está sentado sobre el|strong="H3588" trono de|strong="H3588" su|strong="H3588" santidad.',NULL),
(@vid,@bid,47,9,'Los|strong="H3427" príncipes de|strong="H5921" los|strong="H3427" pueblos|strong="H1471" se|strong="H5921" juntaron al|strong="H5921" pueblo del|strong="H5921" Dios de|strong="H5921" Abraham: porque|strong="H5921" de|strong="H5921" Dios son los|strong="H3427" escudos de|strong="H5921" la|strong="H5921" tierra; él|strong="H5921" es muy ensalzado.',NULL),
(@vid,@bid,48,1,'Canción: Salmo de los hijos de Coré. GRANDE es el|strong="H1121" SEÑOR y digno de|strong="H1121" ser en gran manera alabado, en la ciudad de|strong="H1121" nuestro Dios, en el|strong="H1121" monte de|strong="H1121" su santidad.',NULL),
(@vid,@bid,48,2,'Hermosa provincia, el gozo de toda la tierra es el monte|strong="H2022" de Sión, a|strong="H3068" los lados del norte, la ciudad|strong="H5892" del gran|strong="H1419" Rey.',NULL),
(@vid,@bid,48,3,'Dios en sus palacios es conoci­do por|strong="H4428" refugio.',NULL),
(@vid,@bid,48,4,'Porque he aquí los reyes de la tierra se|strong="H3045" reunieron; pasaron todos.',NULL),
(@vid,@bid,48,5,'Y|strong="H3068" viéndola ellos así|strong="H3588" , maravillá­ronse, se turbaron, diéronse prie­sa a huir .',NULL),
