(@vid,@bid,49,5,'¿Por qué he de temer en los días de adversidad, cuando la iniquidad de mis insidiadores me cercare?',NULL),
(@vid,@bid,49,6,'Los que|strong="H4100" confían en sus hacien­das, y en la muchedumbre de|strong="H3372" sus riquezas se|strong="H4100" jactan,',NULL),
(@vid,@bid,49,7,'Ninguno de|strong="H5921" ellos podrá en|strong="H5921" manera alguna redimir al|strong="H5921" herma­ no|strong="H5921" , ni dar a|strong="H3068" Dios su rescate.',NULL),
(@vid,@bid,49,8,'( Porque|strong="H3808" la redención|strong="H3724" de|strong="H5414" su alma es de|strong="H5414" gran precio|strong="H3724" , y no|strong="H3808" se|strong="H3808" hará|strong="H5414" jamás|strong="H3808" ;)',NULL),
(@vid,@bid,49,9,'Que viva adelante para siem­pre, y no|strong="H2308" vea la corrupción.',NULL),
(@vid,@bid,49,10,'Pues|strong="H7200" se|strong="H3808" ve|strong="H7200" que|strong="H3808" mueren los sabios, así como|strong="H5750" el necio y el bruto perecen, y dejan a|strong="H3068" otros|strong="H5750" sus riquezas.',NULL),
(@vid,@bid,49,11,'En|strong="H3588" su|strong="H3588" interior tienen que|strong="H3588" sus casas serán eternas, y|strong="H3588" sus habita­ciones para|strong="H3588" generación y|strong="H3588" genera­ción: llamaron sus tierras de|strong="H3588" sus nombres.',NULL),
(@vid,@bid,49,12,'Mas|strong="H5921" el|strong="H5921" hombre no|strong="H5921" permanecerá en|strong="H5921" honra: es semejante a|strong="H3068" las|strong="H5921" bestias que|strong="H5921" perecen.',NULL),
(@vid,@bid,49,13,'Este su camino es su locura: con todo, corren sus descendien­tes por el|strong="H3885" dicho de ellos. Selah.',NULL),
(@vid,@bid,49,14,'Como rebaños serán|strong="H6310" puestos en la sepultura; la muerte se cebará en ellos; y los rectos se enseñorearán de ellos por|strong="H1870" la mañana: y se consumirá su bien parecer en el sepulcro de su morada.',NULL),
(@vid,@bid,49,15,'Pero Dios redimirá mi alma del poder de la sepultura, por­que él me recibirá. Selah.',NULL),
(@vid,@bid,49,16,'No|strong="H3588" temas cuando|strong="H3588" se enrique­ce alguno|strong="H5315" , cuando|strong="H3588" aumenta la|strong="H3588" gloria de|strong="H3588" su|strong="H3588" casa;',NULL),
(@vid,@bid,49,17,'Porque|strong="H3588" en|strong="H3588" muriendo no|strong="H3588" lleva­rá nada, ni descenderá tras él|strong="H3588" su|strong="H3588" gloria|strong="H3519" .',NULL),
(@vid,@bid,49,18,'Si|strong="H3588" bien|strong="H3588" mientras|strong="H3588" viviere, dirá dichosa a|strong="H3068" su|strong="H3588" alma|strong="H3605" : y|strong="H3588" tú serás loado cuando|strong="H3588" bien|strong="H3588" te|strong="H3588" tratares.',NULL),
(@vid,@bid,49,19,'Entrará a|strong="H3068" la|strong="H3588" generación de|strong="H3588" sus padres: no|strong="H3588" verán luz para|strong="H3588" siem­pre.',NULL),
(@vid,@bid,49,20,'El hombre en|strong="H5704" honra que|strong="H3808" no|strong="H3808" entiende, semejante es a|strong="H3068" las bes­tias que|strong="H3808" perecen.',NULL),
(@vid,@bid,50,1,'Salmo de Asaf. EL Dios|strong="H3068" poderoso, el SEÑOR|strong="H3068" , ha hablado|strong="H1696" , y|strong="H5704" convocado la tierra desde|strong="H5704" el nacimiento del sol|strong="H8121" hasta|strong="H5704" donde se pone.',NULL),
(@vid,@bid,50,2,'De Sión|strong="H6726" , perfección|strong="H4359" de hermo­sura, ha Dios resplandecido|strong="H3313" .',NULL),
