(@vid,@bid,59,3,'Porque he aquí están acechan­do mi vida: hanse juntado contra mí fuertes, no por falta mía, ni pecado mío, oh SEÑOR.',NULL),
(@vid,@bid,59,4,'Sin|strong="H3808" delito mío corren y|strong="H3588" se|strong="H5921" aperciben: despierta para|strong="H5921" venir a|strong="H3068" mi|strong="H5921" encuentro, y|strong="H3588" mira|strong="H2009" .',NULL),
(@vid,@bid,59,5,'Y|strong="H3068" tú oh SEÑOR, Dios de los ejérci­tos, Dios de Israel, despierta|strong="H5782" para visitar todas las gentes: no|strong="H1097" hayas misericordia de todos los que se rebelan con iniquidad|strong="H5771" . Selah.',NULL),
