(@vid,@bid,59,8,'Mas|strong="H3588" tú, oh|strong="H4310" SEÑOR, te|strong="H3588" reirás de|strong="H3588" ellos, te|strong="H3588" burlarás de|strong="H3588" todos los|strong="H3588" paganos.',NULL),
(@vid,@bid,59,9,'De su fuerza esperaré yo en ti: porque Dios|strong="H3068" es mi defensa.',NULL),
(@vid,@bid,59,10,'El|strong="H3588" Dios de|strong="H3588" mi misericordia me|strong="H3588" prevendrá: Dios me|strong="H3588" hará|strong="H8104" ver en|strong="H3588" mis enemigos mi deseo .',NULL),
(@vid,@bid,59,11,'No los matarás, porque mi pueblo no se olvide: hazlos vagar con tu fortaleza; y abátelos, oh Señor, escudo nuestro,',NULL),
(@vid,@bid,59,12,'Por el pecado de|strong="H5971" su boca, por la palabra de|strong="H5971" sus labios; y sean presos por su soberbia, y por la maldición y mentira que|strong="H6435" profie­ren.',NULL),
(@vid,@bid,59,13,'Acábalos con furor, acábalos, y no sean: y sepan que|strong="H1697" Dios domina en Jacob hasta los fines de|strong="H1697" la tierra. Selah.',NULL),
(@vid,@bid,59,14,'Vuelvan pues|strong="H3588" a|strong="H3068" la|strong="H3588" tarde, y|strong="H3588" ladren como|strong="H3588" perros, y|strong="H3588" rodeen la|strong="H3588" ciudad.',NULL),
