(@vid,@bid,59,16,'Pero yo cantaré tu fortaleza, y loaré de|strong="H7646" mañana tu miseri­cordia: porque|strong="H3808" has sido mi ampa­ro y refugio en el|strong="H3885" día de|strong="H7646" mi angustia.',NULL),
(@vid,@bid,59,17,'Fortaleza|strong="H5797" mía, a|strong="H3068" ti cantaré|strong="H7891" ; porque|strong="H3588" eres|strong="H1961" Dios de|strong="H3588" mi|strong="H1961" amparo|strong="H4869" , Dios de|strong="H3588" mi|strong="H1961" misericordia|strong="H2617" .',NULL),
(@vid,@bid,60,1,'Al Músico principal: sobre Susan-­Edut: Mictam de David, para ense­ñar, cuando tuvo guerra contra Aram­-Naharaim y contra Aram de Soba, y volvió Joab, e hirió de Edom en el valle de las Salinas doce mil. OH Dios, tú nos|strong="H5921" has desechado, nos|strong="H5921" disipaste; te|strong="H5921" has airado: vuélvete a|strong="H3068" nosotros|strong="H5921" .',NULL),
