(@vid,@bid,12,14,'Porque|strong="H3588" Dios traerá toda|strong="H3605" obra|strong="H4639" a|strong="H3068" juicio|strong="H4941" , el cual se hará sobre|strong="H5921" toda|strong="H3605" cosa|strong="H3605" oculta, buena|strong="H2896" o|strong="H3068" mala|strong="H7451" .',NULL);
INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'CANCIÓN|strong="H7892" de canciones|strong="H7892" , la cual es de Salomón|strong="H8010" .',NULL),
(@vid,@bid,1,2,'¡Oh si|strong="H3588" él|strong="H3588" me|strong="H3588" besara con|strong="H3588" besos de|strong="H3588" su|strong="H3588" boca|strong="H6310" ! Porque|strong="H3588" mejores|strong="H2896" son|strong="H3588" tus amores que|strong="H3588" el|strong="H3588" vino|strong="H3196" .',NULL),
(@vid,@bid,1,3,'Por|strong="H5921" el|strong="H5921" olor|strong="H7381" de|strong="H5921" tus suaves ungüentos|strong="H8081" , ( ungüento|strong="H8081" derramado|strong="H7324" es tu nombre|strong="H8034" ,) por|strong="H5921" eso|strong="H3651" las|strong="H5921" vírge­nes te|strong="H5921" aman.',NULL),
(@vid,@bid,1,4,'Llévame|strong="H4900" en pos de ti, correre|strong="H7323" ­mos. Metióme el rey|strong="H4428" en sus cámaras: nos gozaremos|strong="H1523" y ale­graremos en ti; acordarémonos|strong="H2142" de tus amores más que del vino|strong="H3196" : los rectos te aman.',NULL),
(@vid,@bid,1,5,'Morena|strong="H7838" soy, oh hijas|strong="H1323" de|strong="H3407" Jerusalem|strong="H3389" , mas codiciable; como las cabañas de|strong="H3407" Cedar|strong="H6938" , como las tiendas de|strong="H3407" Salomón|strong="H8010" .',NULL),
(@vid,@bid,1,6,'No|strong="H3808" miréis|strong="H7200" en que|strong="H3808" soy morena, porque|strong="H3808" el|strong="H1121" sol|strong="H8121" me miró|strong="H7200" . Los|strong="H1121" hijos|strong="H1121" de|strong="H1121" mi madre se|strong="H3808" airaron contra mí, hiciéronme|strong="H7760" guarda|strong="H5201" de|strong="H1121" viñas|strong="H3754" ; Y|strong="H3068" mi viña|strong="H3754" , que|strong="H3808" era|strong="H1121" mía, no|strong="H3808" guar­ dé|strong="H1121" .',NULL),
(@vid,@bid,1,7,'Hazme saber|strong="H5046" , o|strong="H3068" tú a|strong="H3068" quien|strong="H4100" ama mi|strong="H5921" alma|strong="H5315" , dónde|strong="H5921" repastas|strong="H7462" , dónde|strong="H5921" haces tener|strong="H1961" majada|strong="H7257" al|strong="H5921" medio día: Porque|strong="H5921" , ¿ por|strong="H5921" qué|strong="H4100" había|strong="H1961" yo|strong="H5315" de|strong="H5921" estar como|strong="H4100" vagueando tras los|strong="H5921" rebaños|strong="H5739" de|strong="H5921" tus compañeros?',NULL),
(@vid,@bid,1,8,'Si|strong="H3808" tú no|strong="H3808" lo|strong="H3808" sabes|strong="H3045" , oh hermosa|strong="H3303" entre|strong="H5921" las|strong="H5921" mujeres, sal|strong="H3318" , yéndote por|strong="H5921" las|strong="H5921" huellas del|strong="H5921" rebaño|strong="H6629" , y|strong="H5921" apa­cienta tus cabritas|strong="H1429" junto|strong="H5921" a|strong="H3068" las|strong="H5921" cabañas de|strong="H5921" los|strong="H5921" pastores|strong="H7462" .',NULL),
(@vid,@bid,1,9,'A|strong="H3068" yegua de los carros|strong="H7393" de Faraón|strong="H6547" te he comparado, amada mía.',NULL),
(@vid,@bid,1,10,'Hermosas|strong="H4998" son tus mejillas entre los pendientes, tu cuello|strong="H6677" entre los collares.',NULL),
(@vid,@bid,1,11,'Zarcillos|strong="H8447" de|strong="H5973" oro|strong="H2091" te|strong="H5973" haremos|strong="H6213" , con|strong="H5973" clavos de|strong="H5973" plata|strong="H3701" .',NULL),
(@vid,@bid,1,12,'Mientras|strong="H5704" que|strong="H5704" el rey|strong="H4428" estaba en|strong="H5704" su reclinatorio, mi nardo|strong="H5373" dio|strong="H5414" su olor|strong="H7381" .',NULL),
(@vid,@bid,1,13,'Mi amado|strong="H1730" es para mí un manojito de mirra|strong="H4753" , que reposa|strong="H3885" entre mis pechos|strong="H7699" .',NULL),
(@vid,@bid,1,14,'Racimo de cofer en las viñas|strong="H3754" de Engadi es para mí mi amado|strong="H1730" .',NULL),
(@vid,@bid,1,15,'He aquí|strong="H2005" que tú eres hermosa|strong="H3303" , amada mía|strong="H3123" ; He aquí|strong="H2005" que eres bella: tus ojos|strong="H5869" de|strong="H5869" paloma|strong="H3123" .',NULL),
(@vid,@bid,1,16,'He aquí|strong="H2005" que tú eres hermoso|strong="H3303" , amado|strong="H1730" mío, y suave|strong="H5273" : nuestro lecho también florido.',NULL),
(@vid,@bid,1,17,'Las vigas de nuestra casa|strong="H1004" son de cedro, y de ciprés los arteso­nados.',NULL),
