(@vid,@bid,2,3,'Como|strong="H3651" el|strong="H1121" manzano entre los|strong="H3427" árboles|strong="H6086" silvestres|strong="H3293" , así|strong="H3651" es mi amado|strong="H1730" entre los|strong="H3427" mancebos: bajo la sombra|strong="H6738" del deseado me senté, y su fruto|strong="H6529" fue dulce|strong="H4966" en mi pala­dar.',NULL),
(@vid,@bid,2,4,'Llevóme a|strong="H3068" la|strong="H5921" cámara del|strong="H5921" vino|strong="H3196" , y|strong="H5921" su bandera sobre|strong="H5921" mí|strong="H5921" fue amor.',NULL),
(@vid,@bid,2,5,'Sustentadme|strong="H5564" con|strong="H3588" frascos, corroboradme|strong="H7502" con|strong="H3588" manzanas; porque|strong="H3588" estoy enferma de|strong="H3588" amor.',NULL),
(@vid,@bid,2,6,'Su izquierda|strong="H8040" esté debajo|strong="H8478" de|strong="H8478" mi cabeza|strong="H7218" , y su derecha|strong="H3225" me abrace.',NULL),
(@vid,@bid,2,7,'Yo os|strong="H5704" conjuro|strong="H7650" , oh hijas|strong="H1323" de|strong="H5704" Jerusalem|strong="H3389" , por|strong="H5704" las gamas y|strong="H5704" por|strong="H5704" las ciervas del campo|strong="H7704" , que|strong="H5704" no despertéis|strong="H5782" ni|strong="H5704" hagáis velar al|strong="H5704" amor, hasta|strong="H5704" que|strong="H5704" quiera|strong="H2654" .',NULL),
(@vid,@bid,2,8,'¡ La|strong="H5921" voz|strong="H6963" de|strong="H5921" mi|strong="H5921" amado|strong="H1730" ! He aquí|strong="H2009" él|strong="H5921" viene saltando|strong="H1801" sobre|strong="H5921" los|strong="H5921" montes|strong="H2022" , brincando|strong="H7092" sobre|strong="H5921" los|strong="H5921" collados|strong="H1389" .',NULL),
(@vid,@bid,2,9,'Mi|strong="H2009" amado|strong="H1730" es|strong="H2088" semejante al|strong="H4480" gamo, o|strong="H3068" al|strong="H4480" cabrito de|strong="H4480" los ciervos. Helo|strong="H2009" aquí|strong="H2009" , está|strong="H2088" tras nuestra pared|strong="H3796" , mirando|strong="H7688" por|strong="H4480" las ventanas|strong="H2474" , mostrándose por|strong="H4480" las rejas.',NULL),
(@vid,@bid,2,10,'Mi|strong="H6030" amado|strong="H1730" habló|strong="H6030" , y me dijo: Levántate|strong="H6965" , oh amada mía, her­mosa mía, y vente.',NULL),
(@vid,@bid,2,11,'Porque|strong="H3588" he aquí|strong="H2009" ha pasado|strong="H5674" el|strong="H3588" invierno, hase mudado, la|strong="H3588" lluvia|strong="H1653" se fue|strong="H1980" ;',NULL),
(@vid,@bid,2,12,'Hanse mostrado las flores en la tierra, el tiempo|strong="H6256" de|strong="H6256" la canción es venido, y en nuestro país se ha oído|strong="H8085" la voz|strong="H6963" de|strong="H6256" la tórtola;',NULL),
(@vid,@bid,2,13,'La higuera ha echado sus higos|strong="H8384" verdes, y las vides|strong="H1612" en|strong="H3212" cierne die­ron olor|strong="H7381" : levántate|strong="H6965" , oh amada mía, hermosa|strong="H3303" mía, y vente.',NULL),
(@vid,@bid,2,14,'Paloma|strong="H3123" mía|strong="H3123" , que|strong="H3588" estás en|strong="H3588" los|strong="H3588" agujeros de|strong="H3588" la|strong="H3588" peña|strong="H5553" , en|strong="H3588" lo escon­dido de|strong="H3588" escarpados parajes, muéstrame|strong="H7200" tu rostro|strong="H4758" , hazme oír|strong="H8085" tu voz|strong="H6963" ; Porque|strong="H3588" dulce|strong="H6156" es|strong="H3588" la|strong="H3588" voz|strong="H6963" tuya, y|strong="H3588" hermoso tu aspecto|strong="H4758" .',NULL),
(@vid,@bid,2,15,'Cazadnos las zorras|strong="H7776" , las zo­rras pequeñas|strong="H6996" , que echan a|strong="H3068" perder las viñas|strong="H3754" ; pues que nuestras viñas|strong="H3754" están en cierne.',NULL),
(@vid,@bid,2,16,'Mi amado|strong="H1730" es mío, y yo suya; él apacienta|strong="H7462" entre lirios|strong="H7799" .',NULL),
(@vid,@bid,2,17,'Hasta|strong="H5704" que|strong="H5921" apunte el|strong="H5921" día|strong="H3117" , y|strong="H5921" huyan las|strong="H5921" sombras, tórnate, amado|strong="H1730" mío|strong="H5921" ; sé|strong="H5921" semejante al|strong="H5921" gamo, o|strong="H3068" al|strong="H5921" cabrito de|strong="H5921" los|strong="H5921" ciervos, sobre|strong="H5921" los|strong="H5921" montes|strong="H2022" de|strong="H5921" Beter.',NULL),
(@vid,@bid,3,1,'POR|strong="H5921" las|strong="H5921" noches|strong="H3915" busqué|strong="H1245" en|strong="H5921" mi|strong="H5921" lecho al|strong="H5921" que|strong="H3808" ama mi|strong="H5921" alma|strong="H5315" : busquélo|strong="H1245" , y|strong="H5921" no|strong="H3808" lo|strong="H5921" hallé|strong="H4672" .',NULL),
(@vid,@bid,3,2,'Levantaréme|strong="H6965" ahora|strong="H4994" , y rodearé por la ciudad|strong="H5892" ; por las calles|strong="H7339" y por las plazas|strong="H7339" buscaré|strong="H1245" al que|strong="H3808" ama mi|strong="H4994" alma|strong="H5315" : busquélo|strong="H1245" , y no|strong="H3808" lo|strong="H3808" hallé|strong="H4672" .',NULL),
