(@vid,@bid,3,4,'Pasando|strong="H5674" de|strong="H5704" ellos|strong="H1992" un poco|strong="H4592" , hallé|strong="H4672" luego|strong="H5674" al|strong="H5704" que|strong="H3808" mi|strong="H5315" alma|strong="H5315" ama: trabé de|strong="H5704" él|strong="H5674" , y|strong="H5704" no|strong="H3808" lo|strong="H3808" dejé, hasta|strong="H5704" que|strong="H3808" lo|strong="H3808" metí en|strong="H5704" casa|strong="H1004" de|strong="H5704" mi|strong="H5315" madre, y|strong="H5704" en|strong="H5704" la cámara|strong="H2315" de|strong="H5704" la que|strong="H3808" me engendró.',NULL),
(@vid,@bid,3,5,'Yo os|strong="H5704" conjuro|strong="H7650" , oh hijas|strong="H1323" de|strong="H5704" Jerusalem|strong="H3389" , por|strong="H5704" las gamas y|strong="H5704" por|strong="H5704" las ciervas del campo|strong="H7704" , que|strong="H5704" no despertéis|strong="H5782" ni|strong="H5704" hagáis velar al|strong="H5704" amor, hasta|strong="H5704" que|strong="H5704" quiera|strong="H2654" .',NULL),
