(@vid,@bid,3,7,'He aquí|strong="H2009" es la litera de Salomón|strong="H8010" : sesenta|strong="H8346" valientes|strong="H1368" la rodean|strong="H5439" , de los fuertes|strong="H1368" de Israel|strong="H3478" .',NULL),
(@vid,@bid,3,8,'Todos|strong="H3605" ellos|strong="H5921" tienen espadas|strong="H2719" , diestros|strong="H3925" en|strong="H5921" la|strong="H5921" guerra|strong="H4421" ; cada|strong="H3605" uno su espada|strong="H2719" sobre|strong="H5921" su muslo|strong="H3409" , por|strong="H5921" los|strong="H5921" temores de|strong="H5921" la|strong="H5921" noche|strong="H3915" .',NULL),
(@vid,@bid,3,9,'El|strong="H6213" rey|strong="H4428" Salomón|strong="H8010" se hizo|strong="H6213" una carroza de madera|strong="H6086" del Líbano|strong="H3844" .',NULL),
