(@vid,@bid,3,11,'Salid|strong="H3318" , oh hijas|strong="H1323" de Sión|strong="H6726" , y ved|strong="H7200" al|strong="H4428" rey|strong="H4428" Salomón|strong="H8010" con la corona|strong="H5850" con que|strong="H3117" le coronó su madre el día|strong="H3117" de su desposorio, y el día|strong="H3117" del gozo|strong="H8057" de su corazón|strong="H3820" .',NULL),
(@vid,@bid,4,1,'HE aquí|strong="H2005" que|strong="H1157" tú eres hermosa|strong="H3303" ; amada mía|strong="H3123" , he aquí|strong="H2005" que|strong="H1157" tú eres hermosa|strong="H3303" ; tus ojos|strong="H5869" entre tus guedejas como de|strong="H5869" paloma|strong="H3123" ; tus cabellos como manada|strong="H5739" de|strong="H5869" cabras|strong="H5795" , que|strong="H1157" se muestran desde|strong="H1157" el monte|strong="H2022" de|strong="H5869" Galaad|strong="H1568" .',NULL),
