(@vid,@bid,4,4,'Tu cuello|strong="H6677" , como|strong="H5921" la|strong="H5921" torre|strong="H4026" de|strong="H5921" David|strong="H1732" , edificada|strong="H1129" para|strong="H5921" muestra; mil escudos|strong="H4043" están colgados|strong="H8518" de|strong="H5921" ella|strong="H5921" , todos|strong="H3605" escudos|strong="H4043" de|strong="H5921" valientes|strong="H1368" .',NULL),
(@vid,@bid,4,5,'Tus dos|strong="H8147" pechos|strong="H7699" , como gemelos de gacela, que apacienta|strong="H7462" entre lirios|strong="H7799" .',NULL),
(@vid,@bid,4,6,'Hasta|strong="H5704" que|strong="H5704" apunte el día|strong="H3117" y|strong="H5704" huyan las sombras, iréme|strong="H3212" al|strong="H5704" monte|strong="H2022" de|strong="H5704" la mirra|strong="H4753" , y|strong="H5704" al|strong="H5704" collado|strong="H1389" del incienso|strong="H3828" .',NULL),
(@vid,@bid,4,7,'Toda|strong="H3605" tú eres hermosa|strong="H3303" , amada mía, y en ti no hay mancha|strong="H3971" .',NULL),
(@vid,@bid,4,8,'Conmigo del Líbano|strong="H3844" , oh espo­sa, conmigo ven del Líbano|strong="H3844" : mira desde la cumbre|strong="H7218" de Amana, desde la cumbre|strong="H7218" de Senir|strong="H8149" y de Hermón|strong="H2768" , desde las guaridas de los leones, desde los montes de los leopardos.',NULL),
(@vid,@bid,4,9,'Prendiste mi corazón, herma­na, esposa|strong="H3618" mía ; has preso mi corazón con uno de|strong="H5869" tus ojos|strong="H5869" , con una gargantilla|strong="H6060" de|strong="H5869" tu cuello|strong="H6677" .',NULL),
