(@vid,@bid,4,11,'Como panal|strong="H5317" de|strong="H8478" miel|strong="H1706" destilan tus labios|strong="H8193" , oh esposa|strong="H3618" ; miel|strong="H1706" y|strong="H5317" leche|strong="H2461" hay debajo|strong="H8478" de|strong="H8478" tu lengua|strong="H3956" ; y|strong="H5317" el olor|strong="H7381" de|strong="H8478" tus vestiduras como|strong="H8478" el olor|strong="H7381" del Líbano|strong="H3844" .',NULL),
(@vid,@bid,4,12,'Huerto|strong="H1588" cerrado|strong="H5274" eres , mi hermana, esposa|strong="H3618" mía ; fuente|strong="H4599" cerrada|strong="H5274" , fuente|strong="H4599" sellada|strong="H2856" .',NULL),
(@vid,@bid,4,13,'Tus renuevos paraíso|strong="H6508" de|strong="H5973" gra­nados, con|strong="H5973" frutos|strong="H6529" suaves|strong="H4022" , de|strong="H5973" cofer y nardos,',NULL),
