(@vid,@bid,4,15,'Fuente|strong="H4599" de|strong="H4480" huertos, pozo de|strong="H4480" aguas|strong="H4325" vivas|strong="H2416" , que|strong="H4480" corren del|strong="H4480" Líbano|strong="H3844" .',NULL),
(@vid,@bid,4,16,'Levántate|strong="H5782" , viento del norte|strong="H6828" , y ven, viento del sur: sopla mi huerto|strong="H1588" , des­préndanse sus aromas|strong="H1314" . Venga mi amado|strong="H1730" a|strong="H3068" su huerto|strong="H1588" , y coma de su dulce fruta|strong="H6529" .',NULL),
(@vid,@bid,5,1,'YO vine a|strong="H3068" mi huerto|strong="H1588" , oh|strong="H1588" hermana, esposa|strong="H3618" mía: cogido he mi mirra|strong="H4753" y mis aromas; he comido mi panal y mi miel|strong="H1706" , mi vino|strong="H3196" y mi leche|strong="H2461" he bebido|strong="H8354" . Comed, amigos|strong="H7453" ; bebed|strong="H8354" en|strong="H5973" abundancia, oh|strong="H1588" amados|strong="H1730" .',NULL),
(@vid,@bid,5,2,'Yo dormía|strong="H3462" , pero mi corazón|strong="H3820" velaba|strong="H5782" : la voz|strong="H6963" de mi amado|strong="H1730" que llamaba: Abreme|strong="H6605" , hermana mía|strong="H3123" , amada mía|strong="H3123" , paloma|strong="H3123" mía|strong="H3123" , perfec­ta mía|strong="H3123" ; porque mi cabeza|strong="H7218" está llena|strong="H4390" de rocío|strong="H2919" , mis cabellos|strong="H6977" de las gotas de la noche|strong="H3915" .',NULL),
(@vid,@bid,5,3,'Heme desnudado mi ropa; ¿ cómo|strong="H7272" la tengo de|strong="H3847" vestir? He lavado mis pies|strong="H7272" ; ¿ cómo|strong="H7272" los tengo de|strong="H3847" ensuciar?',NULL),
(@vid,@bid,5,4,'Mi|strong="H5921" amado|strong="H1730" metió|strong="H7971" su mano|strong="H3027" por|strong="H5921" el|strong="H5921" agujero|strong="H2356" , y|strong="H5921" mis entrañas|strong="H4578" se|strong="H4480" con|strong="H5921" ­movieron dentro|strong="H5921" de|strong="H4480" mí|strong="H5921" .',NULL),
(@vid,@bid,5,5,'Yo|strong="H5197" me|strong="H5921" levanté para|strong="H5921" abrir a|strong="H3068" mi|strong="H5921" amado|strong="H1730" , y|strong="H5921" mis manos|strong="H3027" gotearon|strong="H5197" mirra|strong="H4753" , y|strong="H5921" mis dedos mirra|strong="H4753" que|strong="H5921" corría sobre|strong="H5921" las|strong="H5921" aldabas del|strong="H5921" can­dado.',NULL),
(@vid,@bid,5,6,'Abrí|strong="H6605" yo|strong="H5315" a|strong="H3068" mi|strong="H6030" amado|strong="H1730" ; Mas|strong="H6030" mi|strong="H6030" amado|strong="H1730" se|strong="H3808" había|strong="H4672" ido, había|strong="H4672" ya pasado|strong="H5674" : y tras su hablar|strong="H1696" salió|strong="H3318" mi|strong="H6030" alma|strong="H5315" : busquélo|strong="H1245" , y no|strong="H3808" lo|strong="H3808" hallé|strong="H4672" ; lla­mélo, y no|strong="H3808" me respondió|strong="H6030" .',NULL),
(@vid,@bid,5,7,'Halláronme|strong="H4672" los|strong="H5921" guardas|strong="H8104" que|strong="H5921" rondan la|strong="H5921" ciudad|strong="H5892" : hiriéronme|strong="H5221" , llagáronme|strong="H6481" , quitáronme|strong="H5375" mi|strong="H5921" manto de|strong="H5921" encima|strong="H5921" los|strong="H5921" guardas|strong="H8104" de|strong="H5921" los|strong="H5921" muros|strong="H2346" .',NULL),
(@vid,@bid,5,8,'Yo os conjuro|strong="H7650" , oh|strong="H4100" hijas|strong="H1323" de Jerusalem|strong="H3389" , si hallareis|strong="H4672" a|strong="H3068" mi|strong="H3389" amado|strong="H1730" , que|strong="H4100" le hagáis saber|strong="H5046" cómo|strong="H4100" de amor estoy enferma.',NULL),
(@vid,@bid,5,9,'¿ Qué|strong="H4100" es tu amado|strong="H1730" más que|strong="H4100" otro amado|strong="H1730" , oh|strong="H4100" la más hermosa|strong="H3303" de todas las mujeres? ¿ Qué|strong="H4100" es tu amado|strong="H1730" más que|strong="H4100" otro amado|strong="H1730" , que|strong="H4100" así|strong="H3602" nos|strong="H4100" conjuras|strong="H7650" ?',NULL),
