(@vid,@bid,5,11,'Su cabeza|strong="H7218" , como oro|strong="H3800" finísimo|strong="H6337" ; sus cabellos|strong="H6977" crespos|strong="H8534" , negros|strong="H7838" como el cuervo|strong="H6158" .',NULL),
(@vid,@bid,5,12,'Sus ojos|strong="H5869" , como|strong="H5921" palomas junto|strong="H5921" a|strong="H3068" los|strong="H3427" arroyos de|strong="H5921" las|strong="H5921" aguas|strong="H4325" , que|strong="H5921" se|strong="H5921" lavan con|strong="H5921" leche|strong="H2461" , y|strong="H5921" a|strong="H3068" la|strong="H5921" perfección colocados|strong="H3427" .',NULL),
(@vid,@bid,5,13,'Sus mejillas, como una era de especias|strong="H1314" aromáticas, como fra­gantes flores|strong="H4026" : sus labios|strong="H8193" , como lirios|strong="H7799" que destilan mirra|strong="H4753" que tras­ciende.',NULL),
(@vid,@bid,5,14,'Sus manos|strong="H3027" , como anillos|strong="H1550" de oro|strong="H2091" engastados|strong="H4390" de berilo: su vientre, como claro|strong="H6247" marfil|strong="H8127" cubierto|strong="H5968" de zafiros.',NULL),
