(@vid,@bid,5,16,'Su paladar, dulcísimo|strong="H4477" : y todo|strong="H3605" él|strong="H3605" codiciable. Tal|strong="H2088" es|strong="H2088" mi|strong="H3389" amado|strong="H1730" , tal|strong="H2088" es|strong="H2088" mi|strong="H3389" amigo|strong="H7453" , oh hijas|strong="H1323" de Jerusalem|strong="H3389" .',NULL),
(@vid,@bid,6,1,'¿DÓNDE se ha ido tu amado|strong="H1730" , oh la más|strong="H1245" hermosa|strong="H3303" de|strong="H5973" todas las mujeres? ¿Adónde se apartó tu amado|strong="H1730" , y le|strong="H5973" buscaremos contigo|strong="H5973" ?',NULL),
(@vid,@bid,6,2,'Mi amado|strong="H1730" descendió|strong="H3381" a|strong="H3068" su huer­to, a|strong="H3068" las eras de los aromas|strong="H1314" , para apacentar en los huertos, y para coger los lirios|strong="H7799" .',NULL),
(@vid,@bid,6,3,'Yo soy de mi amado|strong="H1730" , y mi amado|strong="H1730" es mío: él apacienta|strong="H7462" entre los lirios|strong="H7799" .',NULL),
(@vid,@bid,6,4,'Hermosa|strong="H3303" eres tú, oh amada mía, como Tirsa; de desear, como Jerusalem|strong="H3389" ; imponente como un ejército en orden.',NULL),
(@vid,@bid,6,5,'Aparta|strong="H5437" tus ojos|strong="H5869" de|strong="H4480" delante|strong="H5048" de|strong="H4480" mí, porque ellos|strong="H1992" me|strong="H4480" vencieron. Tu cabello es como manada|strong="H5739" de|strong="H4480" cabras|strong="H5795" , que|strong="H4480" se|strong="H1992" muestran en|strong="H4480" Galaad|strong="H1568" .',NULL),
(@vid,@bid,6,6,'Tus dientes|strong="H8127" , como manada|strong="H5739" de|strong="H4480" ovejas|strong="H7353" que|strong="H4480" suben|strong="H5927" del|strong="H4480" lavadero|strong="H7367" , todas|strong="H3605" con|strong="H4480" crías mellizas, y estéril no hay entre|strong="H4480" ellas.',NULL),
