(@vid,@bid,6,8,'Sesenta|strong="H8346" son las|strong="H1992" reinas, y ochen­ta las|strong="H1992" concubinas|strong="H6370" , y las|strong="H1992" vírgenes sin cuento|strong="H4557" :',NULL),
(@vid,@bid,6,9,'Mas una es|strong="H1931" la|strong="H1931" paloma|strong="H3123" mía|strong="H3123" , la|strong="H1931" perfecta|strong="H8535" mía|strong="H3123" ; única es|strong="H1931" a|strong="H3068" su|strong="H1931" madre, escogida|strong="H1249" a|strong="H3068" la|strong="H1931" que|strong="H1931" la|strong="H1931" engendró|strong="H3205" . Viéronla|strong="H7200" las hijas|strong="H1323" , y llamáronla bienaventurada; las reinas y las concubinas|strong="H6370" , y la|strong="H1931" ala­baron.',NULL),
(@vid,@bid,6,10,'¿ Quién|strong="H4310" es|strong="H2063" ésta|strong="H2063" que|strong="H4310" se muestra como|strong="H3644" el|strong="H4310" alba, hermosa|strong="H3303" como|strong="H3644" la|strong="H2063" luna, esclarecida|strong="H1249" como|strong="H3644" el|strong="H4310" sol, imponente como|strong="H3644" un ejército en orden?',NULL),
(@vid,@bid,6,11,'Al huerto|strong="H1594" de los nogales des­cendí a|strong="H3068" ver|strong="H7200" los frutos del valle, y para ver|strong="H7200" si brotaban las vides|strong="H1612" , si florecían los granados.',NULL),
(@vid,@bid,6,12,'No|strong="H3808" lo|strong="H3808" supe|strong="H3045" : hame mi|strong="H5315" alma|strong="H5315" hecho|strong="H5315" como los carros|strong="H4818" de|strong="H5971" Aminadab.',NULL),
(@vid,@bid,6,13,'Tórnate, tórnate, oh sulamita; tórnate, tórnate, y te miraremos. ¿Qué veréis en la sulamita? Como la reunión de dos ejércitos.',NULL),
(@vid,@bid,7,1,'¡ CUÁN|strong="H4100" hermosos son tus pies en los calzados, oh|strong="H4100" hija de príncipe! Los contornos de tus muslos son como|strong="H4100" joyas, obra de mano de excelente maestro.',NULL),
(@vid,@bid,7,2,'Tu ombligo, como una|strong="H6471" taza redonda, que|strong="H4100" no|strong="H4100" le falta bebida. Tu vientre, como montón de trigo, cercado de lirios.',NULL),
(@vid,@bid,7,3,'Tus dos pechos, como gemelos de gacela.',NULL),
(@vid,@bid,7,4,'Tu cuello, como torre de marfil; tus ojos, como las pesqueras de Hesbón junto a|strong="H3068" la puerta de Batrabim; tu nariz, como la torre del Líbano, que mira hacia Damasco.',NULL),
(@vid,@bid,7,5,'Tu cabeza encima|strong="H5921" de|strong="H5921" ti|strong="H5921" , como|strong="H5921" el|strong="H5921" Carmelo; y|strong="H5921" el|strong="H5921" cabello de|strong="H5921" tu cabeza, como|strong="H5921" la|strong="H5921" púrpura del|strong="H5921" rey ligada en|strong="H5921" los|strong="H5921" corredores.',NULL),
(@vid,@bid,7,6,'¡ Qué|strong="H5921" hermosa eres, y|strong="H5921" cuán suave, oh amor deleitoso!',NULL),
