(@vid,@bid,7,9,'Y|strong="H3068" tu paladar como|strong="H1961" el buen vino|strong="H1961" , que|strong="H4994" se|strong="H1961" entra a|strong="H3068" mi|strong="H1961" amado suavemente, y hace hablar los|strong="H1961" labios de los|strong="H1961" viejos.',NULL),
(@vid,@bid,7,10,'Yo soy de mi amado|strong="H1730" , y su deseo es hacia mi.',NULL),
(@vid,@bid,7,11,'Ven, oh amado|strong="H1730" mío|strong="H5921" , salgamos al|strong="H5921" campo, moremos en|strong="H5921" las|strong="H5921" alde­as.',NULL),
(@vid,@bid,7,12,'Levantémonos de mañana a|strong="H3068" las viñas; veamos si brotan las vides, si se abre el|strong="H3885" cierne, si han florecido los granados; allí te daré mis amores.',NULL),
(@vid,@bid,7,13,'Las mandrágoras han dado|strong="H5414" olor, y a|strong="H3068" nuestras puertas hay toda suerte de|strong="H5414" dulces frutas, nue­vas y añejas, que para|strong="H5414" ti, oh amado|strong="H1730" mío, he guardado.',NULL),
(@vid,@bid,8,1,'¡ OH|strong="H4310" quién|strong="H4310" te me|strong="H4310" diese|strong="H5414" como|strong="H1571" hermano que|strong="H4310" mamó los pechos|strong="H7699" de|strong="H5414" mi madre; de modo que|strong="H4310" te halle|strong="H4672" yo fuera|strong="H2351" , y|strong="H1571" te bese, y|strong="H1571" no|strong="H3808" me|strong="H4310" menosprecien!',NULL),
(@vid,@bid,8,2,'Yo te llevaría, te metiera en casa|strong="H1004" de mi madre: tú me enseña­rías, y yo te hiciera beber|strong="H8248" vino|strong="H3196" adobado|strong="H7544" del mosto|strong="H6071" de mis grana­das.',NULL),
(@vid,@bid,8,3,'Su izquierda|strong="H8040" esté debajo|strong="H8478" de|strong="H8478" mi cabeza|strong="H7218" , y su derecha|strong="H3225" me abrace.',NULL),
