(@vid,@bid,8,5,'¿ Quién|strong="H4310" es|strong="H2063" ésta|strong="H2063" que|strong="H4480" sube|strong="H5927" del|strong="H4480" desierto|strong="H4057" , recostada|strong="H7514" sobre|strong="H5921" su amado|strong="H1730" ? Debajo|strong="H8478" de|strong="H4480" un manzano te|strong="H5921" desperté|strong="H5782" : allí|strong="H8033" tuvo tu madre dolores|strong="H2254" , allí|strong="H8033" tuvo dolores|strong="H2254" la|strong="H5921" que|strong="H4480" te|strong="H5921" parió|strong="H3205" .',NULL),
(@vid,@bid,8,6,'Ponme|strong="H7760" como|strong="H3588" un sello sobre|strong="H5921" tu corazón|strong="H3820" , como|strong="H3588" una marca sobre|strong="H5921" tu brazo|strong="H2220" : porque|strong="H3588" fuerte|strong="H5794" es|strong="H3588" como|strong="H3588" la|strong="H5921" muerte|strong="H4194" el|strong="H5921" amor; duro|strong="H7186" como|strong="H3588" el|strong="H5921" sepulcro|strong="H7585" el|strong="H5921" celo|strong="H7068" : sus brasas|strong="H7565" , bra­sas de|strong="H5921" fuego, fuerte|strong="H5794" llama.',NULL),
(@vid,@bid,8,7,'Las muchas|strong="H7227" aguas|strong="H4325" no|strong="H3808" pueden|strong="H3201" apagar el|strong="H3605" amor, ni|strong="H3808" lo|strong="H3808" ahogan los|strong="H3605" diluvios. Si|strong="H3808" diese|strong="H5414" un hombre toda|strong="H3605" la|strong="H3605" sustancia de|strong="H5414" su casa|strong="H1004" por|strong="H5414" este amor, de|strong="H5414" cierto|strong="H3808" sería menospreciado.',NULL),
(@vid,@bid,8,8,'Tenemos una pequeña|strong="H6996" herma­na, que|strong="H4100" no|strong="H6213" tiene pechos|strong="H7699" : ¿ Qué|strong="H4100" haremos|strong="H6213" a|strong="H3068" nuestra hermana cuando|strong="H3117" de ella se|strong="H4100" hablare|strong="H1696" ?',NULL),
(@vid,@bid,8,9,'Si|strong="H1931" ella|strong="H1931" es|strong="H1931" muro|strong="H2346" , edificaremos|strong="H1129" sobre|strong="H5921" él|strong="H1931" un palacio de|strong="H5921" plata|strong="H3701" : y|strong="H5921" si|strong="H1931" fuere puerta|strong="H1817" , la|strong="H1931" guarneceremos|strong="H6696" con|strong="H5921" tablas|strong="H3871" de|strong="H5921" cedro.',NULL),
(@vid,@bid,8,10,'Yo soy|strong="H1961" muro|strong="H2346" , y mis pechos|strong="H7699" como|strong="H1961" torres|strong="H4026" , desde que|strong="H1961" fui|strong="H1961" en sus ojos|strong="H5869" como|strong="H1961" la que|strong="H1961" halla|strong="H4672" paz|strong="H7965" .',NULL),
(@vid,@bid,8,11,'Salomón|strong="H8010" tuvo|strong="H1961" una viña|strong="H3754" en Baal-hamón, la cual entregó|strong="H5414" a|strong="H3068" guardas, cada uno de|strong="H5414" los|strong="H1961" cuales debía traer mil monedas de|strong="H5414" plata|strong="H3701" por|strong="H5414" su fruto|strong="H6529" .',NULL),
(@vid,@bid,8,12,'Mi viña|strong="H3754" , que es mía, está delante|strong="H6440" de|strong="H6440" mí: las mil|strong="H3967" serán tuyas, oh Salomón|strong="H8010" , y doscientas|strong="H3967" , de|strong="H6440" los que guardan su fruto|strong="H6529" .',NULL),
(@vid,@bid,8,13,'Oh|strong="H1588" tú la que moras|strong="H3427" en los|strong="H3427" huertos, los|strong="H3427" compañeros escu­chan tu voz|strong="H6963" : házmela oír|strong="H8085" .',NULL),
(@vid,@bid,8,14,'Huye, amado|strong="H1730" mío|strong="H5921" ; y|strong="H5921" sé|strong="H5921" seme­jante al|strong="H5921" gamo, o|strong="H3068" al|strong="H5921" cervatillo, sobre|strong="H5921" las|strong="H5921" montañas de|strong="H5921" los|strong="H5921" aro­ mas|strong="H5921" .',NULL);
INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'VISIÓN|strong="H2377" de|strong="H5921" Isaías|strong="H3470" hijo|strong="H1121" de|strong="H5921" Amoz, la|strong="H5921" cual vio|strong="H2372" sobre|strong="H5921" Judá|strong="H3063" y|strong="H5921" Jerusalem|strong="H3389" , en|strong="H5921" días|strong="H3117" de|strong="H5921" Uzías, Jotam, Acaz y|strong="H5921" Ezequías, reyes|strong="H4428" de|strong="H5921" Judá|strong="H3063" .',NULL),
(@vid,@bid,1,2,'Oíd|strong="H8085" , oh|strong="H1121" cielos|strong="H8064" , y|strong="H3588" escucha|strong="H8085" tú, tierra; porque|strong="H3588" habla|strong="H1696" el|strong="H3588" SEÑOR|strong="H3068" : Crié|strong="H1431" hijos|strong="H1121" , y|strong="H3588" engrandecílos, y|strong="H3588" ellos|strong="H1992" se|strong="H1992" rebelaron contra mí|strong="H1431" .',NULL),
(@vid,@bid,1,3,'El buey|strong="H7794" conoce|strong="H3045" a|strong="H3068" su dueño|strong="H1167" , y|strong="H7794" el asno|strong="H2543" el pesebre de|strong="H5971" su señor: Israel|strong="H3478" no|strong="H3808" conoce|strong="H3045" , mi pueblo|strong="H5971" no|strong="H3808" tiene|strong="H7069" entendimiento.',NULL),
(@vid,@bid,1,4,'¡ Oh|strong="H1945" nación|strong="H1471" pecadora|strong="H2398" , pueblo|strong="H5971" cargado|strong="H3515" de|strong="H1121" maldad|strong="H5771" , generación|strong="H2233" de|strong="H1121" malignos|strong="H7489" , hijos|strong="H1121" depravados|strong="H7843" ! Dejaron|strong="H5800" al SEÑOR|strong="H3068" , provocaron a|strong="H3068" ira al Santo|strong="H6918" de|strong="H1121" Israel|strong="H3478" , torná­ronse atrás.',NULL),
(@vid,@bid,1,5,'¿ Para|strong="H5921" qué|strong="H4100" habéis de|strong="H5921" ser casti­gados aún|strong="H5750" ? todavía|strong="H5750" os|strong="H5921" rebelaréis. Toda|strong="H3605" cabeza|strong="H7218" está|strong="H5921" enferma, y|strong="H5921" todo|strong="H3605" corazón|strong="H3824" doliente|strong="H1742" .',NULL),
(@vid,@bid,1,6,'Desde|strong="H5704" la planta del pie|strong="H7272" hasta|strong="H5704" la cabeza|strong="H7218" no|strong="H3808" hay en|strong="H5704" él cosa ilesa, sino herida|strong="H6482" , hinchazón|strong="H2250" y|strong="H5704" podrida llaga|strong="H2250" : no|strong="H3808" están curadas, ni|strong="H3808" venda­das, ni|strong="H3808" suavizadas|strong="H7401" con|strong="H5704" aceite|strong="H8081" .',NULL),
