INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,49,19,'Porque|strong="H3588" tus asolamientos|strong="H8074" , y|strong="H3588" tus ruinas, y|strong="H3588" tu tierra desierta|strong="H2723" , ahora|strong="H6258" será angosta por|strong="H3588" la|strong="H3588" multitud de|strong="H3588" los|strong="H3427" moradores|strong="H3427" ; y|strong="H3588" tus destruidores serán apartados lejos|strong="H7368" .',NULL),
