(@vid,@bid,66,10,'Alegraos|strong="H8055" con|strong="H5921" Jerusalem|strong="H3389" , y|strong="H5921" gozaos con|strong="H5921" ella|strong="H3605" , todos|strong="H3605" los|strong="H5921" que|strong="H5921" la|strong="H5921" amáis: llenaos|strong="H7797" con|strong="H5921" ella|strong="H3605" de|strong="H5921" gozo|strong="H4885" , todos|strong="H3605" los|strong="H5921" que|strong="H5921" os|strong="H5921" enlutáis por|strong="H5921" ella|strong="H3605" :',NULL),
