(@vid,@bid,40,4,'Y|strong="H3068" ahora|strong="H6258" yo|strong="H4480" te|strong="H5869" he soltado hoy|strong="H3117" de|strong="H4480" las|strong="H5921" esposas que|strong="H4480" tenías en|strong="H5921" tus manos|strong="H3027" . Si|strong="H6440" te|strong="H5869" está|strong="H5921" bien|strong="H2896" venir|strong="H3212" con|strong="H5921" ­migo a|strong="H3068" Babilonia, ven|strong="H3212" , y|strong="H5921" yo|strong="H4480" miraré|strong="H7200" por|strong="H5921" ti|strong="H5921" ; mas|strong="H4480" si|strong="H6440" no|strong="H2308" te|strong="H5869" está|strong="H5921" bien|strong="H2896" venir|strong="H3212" conmigo a|strong="H3068" Babilonia, déjalo|strong="H2308" : mira|strong="H7200" , toda|strong="H3605" la|strong="H5921" tierra está|strong="H5921" delante|strong="H6440" de|strong="H4480" ti|strong="H5921" ; ve|strong="H3212" a|strong="H3068" donde|strong="H8033" mejor|strong="H2896" y|strong="H5921" más|strong="H4480" cómodo te|strong="H5869" pareciere|strong="H5869" ir|strong="H3212" .',NULL),
(@vid,@bid,40,5,'Y|strong="H3068" aun|strong="H5750" no|strong="H3808" se|strong="H3808" había él|strong="H3605" vuelto|strong="H7725" , cuando le dijo : Vuélvete|strong="H7725" a|strong="H3068" Gedalías|strong="H1436" hijo|strong="H1121" de|strong="H5750" Ahicam, hijo|strong="H1121" de|strong="H5750" Safán, al|strong="H4428" cual el|strong="H3605" rey|strong="H4428" de|strong="H5750" Babilonia ha|strong="H3808" puesto|strong="H5414" sobre todas|strong="H3605" las ciudades|strong="H5892" de|strong="H5750" Judá|strong="H3063" , y vive con él|strong="H3605" en|strong="H8432" medio|strong="H8432" del pueblo|strong="H5971" : o|strong="H3068" ve|strong="H3212" a|strong="H3068" donde te|strong="H5869" pareciere|strong="H5869" más|strong="H5750" cómodo de|strong="H5750" ir|strong="H3212" . Y|strong="H3068" dióle|strong="H5414" el|strong="H3605" capitán|strong="H7227" de|strong="H5750" la|strong="H3605" guardia presentes y dones, y des|strong="H5414" ­pidióle.',NULL);
INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
