(@vid,@bid,40,7,'Y|strong="H3068" como|strong="H3588" oyeron|strong="H8085" todos|strong="H3605" los|strong="H1992" prínci­pes del ejército|strong="H2428" que|strong="H3588" estaba por|strong="H3588" el|strong="H3588" campo|strong="H7704" , ellos|strong="H1992" y|strong="H3588" sus|strong="H1992" hombres|strong="H1121" , que|strong="H3588" el|strong="H3588" rey|strong="H4428" de|strong="H3588" Babilonia había|strong="H3588" puesto|strong="H3588" a|strong="H3068" Gedalías|strong="H1436" hijo|strong="H1121" de|strong="H3588" Ahicam sobre la|strong="H3588" tierra, y|strong="H3588" que|strong="H3588" le había|strong="H3588" encomenda­do los|strong="H1992" hombres|strong="H1121" , y|strong="H3588" las|strong="H1992" mujeres, y|strong="H3588" los|strong="H1992" niños|strong="H2945" , y|strong="H3588" los|strong="H1992" pobres de|strong="H3588" la|strong="H3588" tierra, que|strong="H3588" no|strong="H3808" fueron llevados cautivos|strong="H1540" a|strong="H3068" Babilonia;',NULL),
(@vid,@bid,40,8,'Vinieron luego a|strong="H3068" Gedalías|strong="H1436" en Mizpa, es a|strong="H3068" saber, Ismael|strong="H3458" hijo|strong="H1121" de|strong="H1121" Netanías, y Johanán|strong="H3110" y Jonatán hijos|strong="H1121" de|strong="H1121" Carea|strong="H7143" , y Seraías|strong="H8304" hijo|strong="H1121" de|strong="H1121" Tanhumet, y los|strong="H1992" hijos|strong="H1121" de|strong="H1121" Efi netofatita|strong="H5200" , y Jezanías hijo|strong="H1121" de|strong="H1121" Maacati, ellos|strong="H1992" y sus|strong="H1992" hombres|strong="H1121" .',NULL),
