(@vid,@bid,20,42,'Y|strong="H3068" sabréis|strong="H3045" que|strong="H3588" yo|strong="H3588" soy el|strong="H3588" SEÑOR|strong="H3068" , cuando|strong="H3588" os hubiere meti­do en|strong="H3588" la|strong="H3588" tierra de|strong="H3588" Israel|strong="H3478" , en|strong="H3588" la|strong="H3588" tierra por|strong="H3588" la|strong="H3588" cual|strong="H3588" alcé|strong="H5375" mi|strong="H5375" mano|strong="H3027" que|strong="H3588" la|strong="H3588" daría|strong="H5414" a|strong="H3068" vuestros padres.',NULL),
(@vid,@bid,20,43,'Y|strong="H3068" allí|strong="H8033" os acordaréis de|strong="H6440" vuestros caminos|strong="H1870" , y de|strong="H6440" todos|strong="H3605" vuestros hechos|strong="H6213" en que|strong="H3605" os contaminasteis; y seréis confusos en vuestra misma presencia|strong="H6440" por|strong="H1870" todos|strong="H3605" vues­tros pecados que|strong="H3605" cometisteis|strong="H6213" .',NULL),
