(@vid,@bid,21,4,'Y|strong="H3068" por|strong="H3588" cuanto|strong="H3588" he de|strong="H3588" talar de|strong="H3588" ti al justo y|strong="H3588" al impío, por|strong="H3588" tanto, mi espada saldrá de|strong="H3588" su|strong="H3588" vaina contra toda|strong="H3605" carne|strong="H1320" , desde el|strong="H3588" sur hasta el|strong="H3588" norte:',NULL),
(@vid,@bid,21,5,'Y|strong="H3068" sabrá toda carne que|strong="H1931" yo el|strong="H1931" SEÑOR saqué mi espada de su|strong="H1931" vaina; no|strong="H3808" volverá más|strong="H3808" .',NULL),
(@vid,@bid,21,6,'Y|strong="H3068" tú, hijo del hombre, gime con quebrantamiento de|strong="H1697" lomos, y con amargura; gime delante de|strong="H1697" los|strong="H1961" ojos de|strong="H1697" ellos.',NULL),
