(@vid,@bid,21,10,'Para|strong="H3588" degollar víctimas está afilada, acicalada está para|strong="H3588" que|strong="H3588" relumbre. ¿Hemos de|strong="H3588" alegrar­nos? A|strong="H3068" la|strong="H3605" vara de|strong="H3588" mi hijo viene menospreciando todo|strong="H3605" árbol.',NULL),
(@vid,@bid,21,11,'Y|strong="H3068" dióla a|strong="H3068" acicalar para tenerla a|strong="H3068" mano: la espada está afilada, y acicalada está ella, para entregar­la en mano del matador.',NULL),
(@vid,@bid,21,12,'Clama y|strong="H3588" aúlla, oh|strong="H4100" hijo del|strong="H5921" hombre; porque|strong="H3588" ésta|strong="H1961" será sobre|strong="H5921" mi|strong="H5921" pueblo, será ella|strong="H5921" sobre|strong="H5921" todos|strong="H3605" los|strong="H5921" príncipes de|strong="H5921" Israel. Temores de|strong="H5921" espada serán|strong="H1961" a|strong="H3068" mi|strong="H5921" pueblo: por|strong="H5921" tanto|strong="H5921" , hiere el|strong="H5921" muslo;',NULL),
(@vid,@bid,21,13,'Porque está|strong="H1961" probado. ¿ Y|strong="H3068" qué|strong="H1697" , si|strong="H1961" la espada desprecia aun el cetro? El no|strong="H1961" será|strong="H1961" más , dice|strong="H1697" el Señor|strong="H3068" DIOS|strong="H3068" .',NULL),
(@vid,@bid,21,14,'Tú pues|strong="H1571" , hijo|strong="H1121" del hombre|strong="H1121" , pro­fetiza y|strong="H1571" bate una mano con|strong="H1571" otra, y|strong="H1571" dóblese la|strong="H1571" espada|strong="H2719" la|strong="H1571" tercera vez, la|strong="H1571" espada|strong="H2719" de|strong="H1121" muertos: ésta es|strong="H3541" espada|strong="H2719" de|strong="H1121" gran matanza que|strong="H1571" los|strong="H1121" penetrará,',NULL),
(@vid,@bid,21,15,'Para|strong="H4616" que|strong="H1121" el|strong="H3605" corazón desmaye, y los|strong="H1121" estragos se|strong="H1961" multipliquen: en todas|strong="H3605" las puertas de|strong="H1121" ellos|strong="H3605" he puesto espanto de|strong="H1121" espada. ¡Ah! dispuesta está|strong="H1961" para|strong="H4616" que|strong="H1121" relumbre, y aderezada para|strong="H4616" degollar|strong="H2874" .',NULL),
(@vid,@bid,21,16,'Ponte a|strong="H3068" una parte, ponte a|strong="H3068" la|strong="H1931" diestra, o|strong="H3068" ponte a|strong="H3068" la|strong="H1931" siniestra, hacia donde|strong="H1931" tu rostro se|strong="H1931" determi­nare.',NULL),
