INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,21,21,'Porque|strong="H6440" el rey de|strong="H6440" Babilonia se paró en|strong="H3259" una encrucijada, al prin­cipio de|strong="H6440" dos|strong="H6440" caminos, para tomar adivinación: acicaló saetas, con­sultó en|strong="H3259" ídolos, miró el hígado.',NULL),
(@vid,@bid,21,22,'La|strong="H1571" adivinación fue|strong="H1571" a|strong="H3068" su mano|strong="H3709" derecha, sobre Jerusalem, para poner capitanes, para abrir la|strong="H1571" boca a|strong="H3068" la|strong="H1571" matanza, para levantar la|strong="H1571" voz en|strong="H5221" grito, para poner inge­nios contra las puertas, para fun­dar baluarte, y|strong="H1571" edificar fuerte.',NULL),
(@vid,@bid,21,23,'Y|strong="H3068" seráles como|strong="H1961" adivinación mentirosa en sus ojos, por|strong="H1697" estar juramentados con juramento a|strong="H3068" ellos: mas él trae a|strong="H3068" la memoria la maldad, para|strong="H1961" prenderlos.',NULL),
(@vid,@bid,21,24,'Por|strong="H1870" tanto, así ha dicho el|strong="H1121" Señor DIOS: Por|strong="H1870" cuanto habéis hecho venir en|strong="H3318" memoria vuestras maldades, manifestando vuestras traiciones, y descubriendo vues­tros pecados en|strong="H3318" todas vuestras obras; por|strong="H1870" cuanto habéis venido en|strong="H3318" memoria, seréis tomados a|strong="H3068" mano|strong="H3027" .',NULL),
