(@vid,@bid,21,26,'Así|strong="H3588" ha dicho el|strong="H3588" Señor DIOS: Depón la|strong="H3588" diadema, quita la|strong="H3588" corona: ésta|strong="H5975" no|strong="H3588" será más|strong="H3588" ésta|strong="H5975" : al|strong="H4428" bajo alzaré, y|strong="H3588" al|strong="H4428" alto abatiré.',NULL),
(@vid,@bid,21,27,'Del|strong="H5921" revés, del|strong="H5921" revés, del|strong="H5921" revés la|strong="H5921" tornaré|strong="H7760" ; y|strong="H5921" no|strong="H1961" será|strong="H1961" ésta|strong="H1961" más|strong="H5921" , hasta|strong="H5921" que|strong="H5921" venga|strong="H1961" aquel cuyo es|strong="H1961" el|strong="H5921" derecho|strong="H3225" , y|strong="H5921" se la|strong="H5921" entregaré.',NULL),
(@vid,@bid,21,28,'Y|strong="H3068" tú, hijo del hombre, profeti­za, y di: Así|strong="H1931" ha dicho el|strong="H1931" Señor DIOS sobre|strong="H1961" los|strong="H1931" hijos de|strong="H5869" Amón, y su|strong="H1931" oprobio. Dirás pues|strong="H1931" : La|strong="H1931" espada, la|strong="H1931" espada está|strong="H1931" desenvai­nada para|strong="H1961" degollar; acicalada para|strong="H1961" consumir con resplandor.',NULL),
(@vid,@bid,21,29,'Te profetizan vanidad, adiví­nante mentira, para|strong="H3282" entregarte con los|strong="H3605" cuellos de los|strong="H3605" malos sen­tenciados a|strong="H3068" muerte, cuyo día vino en tiempo de la|strong="H3605" consuma­ción de la|strong="H3605" maldad|strong="H5771" .',NULL),
(@vid,@bid,21,30,'¿Tornaréla a|strong="H3068" su vaina? En el lugar donde fuiste creado, en la tierra de|strong="H6256" tu nacimiento, te tengo de|strong="H6256" juzgar.',NULL),
(@vid,@bid,21,31,'Y|strong="H3068" derramaré sobre ti mi ira: el fuego de mi enojo haré encender sobre ti, y|strong="H3541" te entregaré en|strong="H5493" mano de hombres brutales, artífices de destrucción.',NULL),
