(@vid,@bid,22,1,'Y|strong="H3068" VINO|strong="H1961" a|strong="H3068" mí|strong="H1961" la palabra|strong="H1697" del SEÑOR|strong="H3068" , diciendo:',NULL),
(@vid,@bid,22,2,'Y|strong="H3068" tú|strong="H8199" , hijo|strong="H1121" del hombre|strong="H1121" , ¿No juz­garás tú|strong="H8199" , no juzgarás|strong="H8199" tú|strong="H8199" a|strong="H3068" la|strong="H3605" ciu­dad derramadora de|strong="H1121" sangre|strong="H1818" , y le mostrarás todas|strong="H3605" sus abominacio­nes?',NULL),
(@vid,@bid,22,3,'Dirás, pues: Así|strong="H3541" ha|strong="H3541" dicho el|strong="H5921" Señor DIOS|strong="H3069" : ¡ Ciudad|strong="H5892" derrama|strong="H8210" ­dora de|strong="H5921" sangre|strong="H1818" en|strong="H5921" medio|strong="H8432" de|strong="H5921" sí|strong="H5921" , para|strong="H5921" que|strong="H5921" venga su hora|strong="H6256" , y|strong="H5921" que|strong="H5921" hizo|strong="H6213" ídolos|strong="H1544" contra|strong="H5921" sí|strong="H5921" misma para|strong="H5921" contaminarse!',NULL),
(@vid,@bid,22,4,'En|strong="H5921" tu|strong="H6213" sangre|strong="H1818" que|strong="H5921" derramaste|strong="H8210" has|strong="H5414" pecado, y|strong="H5921" te|strong="H5921" has|strong="H5414" contamina­do en|strong="H5921" tus ídolos|strong="H1544" que|strong="H5921" hiciste|strong="H6213" ; y|strong="H5921" has|strong="H5414" hecho|strong="H6213" acercar tus días|strong="H3117" , y|strong="H5921" has|strong="H5414" lle­gado a|strong="H3068" tus años|strong="H8141" : por|strong="H5921" tanto|strong="H3651" te|strong="H5921" he dado|strong="H5414" en|strong="H5921" oprobio|strong="H2781" a|strong="H3068" las|strong="H5921" gentes|strong="H1471" , y|strong="H5921" en|strong="H5921" escarnio a|strong="H3068" todas|strong="H3605" las|strong="H5921" tierras.',NULL),
(@vid,@bid,22,5,'Las que|strong="H4480" están cerca|strong="H7138" , y las que|strong="H4480" están lejos|strong="H7350" de|strong="H4480" ti|strong="H4480" , se|strong="H4480" reirán de|strong="H4480" ti|strong="H4480" , amancillada|strong="H2931" de|strong="H4480" fama|strong="H8034" , y de|strong="H4480" grande|strong="H7227" turbación|strong="H4103" .',NULL),
(@vid,@bid,22,6,'He aquí|strong="H2009" que|strong="H1961" los|strong="H1961" príncipes|strong="H5387" de|strong="H1818" Israel|strong="H3478" , cada uno según su poder, fueron|strong="H1961" en ti para|strong="H4616" derramar san­gre.',NULL),
(@vid,@bid,22,7,'Al padre y a|strong="H3068" la madre despre­ciaron en|strong="H8432" ti: al extranjero|strong="H1616" trataron|strong="H6213" con calumnia|strong="H6233" en|strong="H8432" medio|strong="H8432" de ti: al huérfano|strong="H3490" y a|strong="H3068" la viuda despojaron|strong="H3238" en|strong="H8432" ti.',NULL),
