(@vid,@bid,22,9,'Calumniadores hubo|strong="H1961" en|strong="H8432" ti para|strong="H4616" derramar sangre|strong="H1818" ; y sobre|strong="H1961" los|strong="H1961" montes|strong="H2022" comieron en|strong="H8432" ti: hicieron|strong="H6213" en|strong="H8432" medio|strong="H8432" de|strong="H1818" ti suciedades.',NULL),
