(@vid,@bid,1,1,'LA palabra|strong="H1697" del SEÑOR|strong="H3068" que|strong="H1697" vino|strong="H1961" a|strong="H3068" Oseas|strong="H1954" hijo|strong="H1121" de|strong="H1121" Beeri, en días|strong="H3117" de|strong="H1121" Ozías, Jahatán, Acaz, y Ezequías, reyes|strong="H4428" de|strong="H1121" Judá|strong="H3063" , y en días|strong="H3117" de|strong="H1121" Jeroboam|strong="H3379" hijo|strong="H1121" de|strong="H1121" Joas|strong="H3101" , rey|strong="H4428" de|strong="H1121" Israel|strong="H3478" .',NULL),
(@vid,@bid,1,2,'El|strong="H3588" principio de|strong="H3588" la|strong="H3588" palabra|strong="H1696" del SEÑOR|strong="H3068" con|strong="H3588" Oseas|strong="H1954" . Y|strong="H3068" dijo|strong="H1696" el|strong="H3588" SEÑOR|strong="H3068" a|strong="H3068" Oseas|strong="H1954" : Ve|strong="H3212" , tómate|strong="H3947" una esposa fornicaria|strong="H2183" , e|strong="H3068" hijos|strong="H3206" de|strong="H3588" forni­caciones: porque|strong="H3588" la|strong="H3588" tierra se dará a|strong="H3068" fornicar apartándose del SEÑOR|strong="H3068" .',NULL),
