(@vid,@bid,1,4,'Y|strong="H3068" díjole el|strong="H5921" SEÑOR|strong="H3068" : Ponle|strong="H7121" por|strong="H5921" nombre|strong="H8034" Jezreel|strong="H3157" ; porque|strong="H3588" de|strong="H5921" aquí a|strong="H3068" poco|strong="H4592" yo|strong="H3588" visitaré|strong="H6485" las|strong="H5921" sangres|strong="H1818" de|strong="H5921" Jezreel|strong="H3157" sobre|strong="H5921" la|strong="H5921" casa|strong="H1004" de|strong="H5921" Jehú|strong="H3058" , y|strong="H3588" haré cesar el|strong="H5921" reino de|strong="H5921" la|strong="H5921" casa|strong="H1004" de|strong="H5921" Israel|strong="H3478" .',NULL),
(@vid,@bid,1,5,'Y|strong="H3068" acaecerá que|strong="H1931" en aquel|strong="H1931" día|strong="H3117" quebraré|strong="H7665" yo el|strong="H1931" arco|strong="H7198" de Israel|strong="H3478" en el|strong="H1931" valle|strong="H6010" de Jezreel|strong="H3157" .',NULL),
(@vid,@bid,1,6,'Y|strong="H3068" concibió|strong="H2029" aún|strong="H5750" , y|strong="H3588" parió|strong="H3205" una hija|strong="H1323" . Y|strong="H3068" díjole Dios: Ponle|strong="H7121" por|strong="H3588" nombre|strong="H8034" Lo-ruhama|strong="H3808" : porque|strong="H3588" no|strong="H3808" más|strong="H5750" tendré misericordia|strong="H7355" de|strong="H3588" la|strong="H3588" casa|strong="H1004" de|strong="H3588" Israel|strong="H3478" , sino|strong="H3588" que|strong="H3588" los|strong="H3588" quita|strong="H5375" ­ré del todo.',NULL),
(@vid,@bid,1,7,'Mas|strong="H3808" de la casa|strong="H1004" de Judá|strong="H3063" tendré misericordia|strong="H7355" , y salvarélos por el SEÑOR|strong="H3068" su Dios|strong="H3068" : y no|strong="H3808" los salva|strong="H3467" ­ré por arco|strong="H7198" , ni|strong="H3808" por espada|strong="H2719" , ni|strong="H3808" por batalla|strong="H4421" , ni|strong="H3808" por caballos|strong="H5483" ni|strong="H3808" por caballeros|strong="H6571" .',NULL),
(@vid,@bid,1,8,'Y|strong="H3068" después de|strong="H1121" haber destetado a|strong="H3068" Lo-ruhama, concibió|strong="H2029" y parió|strong="H3205" un hijo|strong="H1121" .',NULL),
(@vid,@bid,1,9,'Y|strong="H3068" dijo Dios : Ponle|strong="H7121" por|strong="H3588" nombre|strong="H8034" Lo-ammi|strong="H3808" : porque|strong="H3588" vosotros no|strong="H3808" sois|strong="H1961" mi|strong="H1961" pueblo|strong="H5971" , ni|strong="H3808" yo|strong="H3588" seré|strong="H1961" vuestro Dios .',NULL),
(@vid,@bid,1,10,'Con todo será el número de los hijos de Israel como la arena del mar, que ni se puede medir ni contar. Y|strong="H3068" será, que donde se les ha dicho: Vosotros no sois mi pueblo, les será dicho: Sois hijos del Dios viviente.',NULL),
(@vid,@bid,1,11,'Y|strong="H3068" los hijos de Judá y de Israel serán congregados en uno, y levantarán para sí una cabeza, y subirán de la tierra: porque el día de Jezreel será grande.',NULL),
(@vid,@bid,2,1,'DECID a|strong="H3068" vuestros hermanos, Ammi|strong="H5971" , y a|strong="H3068" vuestras hermanas, Ruhama:',NULL),
(@vid,@bid,2,2,'Pleitead con|strong="H4480" vuestra madre, pleitead; porque|strong="H3588" ella|strong="H4480" no|strong="H3588" es|strong="H3588" mi esposa, ni yo|strong="H4480" su|strong="H3588" marido; quite pues|strong="H3588" sus fornicaciones de|strong="H4480" su|strong="H3588" ros­tro, y|strong="H3588" sus adulterios de|strong="H4480" entre|strong="H3588" sus pechos;',NULL),
(@vid,@bid,2,3,'No sea que|strong="H5971" yo la despoje des­nuda, y la haga tornar como el día en que|strong="H5971" nació, y la ponga como un desierto, y la deje como tierra seca, y la mate de|strong="H5971" sed.',NULL),
(@vid,@bid,2,4,'Ni|strong="H3808" tendré misericordia de|strong="H3588" sus|strong="H1931" hijos: porque|strong="H3588" son|strong="H3588" hijos de|strong="H3588" forni­caciones.',NULL),
(@vid,@bid,2,5,'Porque|strong="H6435" su madre fornicó; la que|strong="H6435" los engendró|strong="H3205" fue avergonza­ da|strong="H7760" ; porque|strong="H6435" dijo: Iré tras mis amantes, que|strong="H6435" me dan mi pan y mi agua, mi lana y mi lino, mi aceite y mi bebida.',NULL),
(@vid,@bid,2,6,'Por|strong="H3588" tanto, he aquí yo|strong="H3588" cerco tu camino con|strong="H3588" espinas, y|strong="H3588" la|strong="H3588" cercaré con|strong="H3588" seto, y|strong="H3588" no|strong="H3808" hallará sus|strong="H1992" cami­nos.',NULL),
(@vid,@bid,2,7,'Y|strong="H3068" seguirá sus amantes, y|strong="H3588" no|strong="H3588" los|strong="H3588" alcanzará; buscarálos, y|strong="H3588" no|strong="H3588" los|strong="H3588" hallará. Entonces|strong="H3588" dirá: Iré|strong="H3212" , y|strong="H3588" vol­véreme a|strong="H3068" mi primer marido; por|strong="H3588" ­ que|strong="H3588" mejor me|strong="H3588" iba|strong="H3212" entonces|strong="H3588" que|strong="H3588" ahora.',NULL),
(@vid,@bid,2,8,'Y|strong="H3068" ella no|strong="H3808" reconoció que|strong="H3808" yo le daba el trigo, y el vino|strong="H1870" , y el acei­te, y que|strong="H3808" les multipliqué la plata y el oro con que|strong="H3808" hicieron a|strong="H3068" Baal.',NULL),
(@vid,@bid,2,9,'Por|strong="H3588" tanto yo|strong="H3588" tornaré|strong="H7725" , y|strong="H3588" tomaré mi|strong="H1245" trigo a|strong="H3068" su|strong="H3588" tiempo, y|strong="H3588" mi|strong="H1245" vino|strong="H3212" a|strong="H3068" su|strong="H3588" sazón, y|strong="H3588" quitaré mi|strong="H1245" lana y|strong="H3588" mi|strong="H1245" lino que había dado para|strong="H3588" cubrir su|strong="H3588" desnudez.',NULL),
(@vid,@bid,2,10,'Y|strong="H3068" ahora descubriré yo|strong="H3588" su|strong="H1931" locu­ra delante|strong="H1931" de|strong="H3588" los|strong="H1931" ojos de|strong="H3588" sus|strong="H1931" aman­tes, y|strong="H3588" nadie|strong="H3808" la|strong="H1931" librará de|strong="H3588" mi mano|strong="H1931" .',NULL),
(@vid,@bid,2,11,'Y|strong="H3068" haré cesar todo su gozo, sus fiestas, sus nuevas lunas y sus sábados, y todas sus festividades.',NULL),
(@vid,@bid,2,12,'Y|strong="H3068" haré talar sus vides y sus higueras, de|strong="H5869" que|strong="H3808" ha|strong="H3808" dicho: Mi salario me son|strong="H3808" , que|strong="H3808" me han dado mis amantes. Y|strong="H3068" reducirélas a|strong="H3068" un matorral, y las comerán las bes­tias del campo.',NULL),
(@vid,@bid,2,13,'Y|strong="H3068" visitaré sobre ella|strong="H3605" los|strong="H3605" tiem­pos de los|strong="H3605" Baales, a|strong="H3068" los|strong="H3605" cuales incensaba, y adornábase de sus zarcillos y de sus joyeles, e|strong="H3068" íbase tras sus amantes olvidada de mí, dice el|strong="H3605" SEÑOR.',NULL),
(@vid,@bid,2,14,'Por|strong="H5414" tanto, he aquí, yo la induci­ré, y la llevaré al desierto, y hablaré a|strong="H3068" su|strong="H1992" corazón.',NULL),
(@vid,@bid,2,15,'Y|strong="H3068" daréle sus|strong="H1992" viñas desde|strong="H5921" allí, y|strong="H5921" el|strong="H5921" valle de|strong="H5921" Acor por|strong="H5921" puerta de|strong="H5921" esperanza; y|strong="H5921" allí cantará como|strong="H5921" en|strong="H5921" los|strong="H1992" tiempos|strong="H3117" de|strong="H5921" su|strong="H1992" juventud, y|strong="H5921" como|strong="H5921" en|strong="H5921" el|strong="H5921" día|strong="H3117" de|strong="H5921" su|strong="H1992" subida de|strong="H5921" la|strong="H5921" tierra de|strong="H5921" Egipto.',NULL),
(@vid,@bid,2,16,'Y|strong="H3068" será que|strong="H5921" en|strong="H5921" aquel tiempo, dice|strong="H1696" el|strong="H5921" SEÑOR, me|strong="H5921" llamarás Marido mío|strong="H5921" , y|strong="H5921" nunca más|strong="H5921" me|strong="H5921" lla­marás Baali.',NULL),
(@vid,@bid,2,17,'Porque|strong="H8033" quitaré de|strong="H5414" su boca los nombres de|strong="H5414" los Baales, y nunca más|strong="H6030" serán mentados por|strong="H5414" sus nombres.',NULL),
(@vid,@bid,2,18,'Y|strong="H3068" haré por|strong="H5750" ellos|strong="H1931" concierto en|strong="H5750" aquel|strong="H1931" tiempo|strong="H3117" con las bestias del campo, y con las aves del cielo, y con las serpientes de|strong="H5750" la|strong="H1931" tierra: y quebraré arco, y espada, y batalla de|strong="H5750" la|strong="H1931" tierra, y harélos dormir seguros.',NULL),
(@vid,@bid,2,19,'Y|strong="H3068" te desposaré conmigo para|strong="H5493" siempre; desposarte he conmigo en|strong="H5493" justicia, y juicio, y misericor­dia, y miseraciones.',NULL),
(@vid,@bid,2,20,'Y|strong="H3068" te|strong="H4480" desposaré conmigo|strong="H5973" en|strong="H4480" fe, y conocerás al|strong="H4480" SEÑOR.',NULL),
