(@vid,@bid,2,23,'Y|strong="H3068" la|strong="H1931" sembraré para|strong="H1961" mí|strong="H1961" en la|strong="H1931" tierra; y tendré|strong="H1961" misericordia de la|strong="H1931" que|strong="H1931" no|strong="H1961" obtuvo misericordia; y diré al que no|strong="H1961" era mi|strong="H1961" pueblo|strong="H1992" : Tú eres mi|strong="H1961" pueblo|strong="H1992" , y él|strong="H1931" dirá: Tú eres mi|strong="H1961" Dios|strong="H3068" .',NULL),
(@vid,@bid,3,1,'Y|strong="H3068" DÍJOME otra|strong="H5750" vez el|strong="H1121" SEÑOR|strong="H3068" : Ve|strong="H3212" , ama una mujer amada de|strong="H5750" su compañero|strong="H7453" , aunque adúltera|strong="H5003" , como|strong="H5750" el|strong="H1121" amor del SEÑOR|strong="H3068" para con los|strong="H1992" hijos|strong="H1121" de|strong="H5750" Israel|strong="H3478" ; los|strong="H1992" cuales miran|strong="H6437" a|strong="H3068" dioses ajenos, y aman frascos de|strong="H5750" vino|strong="H3212" .',NULL),
(@vid,@bid,3,2,'Compréla|strong="H3739" entonces para mí por quince|strong="H2568" dineros de|strong="H2568" plata|strong="H3701" , y un homer y medio de|strong="H2568" cebada|strong="H8184" ;',NULL),
(@vid,@bid,3,3,'Y|strong="H3068" díjele: Tú estarás|strong="H1961" por mía muchos|strong="H7227" días|strong="H3117" : no|strong="H3808" fornicarás|strong="H2181" , ni|strong="H3808" tomarás|strong="H1961" otro varón; así|strong="H1571" yo también|strong="H1571" estaré por ti.',NULL),
(@vid,@bid,3,4,'Porque|strong="H3588" muchos|strong="H7227" días|strong="H3117" estarán|strong="H3427" los|strong="H3427" hijos|strong="H1121" de|strong="H3588" Israel|strong="H3478" sin rey|strong="H4428" , y|strong="H3588" sin príncipe|strong="H8269" , y|strong="H3588" sin sacrificio|strong="H2077" , y|strong="H3588" sin esta|strong="H3427" ­tua, y|strong="H3588" sin efod, y|strong="H3588" sin terafim.',NULL),
(@vid,@bid,3,5,'Después volverán|strong="H7725" los|strong="H1121" hijos|strong="H1121" de|strong="H1121" Israel|strong="H3478" , y buscarán|strong="H1245" al|strong="H4428" SEÑOR|strong="H3068" su Dios|strong="H3068" , y a|strong="H3068" David|strong="H1732" su rey|strong="H4428" ; y temerán al|strong="H4428" SEÑOR|strong="H3068" y a|strong="H3068" su bondad|strong="H2898" en el|strong="H1121" fin de|strong="H1121" los|strong="H1121" días|strong="H3117" .',NULL),
(@vid,@bid,4,1,'OÍD|strong="H8085" palabra|strong="H1697" del|strong="H5973" SEÑOR|strong="H3068" , hijos|strong="H1121" de|strong="H3588" Israel|strong="H3478" , porque|strong="H3588" el|strong="H5973" SEÑOR|strong="H3068" pleitea con|strong="H5973" los|strong="H3427" moradores|strong="H3427" de|strong="H3588" la|strong="H3588" tierra; porque|strong="H3588" no|strong="H3588" hay verdad, ni|strong="H5973" misericordia|strong="H2617" , ni|strong="H5973" conocimiento|strong="H1847" de|strong="H3588" Dios|strong="H3068" en|strong="H5973" la|strong="H3588" tierra.',NULL),
(@vid,@bid,4,2,'Perjurar, y mentir, y matar, y hurtar y adulterar prevalecieron|strong="H6555" , y sangres|strong="H1818" se tocaron con|strong="H5060" sangres|strong="H1818" .',NULL),
(@vid,@bid,4,3,'Por|strong="H5921" lo|strong="H5921" cual, se|strong="H5921" enlutará la|strong="H5921" tierra, y|strong="H1571" extenuaráse todo|strong="H3605" morador|strong="H3427" de|strong="H5921" ella|strong="H5921" , con|strong="H5921" las|strong="H5921" bestias|strong="H2416" del|strong="H5921" campo|strong="H7704" , y|strong="H1571" las|strong="H5921" aves|strong="H5775" del|strong="H5921" cielo|strong="H8064" : y|strong="H1571" aun|strong="H1571" los|strong="H3427" peces del|strong="H5921" mar|strong="H3220" fallecerán.',NULL),
(@vid,@bid,4,4,'Ciertamente hombre no con­tienda ni reprenda|strong="H3198" a|strong="H3068" hombre, por­ que|strong="H5971" tu pueblo|strong="H5971" es como los que|strong="H5971" resisten al sacerdote|strong="H3548" .',NULL),
(@vid,@bid,4,5,'Caerás|strong="H3782" por tanto en|strong="H5973" el|strong="H5973" día|strong="H3117" , y|strong="H1571" caerá|strong="H3782" también|strong="H1571" contigo|strong="H5973" el|strong="H5973" profeta|strong="H5030" de|strong="H5973" noche|strong="H3915" ; y|strong="H1571" a|strong="H3068" tu madre talaré|strong="H1820" .',NULL),
(@vid,@bid,4,6,'Mi pueblo|strong="H5971" es|strong="H3588" destruido por|strong="H3588" falta de|strong="H3588" conocimiento|strong="H1847" : porque|strong="H3588" tú has desechado|strong="H3988" el|strong="H3588" conocimiento|strong="H1847" , yo|strong="H3588" también|strong="H1571" te|strong="H3588" desecharé|strong="H3988" a|strong="H3068" ti, para|strong="H3588" que|strong="H3588" no|strong="H1097" seas mi sacerdote: y|strong="H1571" pues|strong="H3588" que|strong="H3588" olvidaste|strong="H7911" la|strong="H1571" ley|strong="H8451" de|strong="H3588" tu Dios, también|strong="H1571" yo|strong="H3588" me|strong="H3588" olvidaré|strong="H7911" de|strong="H3588" tus hijos|strong="H1121" .',NULL),
(@vid,@bid,4,7,'Conforme a|strong="H3068" su grandeza|strong="H3519" así|strong="H3651" pecaron|strong="H2398" contra mí: trocaré|strong="H4171" su honra|strong="H3519" en afrenta|strong="H7036" .',NULL),
(@vid,@bid,4,8,'Comen del pecado|strong="H2403" de|strong="H5971" mi|strong="H5375" pue­blo, y en su maldad|strong="H5771" levantan|strong="H5375" su alma|strong="H5315" .',NULL),
(@vid,@bid,4,9,'Tal será|strong="H1961" el|strong="H5921" pueblo|strong="H5971" como|strong="H1961" el|strong="H5921" sacerdote|strong="H3548" : y|strong="H5921" visitaré|strong="H6485" sobre|strong="H5921" él|strong="H5921" sus caminos|strong="H1870" , y|strong="H5921" pagaréle conforme|strong="H5921" a|strong="H3068" sus obras|strong="H4611" .',NULL),
(@vid,@bid,4,10,'Y|strong="H3068" comerán, mas|strong="H3588" no|strong="H3808" se|strong="H3808" hartarán; fornicarán|strong="H2181" , mas|strong="H3588" no|strong="H3808" se|strong="H3808" aumen­tarán: porque|strong="H3588" dejaron|strong="H5800" de|strong="H3588" atender al SEÑOR|strong="H3068" .',NULL),
