(@vid,@bid,4,13,'Sobre|strong="H5921" las|strong="H5921" cabezas|strong="H7218" de|strong="H5921" los|strong="H5921" mon­tes sacrificaron|strong="H2076" , e|strong="H3068" incensaron sobre|strong="H5921" los|strong="H5921" collados|strong="H1389" , debajo|strong="H8478" de|strong="H5921" encinas, y|strong="H3588" álamos, y|strong="H3588" olmos que|strong="H3588" tuviesen buena|strong="H2896" sombra|strong="H6738" : por|strong="H5921" tanto|strong="H3651" , vuestras hijas|strong="H1323" fornicarán|strong="H2181" , y|strong="H3588" adulterarán vuestras nueras|strong="H3618" .',NULL),
(@vid,@bid,4,14,'No|strong="H3808" visitaré|strong="H6485" sobre|strong="H5921" vuestras hijas|strong="H1323" cuando|strong="H3588" fornicaren, ni|strong="H3808" sobre|strong="H5921" vuestras nueras|strong="H3618" cuando|strong="H3588" adultera|strong="H5003" ­ren: porque|strong="H3588" ellos|strong="H1992" ofrecen con|strong="H5973" las|strong="H1992" rameras|strong="H2181" , y|strong="H3588" con|strong="H5973" las|strong="H1992" malas mujeres|strong="H1323" sacrifican|strong="H2076" : por|strong="H5921" tanto|strong="H5921" , el|strong="H5921" pueblo|strong="H5971" sin|strong="H3808" entendimiento caerá|strong="H3832" .',NULL),
(@vid,@bid,4,15,'Si fornicares|strong="H2181" tú, Israel|strong="H3478" , a|strong="H3068" lo menos no peque Judá|strong="H3063" : y no entréis en Gilgal|strong="H1537" , ni subáis|strong="H5927" a|strong="H3068" Bet-aven; ni juréis|strong="H7650" , Vive|strong="H2416" el SEÑOR|strong="H3068" .',NULL),
(@vid,@bid,4,16,'Porque|strong="H3588" como|strong="H3588" becerra cerrera|strong="H5637" se apartó Israel|strong="H3478" : ¿ apacentarálos|strong="H7462" ahora|strong="H6258" el|strong="H3588" SEÑOR|strong="H3068" como|strong="H3588" a|strong="H3068" carne­ros en|strong="H3588" anchura?',NULL),
(@vid,@bid,4,17,'Efraím es dado a|strong="H3068" ídolos|strong="H6091" ; déjalo.',NULL),
