(@vid,@bid,13,1,'CUANDO Efraím hablaba|strong="H1696" , hubo temor; fue|strong="H1931" ensalzado|strong="H5375" en Israel|strong="H3478" ; mas|strong="H4191" pecó en Baal|strong="H1168" , y murió|strong="H4191" .',NULL),
(@vid,@bid,13,2,'Y|strong="H3068" ahora|strong="H6258" añadieron|strong="H3254" a|strong="H3068" su|strong="H1992" pecado|strong="H2398" , y de su|strong="H1992" plata|strong="H3701" se|strong="H1992" han hecho|strong="H6213" según su|strong="H1992" entendimiento|strong="H8394" , estatuas|strong="H4541" de fundición|strong="H4541" , ídolos|strong="H6091" , toda|strong="H3605" obra|strong="H4639" de artífices|strong="H2796" ; acerca de los|strong="H1992" cuales dicen a|strong="H3068" los|strong="H1992" hombres que|strong="H6258" sacrifi­can, que|strong="H6258" besen los|strong="H1992" becerros|strong="H5695" .',NULL),
