(@vid,@bid,2,9,'Irán|strong="H8264" por|strong="H1157" la ciudad|strong="H5892" , correrán|strong="H7323" por|strong="H1157" el muro|strong="H2346" , subirán|strong="H5927" por|strong="H1157" las casas|strong="H1004" , entrarán por|strong="H1157" las ventanas|strong="H2474" a|strong="H3068" manera de ladrones|strong="H1590" .',NULL),
(@vid,@bid,2,10,'Delante|strong="H6440" de|strong="H6440" él temblará la tie­rra, se estremecerán los cielos|strong="H8064" : el sol|strong="H8121" y la luna|strong="H3394" se oscurecerán, y las estrellas|strong="H3556" retraerán su resplandor|strong="H5051" .',NULL),
(@vid,@bid,2,11,'Y|strong="H3068" el|strong="H3588" SEÑOR|strong="H3068" dará|strong="H5414" su|strong="H3588" voz|strong="H6963" delante|strong="H6440" de|strong="H3588" su|strong="H3588" ejército|strong="H2426" : porque|strong="H3588" muchos|strong="H7227" son|strong="H3588" sus reales y|strong="H3588" fuertes|strong="H6099" , que|strong="H3588" ponen en|strong="H3588" efecto su|strong="H3588" palabra|strong="H1697" : porque|strong="H3588" grande|strong="H1419" es|strong="H3588" el|strong="H3588" día|strong="H3117" del SEÑOR|strong="H3068" , y|strong="H3588" muy|strong="H3966" terrible|strong="H3372" ; ¿ y|strong="H3588" quién|strong="H4310" lo|strong="H1697" podrá sufrir|strong="H3557" ?',NULL),
(@vid,@bid,2,12,'Por|strong="H5704" eso pues|strong="H6258" ahora|strong="H6258" , dice|strong="H5002" el|strong="H3605" SEÑOR|strong="H3068" , convertíos|strong="H7725" a|strong="H3068" mí con|strong="H1571" todo|strong="H3605" vuestro corazón|strong="H3824" , con|strong="H1571" ayuno|strong="H6685" y|strong="H1571" lloro|strong="H1065" y|strong="H1571" llanto|strong="H1065" .',NULL),
(@vid,@bid,2,13,'Y|strong="H3068" lacerad vuestro corazón|strong="H3824" , y|strong="H3588" no|strong="H3588" vuestras vestiduras; y|strong="H3588" convertí­ os|strong="H5921" al|strong="H5921" SEÑOR|strong="H3068" vuestro Dios|strong="H3068" ; por|strong="H5921" ­ que|strong="H3588" misericordioso|strong="H7349" es|strong="H1931" y|strong="H3588" clemen­ te|strong="H5921" , tardo para|strong="H5921" la|strong="H1931" ira, y|strong="H3588" grande|strong="H7227" en|strong="H5921" misericordia|strong="H2617" , y|strong="H3588" que|strong="H3588" se|strong="H1931" arrepiente del|strong="H5921" castigo|strong="H7451" .',NULL),
(@vid,@bid,2,14,'¿ Quién|strong="H4310" sabe|strong="H3045" si volverá|strong="H7725" y se|strong="H3045" apiadará, y dejará bendición|strong="H1293" tras de él|strong="H4310" , presente|strong="H4503" y libación|strong="H5262" para el|strong="H4310" SEÑOR|strong="H3068" Dios|strong="H3068" vuestro?',NULL),
(@vid,@bid,2,15,'Tocad|strong="H8628" trompeta|strong="H7782" en Sión|strong="H6726" , pregonad|strong="H6942" ayuno|strong="H6685" , llamad|strong="H7121" una asamblea solemne.',NULL),
(@vid,@bid,2,16,'Reunid el pueblo|strong="H5971" , santificad|strong="H6942" la reunión|strong="H6951" , juntad|strong="H6908" los viejos|strong="H2205" , con­gregad los niños|strong="H5768" y los que|strong="H5971" maman: salga|strong="H3318" de|strong="H5971" su cámara|strong="H2315" el novio, y de|strong="H5971" su tálamo|strong="H2646" la novia.',NULL),
(@vid,@bid,2,17,'Entre|strong="H5921" la|strong="H5921" entrada y|strong="H5921" el|strong="H5921" altar|strong="H4196" , llo­ren los|strong="H5921" sacerdotes|strong="H3548" , ministros|strong="H8334" del|strong="H5921" SEÑOR|strong="H3068" , y|strong="H5921" digan: Perdona, oh|strong="H4100" SEÑOR|strong="H3068" , a|strong="H3068" tu pueblo|strong="H5971" , y|strong="H5921" no|strong="H5921" pon|strong="H5414" ­gas en|strong="H5921" oprobio|strong="H2781" tu heredad|strong="H5159" , para|strong="H5921" que|strong="H4100" las|strong="H5921" gentes|strong="H1471" se|strong="H5921" enseñoreen de|strong="H5921" ella|strong="H5921" . ¿ Por|strong="H5921" qué|strong="H4100" han de|strong="H5921" decir entre|strong="H5921" los|strong="H5921" pueblos|strong="H5971" : Dónde|strong="H5921" está|strong="H5921" su Dios|strong="H3068" ?',NULL),
(@vid,@bid,2,18,'Y|strong="H3068" el|strong="H5921" SEÑOR|strong="H3068" celará|strong="H7065" su tierra, y|strong="H5921" perdonará|strong="H2550" su pueblo|strong="H5971" .',NULL),
(@vid,@bid,2,19,'Y|strong="H3068" responderá|strong="H6030" el SEÑOR|strong="H3068" , y dirá a|strong="H3068" su pueblo|strong="H5971" : He aquí|strong="H2005" yo os envío|strong="H7971" pan|strong="H1715" , y mosto|strong="H8492" , y aceite|strong="H3323" , y seréis saciados de|strong="H5750" ellos: y nunca|strong="H3808" más|strong="H5750" os pondré|strong="H5414" en|strong="H5750" oprobio|strong="H2781" entre|strong="H3808" las gentes|strong="H1471" .',NULL),
(@vid,@bid,2,20,'Y|strong="H3068" haré|strong="H6213" alejar de|strong="H5921" vosotros al|strong="H5921" ejército del|strong="H5921" norte, y|strong="H3588" echarélo en|strong="H5921" la|strong="H5921" tierra seca|strong="H6723" y|strong="H3588" desierta|strong="H8077" : su|strong="H3588" faz|strong="H6440" será|strong="H6213" hacia|strong="H6213" el|strong="H5921" mar|strong="H3220" oriental, y|strong="H3588" su|strong="H3588" fin al|strong="H5921" mar|strong="H3220" occidental|strong="H3220" , y|strong="H3588" exhalará su|strong="H3588" hedor; y|strong="H3588" subirá|strong="H5927" su|strong="H3588" pudrición, por|strong="H5921" ­ que|strong="H3588" hizo|strong="H6213" grandes|strong="H1431" cosas.',NULL),
(@vid,@bid,2,21,'Tierra, no|strong="H6213" temas|strong="H3372" ; alégrate|strong="H1523" y|strong="H3588" gózate|strong="H8055" : porque|strong="H3588" el|strong="H3588" SEÑOR|strong="H3068" ha de|strong="H3588" hacer|strong="H6213" grandes|strong="H1431" cosas.',NULL),
(@vid,@bid,2,22,'Animales del campo|strong="H7704" , no|strong="H3588" temáis|strong="H3372" ; porque|strong="H3588" los|strong="H3588" pastos del desierto|strong="H4057" reverdecerán|strong="H1876" , porque|strong="H3588" los|strong="H3588" árboles|strong="H6086" llevarán|strong="H5375" su|strong="H3588" fruto|strong="H6529" , la|strong="H3588" higuera y|strong="H3588" la|strong="H3588" vid|strong="H1612" darán|strong="H5414" sus frutos|strong="H6529" .',NULL),
(@vid,@bid,2,23,'Vosotros también, hijos|strong="H1121" de|strong="H3588" Sión|strong="H6726" , alegraos|strong="H8055" y|strong="H3588" gozaos en|strong="H3588" el|strong="H3588" SEÑOR|strong="H3068" vuestro Dios|strong="H3068" ; porque|strong="H3588" os ha dado|strong="H5414" la|strong="H3588" primera|strong="H7223" lluvia|strong="H1653" arregla­damente, y|strong="H3588" hará|strong="H5414" descender sobre vosotros lluvia|strong="H1653" temprana|strong="H4175" y|strong="H3588" tardía|strong="H4456" como al principio|strong="H5414" .',NULL),
(@vid,@bid,2,24,'Y|strong="H3068" las eras se henchirán|strong="H4390" de trigo|strong="H1250" , y los lagares rebosarán de vino|strong="H8492" y aceite|strong="H3323" .',NULL),
(@vid,@bid,2,25,'Y|strong="H3068" os restituiré los años|strong="H8141" que comió la oruga, la langosta, el pulgón, y el revoltón; mi grande|strong="H1419" ejército|strong="H2428" que envié|strong="H7971" contra voso­tros.',NULL),
(@vid,@bid,2,26,'Y|strong="H3068" comeréis hasta saciaros, y alabaréis el|strong="H5973" nombre|strong="H8034" del|strong="H5973" SEÑOR|strong="H3068" vuestro Dios|strong="H3068" , el|strong="H5973" cual|strong="H5973" hizo|strong="H6213" mara­villas con|strong="H5973" vosotros|strong="H5973" : y nunca|strong="H3808" jamás|strong="H5769" será|strong="H3808" mi pueblo|strong="H5971" avergonza­do.',NULL),
(@vid,@bid,2,27,'Y|strong="H3068" conoceréis|strong="H3045" que|strong="H3588" en|strong="H3588" medio|strong="H7130" de|strong="H3588" Israel|strong="H3478" estoy yo|strong="H3588" , y|strong="H3588" que|strong="H3588" yo|strong="H3588" soy el|strong="H3588" SEÑOR|strong="H3068" vuestro Dios|strong="H3068" , y|strong="H3588" no|strong="H3808" hay|strong="H5750" otro|strong="H5750" : y|strong="H3588" mi pueblo|strong="H5971" nunca|strong="H3808" jamás|strong="H5769" será|strong="H3808" avergonzado.',NULL),
(@vid,@bid,2,28,'Y|strong="H3068" será que después de esto, derramaré mi espíritu sobre toda carne, y profetizarán vuestros hijos y vuestras hijas; vuestros viejos soñarán sueños, y vuestros mancebos verán visiones.',NULL),
(@vid,@bid,2,29,'Y|strong="H3068" aun también sobre los sier­vos y sobre las siervas derramaré mi espíritu en aquellos días.',NULL),
(@vid,@bid,2,30,'Y|strong="H3068" mostraré prodigios en los cielos y en la tierra, sangre, y fuego, y columnas de humo.',NULL),
(@vid,@bid,2,31,'El sol se tornará en tinieblas, y la luna en sangre, antes que venga el día grande y espantoso del SEÑOR.',NULL),
(@vid,@bid,2,32,'Y|strong="H3068" será que cualquiera que invocare el nombre del SEÑOR, será salvo: porque en el monte de Sión y en Jerusalem habrá salva­ción, como el SEÑOR ha dicho, y en el remanente, al cual el SEÑOR habrá llamado.',NULL),
(@vid,@bid,3,1,'PORQUE|strong="H5921" he aquí, que|strong="H5921" en|strong="H5921" aquellos|strong="H3605" días, y|strong="H5921" en|strong="H5921" aquel|strong="H3605" tiempo en|strong="H5921" que|strong="H5921" haré tornar la|strong="H5921" cautividad de|strong="H5921" Judá y|strong="H5921" de|strong="H5921" Jerusalem,',NULL),
(@vid,@bid,3,2,'Juntaré todas las|strong="H1992" naciones, y|strong="H1571" haré­ las|strong="H1992" descender al|strong="H5921" valle de|strong="H5921" Josafat, y|strong="H1571" allí entraré en|strong="H5921" juicio con|strong="H5921" ellos|strong="H1992" a|strong="H3068" causa de|strong="H5921" mi|strong="H5921" pueblo|strong="H1992" , y|strong="H1571" de|strong="H5921" Israel mi|strong="H5921" heredad, a|strong="H3068" los|strong="H1992" cuales espar­cieron entre|strong="H5921" las|strong="H1992" naciones, y|strong="H1571" par­tieron mi|strong="H5921" tierra:',NULL),
(@vid,@bid,3,3,'Y|strong="H3068" echaron suertes sobre mi pueblo, y a|strong="H3068" los niños dieron|strong="H5414" por|strong="H5414" una ramera, y vendieron las niñas por|strong="H5414" vino para|strong="H5414" beber.',NULL),
(@vid,@bid,3,4,'Y|strong="H3068" también, ¿ qué|strong="H3117" tengo yo con vosotras, Tiro y Sidón, y todos los términos de|strong="H6440" Filistea? ¿Queréis vengaros de|strong="H6440" mí? Y|strong="H3068" si|strong="H6440" de|strong="H6440" mí os vengáis, bien pronto haré yo recaer la paga sobre vuestra cabeza.',NULL),
(@vid,@bid,3,5,'Porque|strong="H3588" habéis llevado mi|strong="H3389" plata y|strong="H3588" mi|strong="H3389" oro, y|strong="H3588" mis cosas preciosas y|strong="H3588" hermosas metisteis en|strong="H3588" vuestros templos:',NULL),
(@vid,@bid,3,6,'Y|strong="H3068" vendisteis los hijos de Judá y los hijos de Jerusalem a|strong="H3068" los hijos de los griegos, por alejarlos de sus términos.',NULL),
(@vid,@bid,3,7,'He aquí los levantaré yo del lugar donde los vendisteis, y vol­veré vuestra paga sobre vuestra cabeza:',NULL),
(@vid,@bid,3,8,'Y|strong="H3068" venderé vuestros hijos y vuestras hijas en la mano de los hijos de Judá, y ellos los vende­rán a|strong="H3068" los sabeos, nación aparta­da; porque el SEÑOR ha habla­do.',NULL),
(@vid,@bid,3,9,'Pregonad esto entre los gentiles, proclamad guerra, despertad a|strong="H3068" los valientes, lléguense, vengan todos los hombres de guerra.',NULL),
(@vid,@bid,3,10,'Haced espadas de vuestros azadones, lanzas de vuestras hoces; diga el flaco: Fuerte soy.',NULL),
(@vid,@bid,3,11,'Juntaos y venid, gentes todas de alrededor, y congregaos: haz venir allí, oh SEÑOR, tus fuer­tes.',NULL),
(@vid,@bid,3,12,'Las gentes se despierten, y suban al valle de Josafat: por­que allí me sentaré para juzgar todas las gentes de alrededor.',NULL),
(@vid,@bid,3,13,'Echad la hoz, porque la mies está ya madura. Venid, descen­ded; porque el lagar está lleno, rebosan las lagaretas: porque mucha es la maldad de ellos.',NULL),
(@vid,@bid,3,14,'Muchos pueblos en el valle de la decisión: porque cercano está el día del SEÑOR en el valle de la decisión.',NULL),
(@vid,@bid,3,15,'El sol y la luna se oscurece­rán, y las estrellas retraerán su resplandor.',NULL),
(@vid,@bid,3,16,'Y|strong="H3068" el SEÑOR rugirá desde Sión, y dará su voz desde Jerusalem, y temblarán los cielos y la tierra: mas el SEÑOR será la esperanza de su pueblo, y la for­taleza de los hijos de Israel.',NULL),
(@vid,@bid,3,17,'Y|strong="H3068" conoceréis que yo soy el SEÑOR vuestro Dios, que habi­to en Sión, monte de mi santidad: y será Jerusalem santa, y extra­ños no pasarán más por ella.',NULL),
(@vid,@bid,3,18,'Y|strong="H3068" será en aquel tiempo, que los montes destilarán mosto, y los collados fluirán leche, y por todos los arroyos de Judá corre­rán aguas: y saldrá una fuente de la casa del SEÑOR, y regará el valle de Sitim.',NULL),
(@vid,@bid,3,19,'Egipto será destruído, y Edom será vuelto en asolado desierto, por la injuria hecha a|strong="H3068" los hijos de Judá: porque derra­maron en su tierra la sangre ino­cente.',NULL),
(@vid,@bid,3,20,'Mas Judá para siempre será habitada, y Jerusalem en genera­ción y generación.',NULL),
(@vid,@bid,3,21,'Y|strong="H3068" limpiaré la sangre de los que no limpié; y el SEÑOR morará en Sión.',NULL);
INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'LAS|strong="H5921" palabras|strong="H1697" de|strong="H5921" Amós|strong="H5986" , que|strong="H5921" fue|strong="H1961" entre|strong="H5921" los|strong="H1121" pastores de|strong="H5921" Tecoa, las|strong="H5921" cuales vio|strong="H2372" acerca|strong="H5921" de|strong="H5921" Israel|strong="H3478" en|strong="H5921" días|strong="H3117" de|strong="H5921" Uzías rey|strong="H4428" de|strong="H5921" Judá|strong="H3063" , y|strong="H5921" en|strong="H5921" días|strong="H3117" de|strong="H5921" Jeroboam|strong="H3379" hijo|strong="H1121" de|strong="H5921" Joas|strong="H3101" rey|strong="H4428" de|strong="H5921" Israel|strong="H3478" , dos|strong="H3117" años|strong="H8141" antes|strong="H6440" del|strong="H5921" terremoto.',NULL),
(@vid,@bid,1,2,'Y|strong="H3068" dijo: el SEÑOR|strong="H3068" rugirá|strong="H7580" desde Sión|strong="H6726" , y dará|strong="H5414" su voz|strong="H6963" desde Jerusalem|strong="H3389" ; y las estancias de|strong="H5414" los pastores|strong="H7462" se enlutarán, y secaráse la cumbre|strong="H7218" del Carmelo.',NULL),
(@vid,@bid,1,3,'Así|strong="H3541" ha|strong="H3541" dicho el|strong="H5921" SEÑOR|strong="H3068" : Por|strong="H5921" tres|strong="H7969" pecados|strong="H6588" de|strong="H5921" Damasco|strong="H1834" , y|strong="H5921" por|strong="H5921" el|strong="H5921" cuarto, no|strong="H3808" desviaré|strong="H7725" su castigo; porque|strong="H5921" trillaron a|strong="H3068" Galaad|strong="H1568" con|strong="H5921" tri­llos de|strong="H5921" hierro|strong="H1270" .',NULL),
(@vid,@bid,1,4,'Y|strong="H3068" meteré|strong="H7971" fuego en la casa|strong="H1004" de Hazael|strong="H2371" , y consumirá los palacios de Ben-hadad.',NULL),
(@vid,@bid,1,5,'Y|strong="H3068" quebraré|strong="H7665" la barra de|strong="H5971" Damasco|strong="H1834" , y cortaré|strong="H3772" a|strong="H3068" los|strong="H3427" moradores|strong="H3427" del valle de|strong="H5971" Avén, y al que|strong="H5971" segura el|strong="H3427" cetro|strong="H7626" de|strong="H5971" la casa|strong="H1004" de|strong="H5971" Edén: y el|strong="H3427" pueblo|strong="H5971" de|strong="H5971" Siria será|strong="H7665" trasportado|strong="H1540" a|strong="H3068" cautiverio en Kir, dice el|strong="H3427" SEÑOR|strong="H3068" .',NULL),
(@vid,@bid,1,6,'Así|strong="H3541" ha|strong="H3541" dicho el|strong="H5921" SEÑOR|strong="H3068" : Por|strong="H5921" tres|strong="H7969" pecados|strong="H6588" de|strong="H5921" Gaza|strong="H5804" , y|strong="H5921" por|strong="H5921" el|strong="H5921" cuarto, no|strong="H3808" desviaré|strong="H7725" su castigo; porque|strong="H5921" llevó cautiva toda|strong="H5921" la|strong="H5921" cau­tividad, para|strong="H5921" entregarlos a|strong="H3068" Edom.',NULL),
(@vid,@bid,1,7,'Y|strong="H3068" meteré|strong="H7971" fuego en el muro|strong="H2346" de Gaza|strong="H5804" , y quemará sus palacios.',NULL),
(@vid,@bid,1,8,'Y|strong="H3068" talaré|strong="H3772" los|strong="H3427" moradores|strong="H3427" de|strong="H5921" Azoto, y|strong="H5921" los|strong="H3427" gobernadores de|strong="H5921" Ascalón: y|strong="H5921" tornaré|strong="H7725" mi|strong="H5921" mano|strong="H3027" sobre|strong="H5921" Ecrón|strong="H6138" , y|strong="H5921" las|strong="H5921" reliquias|strong="H7611" de|strong="H5921" los|strong="H3427" filisteos|strong="H6430" perecerán, ha dicho el|strong="H5921" Señor DIOS|strong="H3069" .',NULL),
(@vid,@bid,1,9,'Así|strong="H3541" ha|strong="H3541" dicho el|strong="H5921" SEÑOR|strong="H3068" : Por|strong="H5921" tres|strong="H7969" pecados|strong="H6588" de|strong="H5921" Tiro|strong="H6865" , y|strong="H5921" por|strong="H5921" el|strong="H5921" cuarto, no|strong="H3808" desviaré|strong="H7725" su castigo; porque|strong="H5921" entregaron|strong="H5462" la|strong="H5921" cautividad entera a|strong="H3068" Edom, y|strong="H5921" no|strong="H3808" se|strong="H5921" acordaron del|strong="H5921" concierto|strong="H1285" de|strong="H5921" hermanos.',NULL),
(@vid,@bid,1,10,'Y|strong="H3068" meteré|strong="H7971" fuego en el muro|strong="H2346" de Tiro|strong="H6865" , y consumirá sus palacios.',NULL),
(@vid,@bid,1,11,'Así|strong="H3541" ha|strong="H3541" dicho el|strong="H5921" SEÑOR|strong="H3068" : Por|strong="H5921" tres|strong="H7969" pecados|strong="H6588" de|strong="H5921" Edom, y|strong="H5921" por|strong="H5921" el|strong="H5921" cuarto, no|strong="H3808" desviaré|strong="H7725" su castigo; porque|strong="H5921" persiguió|strong="H7291" a|strong="H3068" espada|strong="H2719" a|strong="H3068" su hermano, y|strong="H5921" rompió sus conmise­raciones; y|strong="H5921" con|strong="H5921" su furor le|strong="H5921" ha|strong="H3541" robado siempre|strong="H5703" , y|strong="H5921" ha|strong="H3541" perpetua­mente guardado|strong="H8104" el|strong="H5921" enojo.',NULL),
(@vid,@bid,1,12,'Y|strong="H3068" meteré|strong="H7971" fuego en Temán|strong="H8487" , y consumirá los palacios de Bosra|strong="H1224" .',NULL),
