(@vid,@bid,1,15,'Porque|strong="H3588" cercano|strong="H7138" está|strong="H5921" el|strong="H5921" día|strong="H3117" del|strong="H5921" SEÑOR|strong="H3068" sobre|strong="H5921" todas|strong="H3605" las|strong="H5921" gentes|strong="H1471" : como|strong="H3588" tú|strong="H6213" hiciste|strong="H6213" se|strong="H5921" hará|strong="H6213" contigo|strong="H5921" : tu|strong="H6213" galardón volverá|strong="H7725" sobre|strong="H5921" tu|strong="H6213" cabeza|strong="H7218" .',NULL),
