INSERT IGNORE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'CARGA|strong="H4853" de Nínive|strong="H5210" . Libro|strong="H5612" de la visión|strong="H2377" de Nahum, el elcosita.',NULL),
