(@vid,@bid,1,1,'CARGA|strong="H4853" de|strong="H1697" la palabra|strong="H1697" del SEÑOR|strong="H3068" contra|strong="H3478" Israel|strong="H3478" , por|strong="H1697" mano|strong="H3027" de|strong="H1697" Malaquías.',NULL),
(@vid,@bid,1,2,'Yo os he amado, dice|strong="H5002" el SEÑOR|strong="H3068" ; y dijisteis: ¿En qué|strong="H4100" nos|strong="H4100" amaste? ¿ No|strong="H3808" era Esaú|strong="H6215" hermano de Jacob|strong="H3290" , dice|strong="H5002" el SEÑOR|strong="H3068" , y amé a|strong="H3068" Jacob|strong="H3290" ,',NULL),
(@vid,@bid,1,3,'Y|strong="H3068" a|strong="H3068" Esaú|strong="H6215" aborrecí|strong="H8130" , y torné sus montes|strong="H2022" en asolamiento|strong="H8077" , y su posesión|strong="H5159" para los dragones del desierto|strong="H4057" ?',NULL),
(@vid,@bid,1,4,'Cuando|strong="H3588" Edom dijere: Nos hemos empobrecido, mas|strong="H3588" torne­mos a|strong="H3068" edificar|strong="H1129" lo|strong="H5704" arruinado; así|strong="H3541" ha|strong="H3541" dicho el|strong="H3588" SEÑOR|strong="H3068" de|strong="H3588" los|strong="H1992" ejérci­tos: Ellos|strong="H1992" edificarán|strong="H1129" , y|strong="H3588" yo|strong="H3588" des­truiré: y|strong="H3588" les|strong="H1992" llamarán|strong="H7121" provincia de|strong="H3588" impiedad|strong="H7564" , y|strong="H3588" pueblo|strong="H5971" contra quien el|strong="H3588" SEÑOR|strong="H3068" se|strong="H1992" airó para|strong="H5704" siempre|strong="H5769" .',NULL),
(@vid,@bid,1,5,'Y|strong="H3068" vuestros ojos|strong="H5869" lo|strong="H5921" verán|strong="H7200" , y|strong="H5921" diréis: Sea el|strong="H5921" SEÑOR|strong="H3068" engrandecido|strong="H1431" sobre|strong="H5921" la|strong="H5921" provincia de|strong="H5921" Israel|strong="H3478" .',NULL),
(@vid,@bid,1,6,'El|strong="H1121" hijo|strong="H1121" honra|strong="H3513" a|strong="H3068" su padre, y|strong="H3519" el|strong="H1121" sier­vo a|strong="H3068" su señor|strong="H3068" : si pues|strong="H4100" soy yo padre, ¿ Qué|strong="H4100" es de|strong="H1121" mi honra|strong="H3513" ? y|strong="H3519" si soy señor|strong="H3068" , ¿ qué|strong="H4100" es de|strong="H1121" mi temor|strong="H4172" ?, dice el|strong="H1121" SEÑOR|strong="H3068" de|strong="H1121" los|strong="H1121" ejércitos|strong="H6635" a|strong="H3068" vosotros, oh|strong="H1121" sacerdotes|strong="H3548" , que|strong="H4100" menospreciáis mi nombre|strong="H8034" . Y|strong="H3068" decís: ¿En qué|strong="H4100" hemos menospre­ciado tu nombre|strong="H8034" ?',NULL),
(@vid,@bid,1,7,'Que|strong="H4100" ofrecéis|strong="H5066" sobre|strong="H5921" mi|strong="H5921" altar|strong="H4196" pan|strong="H3899" inmundo|strong="H1351" . Y|strong="H3068" dijisteis: ¿ En|strong="H5921" qué|strong="H4100" te|strong="H5921" hemos amancillado? En|strong="H5921" que|strong="H4100" decís: La|strong="H1931" mesa|strong="H7979" del|strong="H5921" SEÑOR|strong="H3068" es despreciable.',NULL),
(@vid,@bid,1,8,'Y|strong="H3068" cuando|strong="H3588" ofrecéis|strong="H5066" el|strong="H3588" animal ciego|strong="H5787" para|strong="H3588" sacrificar, ¿ No|strong="H3588" es malo|strong="H7451" ? asimismo cuando|strong="H3588" ofrecéis|strong="H5066" el|strong="H3588" cojo|strong="H6455" o|strong="H3068" el|strong="H3588" enfermo|strong="H2470" , ¿ no|strong="H3588" es malo|strong="H7451" ? Preséntalo|strong="H7126" pues|strong="H3588" a|strong="H3068" tu gobernador|strong="H6346" : ¿acaso se agradará de|strong="H3588" ti, o|strong="H3068" le serás acepto? dice el|strong="H3588" SEÑOR|strong="H3068" de|strong="H3588" los|strong="H3588" ejércitos|strong="H6635" .',NULL),
(@vid,@bid,1,9,'Ahora|strong="H6258" pues|strong="H4994" , orad|strong="H2470" a|strong="H3068" la|strong="H2063" faz|strong="H6440" de|strong="H4480" Dios|strong="H3068" que|strong="H4480" tenga|strong="H1961" piedad de|strong="H4480" noso­tros: esto|strong="H2063" de|strong="H4480" vuestra|strong="H1961" mano|strong="H3027" vino|strong="H1961" : ¿Le seréis|strong="H1961" agradables? dice el SEÑOR|strong="H3068" de|strong="H4480" los|strong="H1961" ejércitos|strong="H6635" .',NULL),
(@vid,@bid,1,10,'¿ Quién|strong="H4310" también|strong="H1571" hay de vosotros que|strong="H4310" cierre las puertas|strong="H1817" en vano ? Ni|strong="H3808" encendéis fuego en mi altar|strong="H4196" por|strong="H3027" nada|strong="H3808" . Yo no|strong="H3808" tengo placer en vosotros, dice el|strong="H4310" SEÑOR|strong="H3068" de los ejércitos|strong="H6635" , ni|strong="H3808" de vuestra mano|strong="H3027" aceptaré ofrenda|strong="H4503" .',NULL),
(@vid,@bid,1,11,'Porque|strong="H3588" desde|strong="H5704" donde|strong="H8034" el|strong="H3588" sol|strong="H8121" nace|strong="H4217" hasta|strong="H5704" donde|strong="H8034" se pone, es grande|strong="H1419" mi nombre|strong="H8034" entre|strong="H3588" los|strong="H3605" gentiles; y|strong="H3588" en|strong="H5704" todo|strong="H3605" lugar|strong="H4725" se ofrece|strong="H5066" incienso a|strong="H3068" mi nombre|strong="H8034" , y|strong="H3588" ofrenda|strong="H4503" pura|strong="H2889" : porque|strong="H3588" grande|strong="H1419" es mi nombre|strong="H8034" entre|strong="H3588" las gentes|strong="H1471" , dice el|strong="H3588" SEÑOR|strong="H3068" de|strong="H3588" los|strong="H3605" ejércitos|strong="H6635" .',NULL),
