(@vid,@bid,2,13,'Y|strong="H3068" esta|strong="H2063" otra|strong="H5750" vez haréis|strong="H6213" cubrir|strong="H3680" el|strong="H6213" altar|strong="H4196" del|strong="H4196" SEÑOR|strong="H3068" de|strong="H5750" lágrimas|strong="H1832" , de|strong="H5750" llanto|strong="H1065" , y de|strong="H5750" clamor; así|strong="H2063" que|strong="H3027" no|strong="H6213" miraré|strong="H6437" más|strong="H5750" a|strong="H3068" presente|strong="H4503" , para acep­tarlo con gusto de|strong="H5750" vuestra|strong="H2063" mano|strong="H3027" .',NULL),
(@vid,@bid,2,14,'Mas|strong="H3588" diréis: ¿ Por|strong="H5921" qué|strong="H3588" ? Porque|strong="H3588" el|strong="H1931" SEÑOR|strong="H3068" ha atestiguado entre|strong="H5921" ti|strong="H5921" y|strong="H3588" la|strong="H1931" esposa de|strong="H5921" tu mocedad|strong="H5271" , contra|strong="H5921" la|strong="H1931" cual|strong="H4100" tú has sido desleal, siendo ella|strong="H1931" tu compañera|strong="H2278" , y|strong="H3588" la|strong="H1931" esposa de|strong="H5921" tu pacto|strong="H1285" .',NULL),
(@vid,@bid,2,15,'Pues|strong="H4100" qué|strong="H4100" ¿ No|strong="H3808" hizo|strong="H6213" él|strong="H6213" uno solo aunque|strong="H3808" tenía la|strong="H8104" abundancia del espíritu|strong="H7307" ? ¿ Y|strong="H3068" por|strong="H4100" qué|strong="H4100" uno? Para que|strong="H4100" procurara una simiente|strong="H2233" de Dios. Guardaos|strong="H8104" pues|strong="H4100" en vuestros espíritus|strong="H7307" , y contra la|strong="H8104" esposa de vuestra mocedad|strong="H5271" no|strong="H3808" seáis deslea­les.',NULL),
(@vid,@bid,2,16,'Porque|strong="H3588" el|strong="H5921" SEÑOR|strong="H3068" , el|strong="H5921" Dios|strong="H3068" de|strong="H5921" Israel|strong="H3478" ha|strong="H3808" dicho que|strong="H3588" él|strong="H5921" aborrece|strong="H8130" que|strong="H3588" sea repudiada; y|strong="H3588" cubra la|strong="H5921" iniquidad|strong="H2555" con|strong="H5921" su|strong="H3588" vestidura, dijo el|strong="H5921" SEÑOR|strong="H3068" de|strong="H5921" los|strong="H5921" ejércitos|strong="H6635" . Guardaos|strong="H8104" pues|strong="H3588" en|strong="H5921" vuestros espíritus|strong="H7307" , y|strong="H3588" no|strong="H3808" seáis desleales.',NULL),
(@vid,@bid,2,17,'Habéis hecho|strong="H6213" cansar al SEÑOR|strong="H3068" con vuestras|strong="H1697" palabras|strong="H1697" . Y|strong="H3068" diréis: ¿En qué|strong="H4100" le hemos cansa­do? Cuando|strong="H4100" decís: Cualquiera|strong="H3605" que|strong="H4100" mal|strong="H7451" hace|strong="H6213" agrada|strong="H2896" al SEÑOR|strong="H3068" , y en los|strong="H3605" tales toma contenta­miento: de|strong="H1697" otra|strong="H6213" manera|strong="H1697" , ¿ Dónde|strong="H1931" está el|strong="H1931" Dios|strong="H3068" de|strong="H1697" juicio|strong="H4941" ?',NULL),
(@vid,@bid,3,1,'HE aquí|strong="H2009" , yo|strong="H2009" enviaré|strong="H7971" mi|strong="H2009" men- sajero, el cual preparará el camino|strong="H1870" delante|strong="H6440" de|strong="H6440" mí|strong="H2009" : y repentinamente|strong="H6597" vendrá a|strong="H3068" su templo|strong="H1964" el SEÑOR|strong="H3068" a|strong="H3068" quien buscáis|strong="H1245" ; es decir, y el ángel|strong="H4397" del pacto|strong="H1285" , a|strong="H3068" quien deseáis|strong="H2655" vosotros. He aquí|strong="H2009" viene, ha dicho el SEÑOR|strong="H3068" de|strong="H6440" los ejércitos|strong="H6635" .',NULL),
(@vid,@bid,3,2,'¿ Pero|strong="H3588" quién|strong="H4310" podrá soportar el|strong="H1931" día|strong="H3117" de|strong="H3588" su|strong="H1931" venida? y|strong="H3588" ¿ quién|strong="H4310" se|strong="H1931" parará|strong="H5975" cuando|strong="H3588" él|strong="H1931" aparezca|strong="H7200" ? Porque|strong="H3588" él|strong="H1931" es|strong="H1931" como|strong="H3588" fuego purificador|strong="H6884" , y|strong="H3588" como|strong="H3588" jabón|strong="H1287" de|strong="H3588" lavadores.',NULL),
(@vid,@bid,3,3,'Y|strong="H3068" él|strong="H1121" se|strong="H1961" sentará como refinador y purificador|strong="H6884" de|strong="H1121" plata|strong="H3701" : y él|strong="H1121" purificará los|strong="H3427" hijos|strong="H1121" de|strong="H1121" Leví|strong="H3878" , los|strong="H3427" afinará como|strong="H1961" a|strong="H3068" oro|strong="H2091" y como|strong="H1961" a|strong="H3068" plata|strong="H3701" ; y ofrecerán al SEÑOR|strong="H3068" ofrenda|strong="H4503" con justicia|strong="H6666" .',NULL),
(@vid,@bid,3,4,'Y|strong="H3068" será agradable al SEÑOR|strong="H3068" la ofrenda|strong="H4503" de Judá|strong="H3063" y de Jerusalem|strong="H3389" , como en los días|strong="H3117" pasados|strong="H5769" , y como en los años|strong="H8141" antiguos|strong="H5769" .',NULL),
(@vid,@bid,3,5,'Y|strong="H3068" llegarme he a|strong="H3068" vosotros a|strong="H3068" juicio|strong="H4941" : y seré|strong="H1961" pronto|strong="H4116" testigo|strong="H5707" contra|strong="H1961" los|strong="H1961" hechiceros y adúlteros; y contra|strong="H1961" los|strong="H1961" que|strong="H3808" juran mentira|strong="H8267" , y los|strong="H1961" que|strong="H3808" detienen el salario|strong="H7939" del jornalero, de|strong="H3372" la viuda, y del huérfano|strong="H3490" , y los|strong="H1961" que|strong="H3808" privan de su derecho al extranjero|strong="H1616" , no|strong="H3808" teniendo temor|strong="H3372" de|strong="H3372" mí|strong="H1961" , dice el SEÑOR|strong="H3068" de|strong="H3372" los|strong="H1961" ejércitos|strong="H6635" .',NULL),
(@vid,@bid,3,6,'Porque|strong="H3588" yo|strong="H3588" el|strong="H3588" SEÑOR|strong="H3068" , no|strong="H3808" me|strong="H3588" mudo; y|strong="H3588" así|strong="H3588" vosotros, hijos|strong="H1121" de|strong="H3588" Jacob|strong="H3290" , no|strong="H3808" habéis sido consumi­dos.',NULL),
(@vid,@bid,3,7,'Desde los días|strong="H3117" de vuestros padres os habéis apartado de mis ordenanzas|strong="H2706" , y no|strong="H3808" las guardasteis|strong="H8104" . Tornaos|strong="H7725" a|strong="H3068" mí, y yo me tornaré|strong="H7725" a|strong="H3068" vosotros, ha|strong="H3808" dicho el SEÑOR|strong="H3068" de los ejércitos|strong="H6635" . Mas|strong="H3808" dijisteis: ¿ En|strong="H5493" qué|strong="H4100" hemos de tornar|strong="H7725" ?',NULL),
(@vid,@bid,3,8,'¿ Robará|strong="H6906" el|strong="H3588" hombre a|strong="H3068" Dios? Pues|strong="H3588" vosotros me|strong="H3588" habéis robado. Y|strong="H3068" dijisteis: ¿ En|strong="H3588" qué|strong="H3588" te|strong="H3588" hemos robado? En|strong="H3588" los|strong="H3588" diezmos y|strong="H3588" las ofrendas|strong="H8641" .',NULL),
(@vid,@bid,3,9,'Malditos sois con maldición|strong="H3994" , porque vosotros, la|strong="H3605" nación|strong="H1471" toda|strong="H3605" , me habéis robado.',NULL),
(@vid,@bid,3,10,'Traed todos|strong="H3605" los|strong="H3605" diezmos al|strong="H5704" alfolí|strong="H1004" , para|strong="H5704" que|strong="H3808" haya|strong="H1961" alimento|strong="H2964" en|strong="H5704" mi|strong="H1961" casa|strong="H1004" ; y|strong="H5704" probadme ahora|strong="H4994" en|strong="H5704" esto|strong="H2063" , dice el|strong="H3605" SEÑOR|strong="H3068" de|strong="H5704" los|strong="H3605" ejércitos|strong="H6635" , si|strong="H3808" no|strong="H3808" os|strong="H5704" abriré|strong="H6605" las ventanas del cielo|strong="H8064" , y|strong="H5704" verteré sobre|strong="H1961" vosotros bendición|strong="H1293" hasta|strong="H5704" que|strong="H3808" no|strong="H3808" haya lugar suficiente para recibirla .',NULL),
